(365828,40648,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a fait tout ce trajet en ... juste pour un phare ! Complètement obsédée !'::text,'train'::text,'le train'::text,'un train'::text,'Elle a fait tout ce trajet en train juste pour un phare ! Complètement obsédée !'::text),
