(382671,42519,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jaj, ne! Fogadok, hogy az egész ház másodpercek alatt romhalmazzá ...!'::text,'válik'::text,'fog válni'::text,'éppen válik'::text,'Jaj, ne! Fogadok, hogy az egész ház másodpercek alatt romhalmazzá válik!'::text),
(382674,42520,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Bagger eine alte Ziegelwand trifft, ...'::text,'zerfällt die Wand zu Schutt'::text,'zerfiel die Wand zu Schutt'::text,'wird die Wand zu Schutt zerfallen'::text,'Wenn ein Bagger eine alte Ziegelwand trifft, zerfällt die Wand zu Schutt.'::text),
(382678,42520,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо екскаватор б''є в стару цегляну стіну, стіна ... на уламки.'::text,'розсипається'::text,'розсипалася'::text,'розсиплеться'::text,'Якщо екскаватор б''є в стару цегляну стіну, стіна розсипається на уламки.'::text),
(382677,42520,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si una excavadora golpea un viejo muro de ladrillo, el muro ... en escombros.'::text,'se deshace'::text,'se deshizo'::text,'se deshará'::text,'Si una excavadora golpea un viejo muro de ladrillo, el muro se deshace en escombros.'::text),
(382676,42520,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si une pelleteuse heurte un vieux mur de briques, le mur ... en gravats.'::text,'s''effondre'::text,'s''est effondré'::text,'s''effondrera'::text,'Si une pelleteuse heurte un vieux mur de briques, le mur s''effondre en gravats.'::text),
(382679,42520,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir ekskavatör eski bir tuğla duvara çarparsa, duvar enkaza ...'::text,'döner'::text,'döndü'::text,'dönecek'::text,'Bir ekskavatör eski bir tuğla duvara çarparsa, duvar enkaza döner.'::text),
(382680,42520,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy markoló nekimegy egy régi téglafalnak, a fal törmelékké ...'::text,'omlik'::text,'omlott'::text,'fog omlani'::text,'Ha egy markoló nekimegy egy régi téglafalnak, a fal törmelékké omlik.'::text),
(382683,42521,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend ist das Haus jetzt nur noch Schutt, ...'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Bestie, anscheinend ist das Haus jetzt nur noch Schutt, oder?'::text),
(382687,42521,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, від будинку тепер лишилися самі руїни, ...'::text,'так?'::text,'так?'::text,'так?'::text,'Подруго, кажуть, від будинку тепер лишилися самі руїни, так?'::text),
(382686,42521,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer la casa ahora es solo escombros, ...'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'Amiga, al parecer la casa ahora es solo escombros, ¿verdad?'::text),
(382685,42521,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment la maison n''est plus qu''un tas de gravats, ...'::text,'hein ?'::text,'hein ?'::text,'hein ?'::text,'Ma belle, apparemment la maison n''est plus qu''un tas de gravats, hein ?'::text),
(382688,42521,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre ev artık sadece enkaz, ...'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Kanka, duyduğuma göre ev artık sadece enkaz, değil mi?'::text),
(382689,42521,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, úgy hallom, a házból már csak törmelék maradt, ...'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Csajszi, úgy hallom, a házból már csak törmelék maradt, ugye?'::text),
(382710,42524,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Bagger nicht gekommen wäre, ...'::text,'wäre das Haus nicht zu einem Schutthaufen geworden'::text,'wird das Haus nicht zu einem Schutthaufen werden'::text,'wurde das Haus nicht zu einem Schutthaufen'::text,'Wenn der Bagger nicht gekommen wäre, wäre das Haus nicht zu einem Schutthaufen geworden.'::text),
(382714,42524,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби екскаватор не приїхав, будинок ... на купу уламків.'::text,'не перетворився б'::text,'не перетвориться'::text,'не перетворився'::text,'Якби екскаватор не приїхав, будинок не перетворився б на купу уламків.'::text),
(382713,42524,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la excavadora no hubiera venido, la casa ... en un montón de escombros.'::text,'no se habría convertido'::text,'no se convertirá'::text,'no se convirtió'::text,'Si la excavadora no hubiera venido, la casa no se habría convertido en un montón de escombros.'::text),
(382712,42524,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si la pelleteuse n''était pas venue, la maison ... en un tas de gravats.'::text,'ne se serait pas transformée'::text,'ne se transformera pas'::text,'ne s''est pas transformée'::text,'Si la pelleteuse n''était pas venue, la maison ne se serait pas transformée en un tas de gravats.'::text),
(382715,42524,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekskavatör gelmeseydi ev bir moloz yığınına ...'::text,'dönmezdi'::text,'dönmeyecek'::text,'dönmedi'::text,'Ekskavatör gelmeseydi ev bir moloz yığınına dönmezdi.'::text),
(382716,42524,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem jött volna a markoló, a ház ... egy törmelékkupaccá.'::text,'nem vált volna'::text,'nem fog válni'::text,'nem vált'::text,'Ha nem jött volna a markoló, a ház nem vált volna egy törmelékkupaccá.'::text),
(382719,42525,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Bauleiter ermahnte sie, nicht zu nah am Schutt ...'::text,'zu stehen'::text,'zu stehen'::text,'zu stehen'::text,'Der Bauleiter ermahnte sie, nicht zu nah am Schutt zu stehen.'::text),
(382723,42525,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Виконроб попередив її, щоб вона ... надто близько до уламків.'::text,'не стояла'::text,'не стояла'::text,'не стояла'::text,'Виконроб попередив її, щоб вона не стояла надто близько до уламків.'::text),
(382722,42525,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El jefe de obra le advirtió que ... demasiado cerca de los escombros.'::text,'no se pusiera'::text,'no se pusiera'::text,'no se pusiera'::text,'El jefe de obra le advirtió que no se pusiera demasiado cerca de los escombros.'::text),
(382721,42525,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chef de chantier l''a avertie de ... trop près des gravats.'::text,'ne pas rester'::text,'ne pas rester'::text,'ne pas rester'::text,'Le chef de chantier l''a avertie de ne pas rester trop près des gravats.'::text),
(382724,42525,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şantiye şefi onu molozun çok yakınında ... uyardı.'::text,'durmaması için'::text,'durmaması için'::text,'durmaması için'::text,'Şantiye şefi onu molozun çok yakınında durmaması için uyardı.'::text),
(382725,42525,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az építésvezető figyelmeztette, hogy ... túl közel a törmelékhez.'::text,'ne álljon'::text,'ne álljon'::text,'ne álljon'::text,'Az építésvezető figyelmeztette, hogy ne álljon túl közel a törmelékhez.'::text),
(382728,42526,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... bei all dem Staub und Schutt eine Maske tragen sollen. Toller Sicherheitsplan, natürlich.'::text,'hätte'::text,'muss'::text,'sollte'::text,'Sie hätte bei all dem Staub und Schutt eine Maske tragen sollen. Toller Sicherheitsplan, natürlich.'::text),
(382732,42526,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... маску через увесь цей пил і уламки. Чудовий план безпеки, звісно.'::text,'мала б вдягти'::text,'мабуть, вдягла'::text,'має вдягти'::text,'Вона мала б вдягти маску через увесь цей пил і уламки. Чудовий план безпеки, звісно.'::text),
(382731,42526,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... una mascarilla por todo ese polvo y escombros. Gran plan de seguridad, obviamente.'::text,'Debería haber llevado'::text,'Debe de haber llevado'::text,'Debería llevar'::text,'Debería haber llevado una mascarilla por todo ese polvo y escombros. Gran plan de seguridad, obviamente.'::text),
(382730,42526,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... un masque avec toute cette poussière et ces gravats. Super plan de sécurité, évidemment.'::text,'aurait dû porter'::text,'a dû porter'::text,'devrait porter'::text,'Elle aurait dû porter un masque avec toute cette poussière et ces gravats. Super plan de sécurité, évidemment.'::text),
(382733,42526,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Maske ... bütün o toz ve moloza karşı. Harika bir güvenlik planı, tabii ki.'::text,'takmalıydı'::text,'takmış olmalı'::text,'takmalı'::text,'Maske takmalıydı bütün o toz ve moloza karşı. Harika bir güvenlik planı, tabii ki.'::text),
(382734,42526,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ennyi por és törmelék miatt. Remek biztonsági terv, nyilván.'::text,'Maszkot kellett volna viselnie'::text,'Biztosan maszkot viselt'::text,'Maszkot kellene viselnie'::text,'Maszkot kellett volna viselnie ennyi por és törmelék miatt. Remek biztonsági terv, nyilván.'::text),
(382737,42527,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als Nächstes wird sie den Schutt ... lassen. Ein winziger kleiner Job, natürlich.'::text,'wegbringen'::text,'wegbringen'::text,'wegbringen'::text,'Als Nächstes wird sie den Schutt wegbringen lassen. Ein winziger kleiner Job, natürlich.'::text),
(382741,42527,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Далі вона попросить ... уламки. Малесенька робота, звісно.'::text,'вивезти'::text,'вивезти'::text,'вивезти'::text,'Далі вона попросить вивезти уламки. Малесенька робота, звісно.'::text),
(382740,42527,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Luego hará que ... los escombros. Un trabajito de nada, obviamente.'::text,'se lleven'::text,'se lleven'::text,'se lleven'::text,'Luego hará que se lleven los escombros. Un trabajito de nada, obviamente.'::text),
(382739,42527,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ensuite, elle va faire ... les gravats. Un tout petit boulot, évidemment.'::text,'enlever'::text,'enlever'::text,'enlever'::text,'Ensuite, elle va faire enlever les gravats. Un tout petit boulot, évidemment.'::text),
(382742,42527,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonra ... molozu. Minicik bir iş, tabii ki.'::text,'taşıtacak'::text,'taşıtacak'::text,'taşıtacak'::text,'Sonra taşıtacak molozu. Minicik bir iş, tabii ki.'::text),
(382743,42527,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezután ... a törmeléket. Egy aprócska meló, nyilván.'::text,'elszállíttatja'::text,'elszállíttatja'::text,'elszállíttatja'::text,'Ezután elszállíttatja a törmeléket. Egy aprócska meló, nyilván.'::text),
(382746,42528,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ihre Nachbarn wünschten, der Schutt ... nicht so viel Staub. Ein herrlicher Tag für sie, natürlich.'::text,'machte'::text,'macht'::text,'wird'::text,'Ihre Nachbarn wünschten, der Schutt machte nicht so viel Staub. Ein herrlicher Tag für sie, natürlich.'::text),
(382750,42528,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Її сусіди хотіли б, щоб уламки ... стільки пилу. Чудовий день для них, звісно.'::text,'не здіймали'::text,'не здіймають'::text,'не здійматимуть'::text,'Її сусіди хотіли б, щоб уламки не здіймали стільки пилу. Чудовий день для них, звісно.'::text),
(382749,42528,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sus vecinos desearían que los escombros ... tanto polvo. Un día precioso para ellos, obviamente.'::text,'no levantaran'::text,'no levantan'::text,'no levantarán'::text,'Sus vecinos desearían que los escombros no levantaran tanto polvo. Un día precioso para ellos, obviamente.'::text),
(382748,42528,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ses voisins aimeraient que les gravats ... autant de poussière. Une belle journée pour eux, évidemment.'::text,'ne fassent pas'::text,'ne font pas'::text,'ne feront pas'::text,'Ses voisins aimeraient que les gravats ne fassent pas autant de poussière. Une belle journée pour eux, évidemment.'::text),
(382751,42528,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Komşuları keşke moloz bu kadar toz ... diyor. Onlar için harika bir gün, tabii ki.'::text,'çıkarmasa'::text,'çıkarmıyor'::text,'çıkarmayacak'::text,'Komşuları keşke moloz bu kadar toz çıkarmasa diyor. Onlar için harika bir gün, tabii ki.'::text),
(382752,42528,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szomszédai azt szeretnék, ha a törmelék ... ekkora port. Remek nap nekik, nyilván.'::text,'nem csinálna'::text,'nem csinál'::text,'nem fog csinálni'::text,'A szomszédai azt szeretnék, ha a törmelék nem csinálna ekkora port. Remek nap nekik, nyilván.'::text),
(382755,42529,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Haus, ... Dach zuerst einstürzte, ist jetzt nur noch Schutt!'::text,'dessen'::text,'welches'::text,'das'::text,'Das Haus, dessen Dach zuerst einstürzte, ist jetzt nur noch Schutt!'::text),
(382759,42529,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Будинок, ... дах обвалився першим, тепер — лише руїни!'::text,'чий'::text,'який'::text,'що'::text,'Будинок, чий дах обвалився першим, тепер — лише руїни!'::text),
(382758,42529,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La casa, ... tejado se derrumbó primero, ahora no es más que escombros!'::text,'cuyo'::text,'la cual'::text,'que'::text,'¡La casa, cuyo tejado se derrumbó primero, ahora no es más que escombros!'::text),
(382757,42529,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La maison, ... le toit s''est effondré en premier, n''est plus qu''un tas de gravats !'::text,'dont'::text,'laquelle'::text,'que'::text,'La maison, dont le toit s''est effondré en premier, n''est plus qu''un tas de gravats !'::text),
(382760,42529,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... çatısı ilk çöken ev şimdi sadece bir enkaz yığını!'::text,''::text,NULL::text,NULL::text,'Çatısı ilk çöken ev şimdi sadece bir enkaz yığını!'::text),
(382761,42529,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A ház, ... teteje elsőként szakadt be, most már csak egy romhalmaz!'::text,'amelynek a'::text,'amely'::text,'ami'::text,'A ház, amelynek a teteje elsőként szakadt be, most már csak egy romhalmaz!'::text),
(347142,38572,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, er ... Waschmittel in die Kappe, als er „Iiih!“ machte, irgendwie witzig.'::text,'goss gerade'::text,'goss'::text,'hat gegossen'::text,'Yo, er goss gerade Waschmittel in die Kappe, als er „Iiih!“ machte, irgendwie witzig.'::text),
(347146,38572,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, він ... засіб для прання в кришечку, коли раптом такий: «Фу!», трохи смішно.'::text,'наливав'::text,'налив'::text,'налив'::text,'Йо, він наливав засіб для прання в кришечку, коли раптом такий: «Фу!», трохи смішно.'::text),
(347145,38572,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, ... detergente en el tapón cuando soltó «¡Puaj!», en plan gracioso.'::text,'estaba echando'::text,'echó'::text,'ha echado'::text,'Oye, estaba echando detergente en el tapón cuando soltó «¡Puaj!», en plan gracioso.'::text),
(347144,38572,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, il ... de la lessive dans le bouchon quand il a fait « Beurk ! », un peu drôle quand même.'::text,'versait'::text,'a versé'::text,'a versé'::text,'Yo, il versait de la lessive dans le bouchon quand il a fait « Beurk ! », un peu drôle quand même.'::text),
(347147,38572,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, kapağa deterjan ... “Iyy!” dedi, biraz komik.'::text,'dökerken'::text,'döktüğünde'::text,'dökmüşken'::text,'Kanka, kapağa deterjan dökerken “Iyy!” dedi, biraz komik.'::text),
(347148,38572,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, épp mosószert ... a kupakba, amikor rákezdte, hogy „Fúj!”, kicsit vicces.'::text,'öntött'::text,'öntött'::text,'öntött'::text,'Tesó, épp mosószert öntött a kupakba, amikor rákezdte, hogy „Fúj!”, kicsit vicces.'::text),
(347151,38573,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wir ... dieses Waschmittel seit 6 Monaten, um im Budget zu bleiben.'::text,'verwenden'::text,'verwenden'::text,'verwenden'::text,'Wir verwenden dieses Waschmittel seit 6 Monaten, um im Budget zu bleiben.'::text),
(347155,38573,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ми ... цей засіб для прання вже 6 місяців, щоб не виходити за межі бюджету.'::text,'використовуємо'::text,'використовуємо'::text,'використовуємо'::text,'Ми використовуємо цей засіб для прання вже 6 місяців, щоб не виходити за межі бюджету.'::text),
(347154,38573,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Llevamos 6 meses ... este detergente para no salirnos del presupuesto.'::text,'usando'::text,'usando'::text,'usando'::text,'Llevamos 6 meses usando este detergente para no salirnos del presupuesto.'::text),
(347153,38573,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nous ... cette lessive depuis 6 mois pour rester dans le budget.'::text,'utilisons'::text,'utilisons'::text,'utilisons'::text,'Nous utilisons cette lessive depuis 6 mois pour rester dans le budget.'::text),
(347156,38573,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütçede kalmak için 6 aydır bu deterjanı ...'::text,'kullanıyoruz'::text,'kullanıyoruz'::text,'kullanıyoruz'::text,'Bütçede kalmak için 6 aydır bu deterjanı kullanıyoruz.'::text),
(347157,38573,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'6 hónapja ... ezt a mosószert, hogy a költségvetésen belül maradjunk.'::text,'használjuk'::text,'használjuk'::text,'használjuk'::text,'6 hónapja használjuk ezt a mosószert, hogy a költségvetésen belül maradjunk.'::text),
(347160,38574,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er goss gerade das Waschmittel in die Kappe, als sein Handy auf dem Regal ...'::text,'klingelte'::text,'gerade klingelte'::text,'geklingelt hat'::text,'Er goss gerade das Waschmittel in die Kappe, als sein Handy auf dem Regal klingelte.'::text),
(347164,38574,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він наливав засіб для прання в кришечку, коли на полиці ... його телефон.'::text,'задзвонив'::text,'дзвонив'::text,'задзвонив'::text,'Він наливав засіб для прання в кришечку, коли на полиці задзвонив його телефон.'::text),
(347163,38574,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estaba echando el detergente en el tapón cuando su móvil ... en la estantería.'::text,'sonó'::text,'estaba sonando'::text,'ha sonado'::text,'Estaba echando el detergente en el tapón cuando su móvil sonó en la estantería.'::text),
(347162,38574,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il versait la lessive dans le bouchon quand son téléphone ... sur l''étagère.'::text,'a sonné'::text,'sonnait'::text,'a sonné'::text,'Il versait la lessive dans le bouchon quand son téléphone a sonné sur l''étagère.'::text),
(347165,38574,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deterjanı kapağa dökerken raftaki telefonu ...'::text,'çaldı'::text,'çalıyordu'::text,'çalmış'::text,'Deterjanı kapağa dökerken raftaki telefonu çaldı.'::text),
(347166,38574,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp öntötte a mosószert a kupakba, amikor ... a telefonja a polcon.'::text,'megcsörrent'::text,'csörgött'::text,'megcsörrent'::text,'Épp öntötte a mosószert a kupakba, amikor megcsörrent a telefonja a polcon.'::text),
(347178,38576,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bevor er die Maschine startete, ...'::text,'hatte er das Waschmittel ins Fach gefüllt'::text,'hat er das Waschmittel ins Fach gefüllt'::text,'füllt er das Waschmittel ins Fach'::text,'Bevor er die Maschine startete, hatte er das Waschmittel ins Fach gefüllt.'::text),
(347182,38576,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Перш ніж увімкнути машинку, він ... засіб для прання в лоток.'::text,'залив'::text,'залив'::text,'заливає'::text,'Перш ніж увімкнути машинку, він залив засіб для прання в лоток.'::text),
(347181,38576,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Antes de poner en marcha la lavadora, ... el detergente en el cajetín.'::text,'había echado'::text,'ha echado'::text,'echa'::text,'Antes de poner en marcha la lavadora, había echado el detergente en el cajetín.'::text),
(347180,38576,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant de lancer la machine, il ... la lessive dans le bac.'::text,'avait versé'::text,'a versé'::text,'verse'::text,'Avant de lancer la machine, il avait versé la lessive dans le bac.'::text),
(347183,38576,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Makineyi çalıştırmadan önce deterjanı hazneye ...'::text,'dökmüştü'::text,'dökmüş'::text,'döker'::text,'Makineyi çalıştırmadan önce deterjanı hazneye dökmüştü.'::text),
(347184,38576,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mielőtt elindította a gépet, ... a mosószert a tartóba.'::text,'beleöntötte'::text,'beleöntötte'::text,'beleönti'::text,'Mielőtt elindította a gépet, beleöntötte a mosószert a tartóba.'::text),
(347187,38577,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er das Waschmittel vergisst, ... das Hemd schmutzig. Wirklich ein genialer Plan.'::text,'bleibt'::text,'bliebe'::text,'blieb'::text,'Wenn er das Waschmittel vergisst, bleibt das Hemd schmutzig. Wirklich ein genialer Plan.'::text),
(347191,38577,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він забуде засіб для прання, сорочка ... брудною. Справді геніальний план.'::text,'залишиться'::text,'залишилася б'::text,'залишилася'::text,'Якщо він забуде засіб для прання, сорочка залишиться брудною. Справді геніальний план.'::text),
(347190,38577,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se olvida del detergente, la camisa ... sucia. Un plan genial, de verdad.'::text,'seguirá'::text,'seguiría'::text,'siguió'::text,'Si se olvida del detergente, la camisa seguirá sucia. Un plan genial, de verdad.'::text),
(347189,38577,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il oublie la lessive, la chemise ... sale. Vraiment un plan de génie.'::text,'restera'::text,'resterait'::text,'est restée'::text,'S''il oublie la lessive, la chemise restera sale. Vraiment un plan de génie.'::text),
(347192,38577,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deterjanı unutursa gömlek kirli ... — gerçekten dahiyane bir plan.'::text,'kalacak'::text,'kalırdı'::text,'kaldı'::text,'Deterjanı unutursa gömlek kirli kalacak — gerçekten dahiyane bir plan.'::text),
(347193,38577,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha elfelejti a mosószert, az ing ... koszos. Tényleg zseniális terv.'::text,'marad'::text,'maradna'::text,'maradt'::text,'Ha elfelejti a mosószert, az ing marad koszos. Tényleg zseniális terv.'::text),
(347196,38578,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des Geruchs goss er das Waschmittel trotzdem hinein. Absoluter Horror!'::text,'Trotz'::text,'Obwohl'::text,'Wegen'::text,'Trotz des Geruchs goss er das Waschmittel trotzdem hinein. Absoluter Horror!'::text),
(347200,38578,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... запах, він однаково залив засіб для прання. Абсолютний жах!'::text,'Попри'::text,'Хоча'::text,'Через'::text,'Попри запах, він однаково залив засіб для прання. Абсолютний жах!'::text),
(347199,38578,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... el olor, echó el detergente de todos modos. ¡Horror absoluto!'::text,'A pesar de'::text,'Aunque'::text,'Por'::text,'A pesar de el olor, echó el detergente de todos modos. ¡Horror absoluto!'::text),
(347198,38578,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... l''odeur, il a quand même versé la lessive. L''horreur absolue !'::text,'Malgré'::text,'Bien que'::text,'À cause de'::text,'Malgré l''odeur, il a quand même versé la lessive. L''horreur absolue !'::text),
(347201,38578,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... deterjanı yine de döktü. Mutlak dehşet!'::text,'Kokuya rağmen'::text,'Kokuya rağmen'::text,'Koku yüzünden'::text,'Kokuya rağmen deterjanı yine de döktü. Mutlak dehşet!'::text),
(347202,38578,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A szag ... mégis beleöntötte a mosószert. Abszolút horror!'::text,'ellenére'::text,'bár'::text,'miatt'::text,'A szag ellenére mégis beleöntötte a mosószert. Abszolút horror!'::text),
(347205,38579,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er wusste, dass das Hemd ohne Waschmittel für immer dreckig ...!'::text,'bleiben würde'::text,'bleiben wird'::text,'bleibt'::text,'Er wusste, dass das Hemd ohne Waschmittel für immer dreckig bleiben würde!'::text),
(347209,38579,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він знав, що без засобу для прання сорочка ... брудною назавжди!'::text,'залишиться'::text,'залишиться'::text,'залишається'::text,'Він знав, що без засобу для прання сорочка залишиться брудною назавжди!'::text),
(347208,38579,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Sabía que sin detergente la camisa ... asquerosa para siempre!'::text,'seguiría'::text,'seguirá'::text,'sigue'::text,'¡Sabía que sin detergente la camisa seguiría asquerosa para siempre!'::text),
(347207,38579,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il savait que sans lessive, la chemise ... crasseuse pour toujours !'::text,'resterait'::text,'restera'::text,'reste'::text,'Il savait que sans lessive, la chemise resterait crasseuse pour toujours !'::text),
(347210,38579,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Deterjan olmadan gömleğin sonsuza dek pis ... biliyordu!'::text,'kalacağını'::text,'kalacağını'::text,'kaldığını'::text,'Deterjan olmadan gömleğin sonsuza dek pis kalacağını biliyordu!'::text),
(347211,38579,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tudta, hogy mosószer nélkül az ing örökre koszos ...!'::text,'maradna'::text,'fog maradni'::text,'marad'::text,'Tudta, hogy mosószer nélkül az ing örökre koszos maradna!'::text),
(347214,38580,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schatz, anscheinend ... er seit zehn Jahren dasselbe Waschmittel.'::text,'benutzt'::text,'benutzt'::text,'benutzt'::text,'Schatz, anscheinend benutzt er seit zehn Jahren dasselbe Waschmittel.'::text),
(347218,38580,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, він ... той самий засіб для прання вже десять років.'::text,'використовує'::text,'використовує'::text,'використовує'::text,'Подруго, кажуть, він використовує той самий засіб для прання вже десять років.'::text),
(347217,38580,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ... el mismo detergente desde hace diez años.'::text,'usa'::text,'usa'::text,'está usando'::text,'Tía, al parecer usa el mismo detergente desde hace diez años.'::text),
(347216,38580,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment il ... la même lessive depuis dix ans.'::text,'utilise'::text,'utilise'::text,'utilise'::text,'Ma belle, apparemment il utilise la même lessive depuis dix ans.'::text),
(347219,38580,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre on yıldır aynı deterjanı ...'::text,'kullanıyor'::text,'kullanıyor'::text,'kullanıyor'::text,'Kızım, duyduğuma göre on yıldır aynı deterjanı kullanıyor.'::text),
(347220,38580,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, úgy tűnik, tíz éve ... ugyanazt a mosószert.'::text,'használja'::text,'használja'::text,'használja'::text,'Csajszi, úgy tűnik, tíz éve használja ugyanazt a mosószert.'::text),
(347232,38582,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Alter, echt, bis die Wäsche fertig ist, ...'::text,'wird er die halbe Flasche Waschmittel verbraucht haben'::text,'wird er die halbe Flasche Waschmittel verbrauchen'::text,'verbraucht er die halbe Flasche Waschmittel'::text,'Alter, echt, bis die Wäsche fertig ist, wird er die halbe Flasche Waschmittel verbraucht haben.'::text),
(347236,38582,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, поки те прання закінчиться, він ... пів пляшки засобу для прання, чесно.'::text,'витратить'::text,'витратить'::text,'витрачає'::text,'Бро, поки те прання закінчиться, він витратить пів пляшки засобу для прання, чесно.'::text),
(347235,38582,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, para cuando termine ese lavado, ... media botella de detergente, en serio.'::text,'habrá gastado'::text,'gastará'::text,'gasta'::text,'Bro, para cuando termine ese lavado, habrá gastado media botella de detergente, en serio.'::text),
(347234,38582,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, d''ici la fin de ce lavage, il ... la moitié de la bouteille de lessive, sérieux.'::text,'aura utilisé'::text,'utilisera'::text,'utilise'::text,'Frérot, d''ici la fin de ce lavage, il aura utilisé la moitié de la bouteille de lessive, sérieux.'::text),
(347237,38582,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, o yıkama bitene kadar deterjan şişesinin yarısını ..., cidden.'::text,'bitirmiş olacak'::text,'bitirecek'::text,'bitiriyor'::text,'Kanka, o yıkama bitene kadar deterjan şişesinin yarısını bitirmiş olacak, cidden.'::text),
(347238,38582,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, mire az a mosás véget ér, ... a flakon mosószer felét, komolyan.'::text,'elhasználja'::text,'el fogja használni'::text,'használja'::text,'Tesó, mire az a mosás véget ér, elhasználja a flakon mosószer felét, komolyan.'::text),
(374556,41618,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Hund ... Sand aus der Grube, als der Junge eine weitere Schaufel auf den Haufen warf.'::text,'scharrte gerade'::text,'scharrte'::text,'hat gescharrt'::text,'Der Hund scharrte gerade Sand aus der Grube, als der Junge eine weitere Schaufel auf den Haufen warf.'::text),
(374560,41618,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пес ... пісок із ями, коли хлопець кинув ще одну лопату на купу.'::text,'вигрібав'::text,'вигріб'::text,'вигріб'::text,'Пес вигрібав пісок із ями, коли хлопець кинув ще одну лопату на купу.'::text),
(374559,41618,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El perro ... arena del hoyo cuando el chico echó otra palada al montón.'::text,'estaba sacando'::text,'sacó'::text,'ha sacado'::text,'El perro estaba sacando arena del hoyo cuando el chico echó otra palada al montón.'::text),
(374558,41618,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le chien ... du sable hors du trou quand le garçon a jeté une autre pelletée sur le tas.'::text,'grattait'::text,'a gratté'::text,'a gratté'::text,'Le chien grattait du sable hors du trou quand le garçon a jeté une autre pelletée sur le tas.'::text),
(374561,41618,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk yığına bir kürek daha attığında köpek çukurdan kum ...'::text,'eşeliyordu'::text,'eşeledi'::text,'eşelemiş'::text,'Çocuk yığına bir kürek daha attığında köpek çukurdan kum eşeliyordu.'::text),
(374562,41618,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kutya épp ... a homokot a gödörből, amikor a fiú újabb lapátnyit dobott a kupacra.'::text,'kaparta ki'::text,'kikaparta'::text,'kikaparta'::text,'A kutya épp kaparta ki a homokot a gödörből, amikor a fiú újabb lapátnyit dobott a kupacra.'::text),
(374565,41619,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Junge ... diese Grube im Sand schon fast eine Stunde.'::text,'gräbt'::text,'gräbt'::text,'gräbt'::text,'Der Junge gräbt diese Grube im Sand schon fast eine Stunde.'::text),
(374569,41619,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопець ... цю яму в піску вже майже годину.'::text,'копає'::text,'копає'::text,'копає'::text,'Хлопець копає цю яму в піску вже майже годину.'::text),
(374568,41619,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chico lleva casi una hora ... este hoyo en la arena.'::text,'cavando'::text,'cavando'::text,'cavando'::text,'El chico lleva casi una hora cavando este hoyo en la arena.'::text),
(374567,41619,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le garçon ... ce trou dans le sable depuis presque une heure.'::text,'creuse'::text,'creuse'::text,'creuse'::text,'Le garçon creuse ce trou dans le sable depuis presque une heure.'::text),
(374570,41619,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk neredeyse bir saattir kumda bu çukuru ...'::text,'kazıyor'::text,'kazıyor'::text,'kazıyor'::text,'Çocuk neredeyse bir saattir kumda bu çukuru kazıyor.'::text),
(374571,41619,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiú már majdnem egy órája ... ezt a gödröt a homokban.'::text,'ássa'::text,'ássa'::text,'ássa'::text,'A fiú már majdnem egy órája ássa ezt a gödröt a homokban.'::text),
(374574,41620,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als die Grube tief genug war, ...'::text,'setzte sich der Junge neben den Hund hinein'::text,'saß der Junge neben dem Hund darin'::text,'hat sich der Junge neben den Hund hineingesetzt'::text,'Als die Grube tief genug war, setzte sich der Junge neben den Hund hinein.'::text),
(374578,41620,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли яма стала достатньо глибокою, хлопець ... в неї поруч із псом.'::text,'сів'::text,'сидів'::text,'сів'::text,'Коли яма стала достатньо глибокою, хлопець сів в неї поруч із псом.'::text),
(374577,41620,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando el hoyo fue lo bastante profundo, el chico ... dentro junto al perro.'::text,'se sentó'::text,'estaba sentado'::text,'se ha sentado'::text,'Cuando el hoyo fue lo bastante profundo, el chico se sentó dentro junto al perro.'::text),
(374576,41620,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le trou a été assez profond, le garçon ... dedans à côté du chien.'::text,'s''est assis'::text,'était assis'::text,'s''est assis'::text,'Quand le trou a été assez profond, le garçon s''est assis dedans à côté du chien.'::text),
(374579,41620,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çukur yeterince derin olunca çocuk köpeğin yanına, içine ...'::text,'oturdu'::text,'oturuyordu'::text,'oturmuş'::text,'Çukur yeterince derin olunca çocuk köpeğin yanına, içine oturdu.'::text),
(374580,41620,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor a gödör elég mély lett, a fiú ... benne a kutya mellé.'::text,'leült'::text,'ült'::text,'leült'::text,'Amikor a gödör elég mély lett, a fiú leült benne a kutya mellé.'::text),
(374583,41621,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katastrophe! Der Junge hat heute schon zwei Gruben ..., und der ganze Strand ist ruiniert!'::text,'gegraben'::text,'gegraben'::text,'gegraben'::text,'Katastrophe! Der Junge hat heute schon zwei Gruben gegraben, und der ganze Strand ist ruiniert!'::text),
(374587,41621,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Катастрофа! Хлопець уже сьогодні ... дві ями, і весь пляж зіпсований!'::text,'викопав'::text,'копав'::text,'копає'::text,'Катастрофа! Хлопець уже сьогодні викопав дві ями, і весь пляж зіпсований!'::text),
(374586,41621,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Catástrofe! ¡El chico ya ... dos hoyos hoy y toda la playa está arruinada!'::text,'ha cavado'::text,'ha estado cavando'::text,'está cavando'::text,'¡Catástrofe! ¡El chico ya ha cavado dos hoyos hoy y toda la playa está arruinada!'::text),
(374585,41621,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Catastrophe ! Le garçon ... déjà deux trous aujourd''hui, et toute la plage est ruinée !'::text,'a creusé'::text,'a creusé'::text,'creuse'::text,'Catastrophe ! Le garçon a creusé déjà deux trous aujourd''hui, et toute la plage est ruinée !'::text),
(374588,41621,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Felaket! Çocuk bugün şimdiden iki çukur ... ve bütün plaj mahvoldu!'::text,'kazdı'::text,'kazıyor'::text,'kazıyor'::text,'Felaket! Çocuk bugün şimdiden iki çukur kazdı ve bütün plaj mahvoldu!'::text),
(374589,41621,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Katasztrófa! A fiú ma már két gödröt ..., és az egész strand tönkrement!'::text,'ásott'::text,'ásott'::text,'ás'::text,'Katasztrófa! A fiú ma már két gödröt ásott, és az egész strand tönkrement!'::text),
(374592,41622,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als seine Mutter nach ihm suchte, ... der Junge schon eine so tiefe Grube gegraben, dass sie schrie!'::text,'hatte'::text,'hat'::text,'hat'::text,'Als seine Mutter nach ihm suchte, hatte der Junge schon eine so tiefe Grube gegraben, dass sie schrie!'::text),
(374596,41622,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли мама прийшла його шукати, хлопець уже ... таку глибоку яму, що вона скрикнула!'::text,'викопав'::text,'викопав'::text,'копає'::text,'Коли мама прийшла його шукати, хлопець уже викопав таку глибоку яму, що вона скрикнула!'::text),
(374595,41622,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Cuando su madre vino a buscarlo, el chico ya ... un hoyo tan profundo que ella gritó!'::text,'había cavado'::text,'ha cavado'::text,'cava'::text,'¡Cuando su madre vino a buscarlo, el chico ya había cavado un hoyo tan profundo que ella gritó!'::text),
(374594,41622,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand sa mère est venue le chercher, le garçon ... un trou si profond qu''elle a crié !'::text,'avait creusé'::text,'a creusé'::text,'creuse'::text,'Quand sa mère est venue le chercher, le garçon avait creusé un trou si profond qu''elle a crié !'::text),
(374597,41622,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Annesi onu aramaya geldiğinde çocuk öyle derin bir çukur ... ki annesi çığlık attı!'::text,'kazmıştı'::text,'kazmış'::text,'kazıyor'::text,'Annesi onu aramaya geldiğinde çocuk öyle derin bir çukur kazmıştı ki annesi çığlık attı!'::text),
(374598,41622,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire az anyja kereste, a fiú olyan mély gödröt ..., hogy felsikoltott!'::text,'ásott'::text,'ásott'::text,'ás'::text,'Mire az anyja kereste, a fiú olyan mély gödröt ásott, hogy felsikoltott!'::text),
(374610,41624,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Junge eine größere Schaufel hätte, ...'::text,'würde er die Grube doppelt so schnell graben'::text,'wird er die Grube doppelt so schnell graben'::text,'gräbt er die Grube doppelt so schnell'::text,'Wenn der Junge eine größere Schaufel hätte, würde er die Grube doppelt so schnell graben.'::text),
(374614,41624,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби хлопець мав більшу лопату, він ... яму вдвічі швидше.'::text,'викопав би'::text,'викопає'::text,'копає'::text,'Якби хлопець мав більшу лопату, він викопав би яму вдвічі швидше.'::text),
(374613,41624,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el chico tuviera una pala más grande, ... el hoyo el doble de rápido.'::text,'cavaría'::text,'cavará'::text,'cava'::text,'Si el chico tuviera una pala más grande, cavaría el hoyo el doble de rápido.'::text),
(374612,41624,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le garçon avait une plus grande pelle, il ... le trou deux fois plus vite.'::text,'creuserait'::text,'creusera'::text,'creuse'::text,'Si le garçon avait une plus grande pelle, il creuserait le trou deux fois plus vite.'::text),
(374615,41624,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuğun daha büyük bir küreği olsaydı çukuru iki kat hızlı ...'::text,'kazardı'::text,'kazacak'::text,'kazıyor'::text,'Çocuğun daha büyük bir küreği olsaydı çukuru iki kat hızlı kazardı.'::text),
(374616,41624,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a fiúnak nagyobb lapátja lenne, kétszer olyan gyorsan ... a gödröt.'::text,'kiásná'::text,'ki fogja ásni'::text,'kiássa'::text,'Ha a fiúnak nagyobb lapátja lenne, kétszer olyan gyorsan kiásná a gödröt.'::text),
(374619,41625,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör mal, ich hab gehört, er hat dem Hund versprochen, dass er eine Grube ..., die groß genug für beide ist.'::text,'graben würde'::text,'graben wird'::text,'gerade gräbt'::text,'Hör mal, ich hab gehört, er hat dem Hund versprochen, dass er eine Grube graben würde, die groß genug für beide ist.'::text),
(374623,41625,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, я чула, він пообіцяв псові, що ... яму, достатньо велику для них обох.'::text,'викопає'::text,'викопає'::text,'копає'::text,'Слухай, я чула, він пообіцяв псові, що викопає яму, достатньо велику для них обох.'::text),
(374622,41625,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, me han dicho que le prometió al perro que ... un hoyo lo bastante grande para los dos.'::text,'cavaría'::text,'cavará'::text,'está cavando'::text,'Oye, me han dicho que le prometió al perro que cavaría un hoyo lo bastante grande para los dos.'::text),
(374621,41625,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, j''ai entendu dire qu''il avait promis au chien qu''il ... un trou assez grand pour eux deux.'::text,'creuserait'::text,'creusera'::text,'est en train de creuser'::text,'Écoute, j''ai entendu dire qu''il avait promis au chien qu''il creuserait un trou assez grand pour eux deux.'::text),
(374624,41625,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, duyduğuma göre köpeğe ikisine de yetecek kadar büyük bir çukur ... söz vermiş.'::text,'kazacağına'::text,'kazacağına'::text,'kazdığına'::text,'Dinle, duyduğuma göre köpeğe ikisine de yetecek kadar büyük bir çukur kazacağına söz vermiş.'::text),
(374625,41625,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyi, úgy hallottam, megígérte a kutyának, hogy ... egy akkora gödröt, hogy mindkettejüknek elég legyen.'::text,'ás'::text,'fog ásni'::text,'éppen ás'::text,'Figyi, úgy hallottam, megígérte a kutyának, hogy ás egy akkora gödröt, hogy mindkettejüknek elég legyen.'::text),
(374628,41626,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Junge ... jetzt mit dem Hund in seiner Grube, offensichtlich schwer am Arbeiten.'::text,'sitzt'::text,'sitzt'::text,'saß'::text,'Der Junge sitzt jetzt mit dem Hund in seiner Grube, offensichtlich schwer am Arbeiten.'::text),
(374632,41626,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Хлопець зараз ... у своїй ямі з псом, очевидно, дуже тяжко працює.'::text,'сидить'::text,'сидить'::text,'сидів'::text,'Хлопець зараз сидить у своїй ямі з псом, очевидно, дуже тяжко працює.'::text),
(374631,41626,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El chico ... en su hoyo con el perro ahora, claramente trabajando muchísimo.'::text,'está sentado'::text,'se sienta'::text,'se ha sentado'::text,'El chico está sentado en su hoyo con el perro ahora, claramente trabajando muchísimo.'::text),
(374630,41626,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le garçon ... dans son trou avec le chien en ce moment, visiblement en plein travail acharné.'::text,'est assis'::text,'s''assoit'::text,'s''est assis'::text,'Le garçon est assis dans son trou avec le chien en ce moment, visiblement en plein travail acharné.'::text),
(374633,41626,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk şu an köpekle birlikte çukurunda ..., belli ki çok sıkı çalışıyor.'::text,'oturuyor'::text,'oturur'::text,'oturmuş'::text,'Çocuk şu an köpekle birlikte çukurunda oturuyor, belli ki çok sıkı çalışıyor.'::text),
(374634,41626,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiú most ... a gödrében a kutyával, láthatóan nagyon keményen dolgozik.'::text,'ül'::text,'ül'::text,'ült'::text,'A fiú most ül a gödrében a kutyával, láthatóan nagyon keményen dolgozik.'::text),
(374637,41627,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als sich der Junge setzte, ... der Hund schon ewig Sand aus der Grube, ein echter Profi.'::text,'scharrte'::text,'scharrte'::text,'scharrte'::text,'Als sich der Junge setzte, scharrte der Hund schon ewig Sand aus der Grube, ein echter Profi.'::text),
(374641,41627,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли хлопець сів, пес уже цілу вічність ... пісок із ями, справжній професіонал.'::text,'вигрібав'::text,'вигрібав'::text,'вигріб'::text,'Коли хлопець сів, пес уже цілу вічність вигрібав пісок із ями, справжній професіонал.'::text),
(374640,41627,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando el chico se sentó, el perro ... arena del hoyo desde hacía siglos, todo un profesional.'::text,'había estado sacando'::text,'estaba sacando'::text,'ha sacado'::text,'Cuando el chico se sentó, el perro había estado sacando arena del hoyo desde hacía siglos, todo un profesional.'::text),
(374639,41627,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le garçon s''est assis, le chien ... du sable du trou depuis une éternité, un vrai pro.'::text,'grattait'::text,'grattait'::text,'a gratté'::text,'Quand le garçon s''est assis, le chien grattait du sable du trou depuis une éternité, un vrai pro.'::text),
(374642,41627,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çocuk oturduğunda köpek çoktandır çukurdan kum ..., tam bir profesyonel.'::text,'eşeliyordu'::text,'eşeliyordu'::text,'eşeledi'::text,'Çocuk oturduğunda köpek çoktandır çukurdan kum eşeliyordu, tam bir profesyonel.'::text),
(374643,41627,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amikor a fiú leült, a kutya már egy örökkévalóság óta ... a homokot a gödörből, igazi profi.'::text,'kaparta'::text,'kaparta'::text,'kikaparta'::text,'Amikor a fiú leült, a kutya már egy örökkévalóság óta kaparta a homokot a gödörből, igazi profi.'::text),
(376815,41869,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Regisseurin verspricht der Crew, dass die Produktion pünktlich ...'::text,'enden wird'::text,'enden wird'::text,'endet'::text,'Die Regisseurin verspricht der Crew, dass die Produktion pünktlich enden wird.'::text),
(376819,41869,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Режисерка обіцяє знімальній групі, що постановка ... вчасно.'::text,'завершиться'::text,'завершуватиметься'::text,'завершується'::text,'Режисерка обіцяє знімальній групі, що постановка завершиться вчасно.'::text),
(376818,41869,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La directora le promete al equipo que la producción ... a tiempo.'::text,'terminará'::text,'estará terminando'::text,'termina'::text,'La directora le promete al equipo que la producción terminará a tiempo.'::text),
(376817,41869,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La réalisatrice promet à l''équipe que la production ... à temps.'::text,'se terminera'::text,'sera en train de se terminer'::text,'se termine'::text,'La réalisatrice promet à l''équipe que la production se terminera à temps.'::text),
(376820,41869,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yönetmen ekibe prodüksiyonun zamanında ... söz veriyor.'::text,'biteceğine'::text,'bitiyor olacağına'::text,'bittiğine'::text,'Yönetmen ekibe prodüksiyonun zamanında biteceğine söz veriyor.'::text),
(376821,41869,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rendezőnő megígéri a stábnak, hogy a produkció időben ...'::text,'befejeződik'::text,'be fog fejeződni'::text,'befejeződik'::text,'A rendezőnő megígéri a stábnak, hogy a produkció időben befejeződik.'::text),
(376824,41870,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn eine Aufnahme perfekt ist, ... die Regisseurin dieser Produktion in die Luft, offensichtlich total ruhig.'::text,'boxt'::text,'boxte'::text,'boxt'::text,'Wenn eine Aufnahme perfekt ist, boxt die Regisseurin dieser Produktion in die Luft, offensichtlich total ruhig.'::text),
(376828,41870,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли дубль ідеальний, режисерка цієї постановки ... кулаком у повітря, очевидно, дуже спокійна.'::text,'б''є'::text,'вдарила'::text,'вдарить'::text,'Коли дубль ідеальний, режисерка цієї постановки б''є кулаком у повітря, очевидно, дуже спокійна.'::text),
(376827,41870,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si una toma es perfecta, la directora de esta producción ... puñetazos al aire, obviamente muy tranquila.'::text,'da'::text,'dio'::text,'dará'::text,'Si una toma es perfecta, la directora de esta producción da puñetazos al aire, obviamente muy tranquila.'::text),
(376826,41870,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand une prise est parfaite, la réalisatrice de cette production ... l''air du poing, évidemment très calme.'::text,'frappe'::text,'a frappé'::text,'frappera'::text,'Quand une prise est parfaite, la réalisatrice de cette production frappe l''air du poing, évidemment très calme.'::text),
(376829,41870,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir çekim mükemmel olunca bu prodüksiyonun yönetmeni havaya yumruk ..., belli ki çok sakin.'::text,'atar'::text,'attı'::text,'atacak'::text,'Bir çekim mükemmel olunca bu prodüksiyonun yönetmeni havaya yumruk atar, belli ki çok sakin.'::text),
(376830,41870,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy felvétel tökéletes, ennek a produkciónak a rendezője ... a levegőbe, nyilván nagyon nyugodtan.'::text,'belebokszol'::text,'belebokszolt'::text,'bele fog bokszolni'::text,'Ha egy felvétel tökéletes, ennek a produkciónak a rendezője belebokszol a levegőbe, nyilván nagyon nyugodtan.'::text),
(376833,41871,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Fensterszene der Produktion ... heute Morgen gedreht, und die Crew wirkt leicht zufrieden.'::text,'wurde'::text,'hat'::text,'wird'::text,'Die Fensterszene der Produktion wurde heute Morgen gedreht, und die Crew wirkt leicht zufrieden.'::text),
(376837,41871,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сцена біля вікна для постановки ... сьогодні вранці, і знімальна група здається трохи задоволеною.'::text,'була знята'::text,'зняла'::text,'знята'::text,'Сцена біля вікна для постановки була знята сьогодні вранці, і знімальна група здається трохи задоволеною.'::text),
(376836,41871,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La escena de la ventana de la producción ... esta mañana, y el equipo parece ligeramente satisfecho.'::text,'se grabó'::text,'grabó'::text,'se graba'::text,'La escena de la ventana de la producción se grabó esta mañana, y el equipo parece ligeramente satisfecho.'::text),
(376835,41871,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La scène de la fenêtre de la production ... ce matin, et l''équipe semble vaguement satisfaite.'::text,'a été tournée'::text,'a tourné'::text,'est tournée'::text,'La scène de la fenêtre de la production a été tournée ce matin, et l''équipe semble vaguement satisfaite.'::text),
(376838,41871,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Prodüksiyonun pencere sahnesi bu sabah ... ve ekip hafifçe memnun görünüyor.'::text,'çekildi'::text,'çekti'::text,'çekiliyor'::text,'Prodüksiyonun pencere sahnesi bu sabah çekildi ve ekip hafifçe memnun görünüyor.'::text),
(376839,41871,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A produkció ablakos jelenetét ma reggel ..., és a stáb enyhén elégedettnek tűnik.'::text,'vették fel'::text,'felvette'::text,'veszik fel'::text,'A produkció ablakos jelenetét ma reggel vették fel, és a stáb enyhén elégedettnek tűnik.'::text),
(376842,41872,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Regisseurin ... die beiden Schauspieler ans Fenster, bevor das Produktionsteam zu drehen begann.'::text,'stellte'::text,'wurde gestellt'::text,'stellend'::text,'Die Regisseurin stellte die beiden Schauspieler ans Fenster, bevor das Produktionsteam zu drehen begann.'::text),
(376846,41872,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Режисерка ... двох акторів біля вікна, перш ніж команда постановки почала знімати.'::text,'поставила'::text,'була поставлена'::text,'ставлячи'::text,'Режисерка поставила двох акторів біля вікна, перш ніж команда постановки почала знімати.'::text),
(376845,41872,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La directora ... a los dos actores junto a la ventana antes de que el equipo de producción empezara a grabar.'::text,'colocó'::text,'fue colocada'::text,'colocando'::text,'La directora colocó a los dos actores junto a la ventana antes de que el equipo de producción empezara a grabar.'::text),
(376844,41872,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La réalisatrice ... les deux acteurs près de la fenêtre avant que l''équipe de production commence à tourner.'::text,'a placé'::text,'a été placée'::text,'plaçant'::text,'La réalisatrice a placé les deux acteurs près de la fenêtre avant que l''équipe de production commence à tourner.'::text),
(376847,41872,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yönetmen, prodüksiyon ekibi çekime başlamadan önce iki oyuncuyu pencerenin yanına ...'::text,'yerleştirdi'::text,'yerleştirildi'::text,'yerleştirerek'::text,'Yönetmen, prodüksiyon ekibi çekime başlamadan önce iki oyuncuyu pencerenin yanına yerleştirdi.'::text),
(376848,41872,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rendezőnő ... a két színészt az ablakhoz, mielőtt a produkciós csapat elkezdett forgatni.'::text,'odaállította'::text,'oda lett állítva'::text,'odaállítva'::text,'A rendezőnő odaállította a két színészt az ablakhoz, mielőtt a produkciós csapat elkezdett forgatni.'::text),
(376851,41873,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, sie boxt in die Luft, also ... diese Produktion echt gut laufen, safe.'::text,'muss'::text,'kann nicht'::text,'könnte nicht'::text,'Yo, sie boxt in die Luft, also muss diese Produktion echt gut laufen, safe.'::text),
(376855,41873,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йо, вона б''є кулаком у повітря, отже, у цієї постановки ... все йде дуже добре, чесно.'::text,'точно'::text,'ніяк не'::text,'можливо, не'::text,'Йо, вона б''є кулаком у повітря, отже, у цієї постановки точно все йде дуже добре, чесно.'::text),
(376854,41873,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oye, está dando puñetazos al aire, así que esta producción ... estar yendo genial, en serio.'::text,'debe de'::text,'no puede'::text,'puede que no'::text,'Oye, está dando puñetazos al aire, así que esta producción debe de estar yendo genial, en serio.'::text),
(376853,41873,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yo, elle frappe l''air du poing, donc cette production ... se passer super bien, sérieux.'::text,'doit'::text,'ne peut pas'::text,'pourrait ne pas'::text,'Yo, elle frappe l''air du poing, donc cette production doit se passer super bien, sérieux.'::text),
(376856,41873,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, havaya yumruk atıyor, yani bu prodüksiyon çok iyi ..., cidden.'::text,'gidiyor olmalı'::text,'gidiyor olamaz'::text,'gitmiyor olabilir'::text,'Kanka, havaya yumruk atıyor, yani bu prodüksiyon çok iyi gidiyor olmalı, cidden.'::text),
(376857,41873,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a levegőbe bokszol, szóval ez a produkció ... nagyon jól megy, komolyan.'::text,'biztosan'::text,'nem lehet, hogy'::text,'lehet, hogy nem'::text,'Tesó, a levegőbe bokszol, szóval ez a produkció biztosan nagyon jól megy, komolyan.'::text),
(376860,41874,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Regisseurin, ... in die Luft geboxt hat, hat für diese Produktion ein Budget von 2 Millionen.'::text,'die'::text,'welche'::text,'deren'::text,'Die Regisseurin, die in die Luft geboxt hat, hat für diese Produktion ein Budget von 2 Millionen.'::text),
(376864,41874,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Режисерка, ... вдарила кулаком у повітря, має бюджет 2 мільйони на цю постановку.'::text,'яка'::text,'котра'::text,'чия'::text,'Режисерка, яка вдарила кулаком у повітря, має бюджет 2 мільйони на цю постановку.'::text),
(376863,41874,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La directora ... dio un puñetazo al aire tiene un presupuesto de 2 millones para esta producción.'::text,'que'::text,'la cual'::text,'cuya'::text,'La directora que dio un puñetazo al aire tiene un presupuesto de 2 millones para esta producción.'::text),
(376862,41874,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La réalisatrice ... a frappé l''air du poing dispose d''un budget de 2 millions pour cette production.'::text,'qui'::text,'laquelle'::text,'dont'::text,'La réalisatrice qui a frappé l''air du poing dispose d''un budget de 2 millions pour cette production.'::text),
(376865,41874,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Havaya yumruk ... yönetmenin bu prodüksiyon için 2 milyonluk bir bütçesi var.'::text,'atan'::text,'atan'::text,'attığı'::text,'Havaya yumruk atan yönetmenin bu prodüksiyon için 2 milyonluk bir bütçesi var.'::text),
(376866,41874,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rendezőnő, ... a levegőbe bokszolt, 2 milliós költségvetéssel rendelkezik ehhez a produkcióhoz.'::text,'aki'::text,'amely'::text,'akinek a'::text,'A rendezőnő, aki a levegőbe bokszolt, 2 milliós költségvetéssel rendelkezik ehhez a produkcióhoz.'::text),
(376869,41875,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Am Montag sagte die Regisseurin, die Produktion ... an dem Tag fertig, weil sie fertig war.'::text,'sei'::text,'ist'::text,'werde'::text,'Am Montag sagte die Regisseurin, die Produktion sei an dem Tag fertig, weil sie fertig war.'::text),
(376873,41875,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'У понеділок режисерка сказала, що постановка ... готова того дня, бо її завершили.'::text,'була'::text,'є'::text,'буде'::text,'У понеділок режисерка сказала, що постановка була готова того дня, бо її завершили.'::text),
(376872,41875,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El lunes la directora dijo que la producción ... lista ese día, porque estaba terminada.'::text,'estaba'::text,'está'::text,'estará'::text,'El lunes la directora dijo que la producción estaba lista ese día, porque estaba terminada.'::text),
(376871,41875,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Lundi, la réalisatrice a dit que la production ... prête ce jour-là, parce qu''elle était terminée.'::text,'était'::text,'est'::text,'sera'::text,'Lundi, la réalisatrice a dit que la production était prête ce jour-là, parce qu''elle était terminée.'::text),
(376874,41875,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pazartesi yönetmen prodüksiyonun o gün hazır ... söyledi, çünkü bitmişti.'::text,'olduğunu'::text,'olduğunu'::text,'olacağını'::text,'Pazartesi yönetmen prodüksiyonun o gün hazır olduğunu söyledi, çünkü bitmişti.'::text),
(376875,41875,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hétfőn a rendezőnő azt mondta, hogy a produkció aznap ... kész, mert befejezték.'::text,'volt'::text,NULL::text,'lesz'::text,'Hétfőn a rendezőnő azt mondta, hogy a produkció aznap volt kész, mert befejezték.'::text),
(376878,41876,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Regisseurin war mit der letzten Aufnahme der Produktion zufrieden, und ...'::text,'die Crew auch'::text,'die Crew auch'::text,'die Crew auch nicht'::text,'Die Regisseurin war mit der letzten Aufnahme der Produktion zufrieden, und die Crew auch.'::text),
(376882,41876,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Режисерка була задоволена останнім дублем постановки, і ...'::text,'знімальна група теж'::text,'знімальна група теж'::text,'знімальна група теж ні'::text,'Режисерка була задоволена останнім дублем постановки, і знімальна група теж.'::text),
(376881,41876,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La directora estaba contenta con la última toma de la producción, y ...'::text,'el equipo también'::text,'el equipo también'::text,'el equipo tampoco'::text,'La directora estaba contenta con la última toma de la producción, y el equipo también.'::text),
(376880,41876,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La réalisatrice était contente de la dernière prise de la production, et ...'::text,'l''équipe aussi'::text,'l''équipe aussi'::text,'l''équipe non plus'::text,'La réalisatrice était contente de la dernière prise de la production, et l''équipe aussi.'::text),
(376883,41876,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yönetmen prodüksiyonun son çekiminden memnundu ve ...'::text,'ekip de öyle'::text,'ekip de öyle'::text,'ekip de değildi'::text,'Yönetmen prodüksiyonun son çekiminden memnundu ve ekip de öyle.'::text),
(376884,41876,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A rendezőnő elégedett volt a produkció utolsó felvételével, és ...'::text,'a stáb is'::text,'a stáb is'::text,'a stáb sem'::text,'A rendezőnő elégedett volt a produkció utolsó felvételével, és a stáb is.'::text),
(376887,41877,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Crew ... diese Produktion seit drei Monaten, und eine schlechte Aufnahme könnte alles zerstören!'::text,'dreht'::text,'dreht'::text,'dreht'::text,'Die Crew dreht diese Produktion seit drei Monaten, und eine schlechte Aufnahme könnte alles zerstören!'::text),
(376891,41877,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Знімальна група ... цю постановку вже три місяці, і один поганий дубль може все зруйнувати!'::text,'знімає'::text,'знімає'::text,'знімає'::text,'Знімальна група знімає цю постановку вже три місяці, і один поганий дубль може все зруйнувати!'::text),
(376890,41877,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El equipo ... esta producción desde hace tres meses, y una mala toma podría destruirlo todo!'::text,'graba'::text,'está grabando'::text,'graba'::text,'¡El equipo graba esta producción desde hace tres meses, y una mala toma podría destruirlo todo!'::text),
(376889,41877,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''équipe ... cette production depuis trois mois, et une seule mauvaise prise pourrait tout détruire !'::text,'tourne'::text,'tourne'::text,'tourne'::text,'L''équipe tourne cette production depuis trois mois, et une seule mauvaise prise pourrait tout détruire !'::text),
(376892,41877,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ekip üç aydır bu prodüksiyonu ... ve tek bir kötü çekim her şeyi mahvedebilir!'::text,'çekiyor'::text,'çekiyor'::text,'çekiyor'::text,'Ekip üç aydır bu prodüksiyonu çekiyor ve tek bir kötü çekim her şeyi mahvedebilir!'::text),
(376893,41877,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A stáb három hónapja ... ezt a produkciót, és egyetlen rossz felvétel mindent tönkretehet!'::text,'forgatja'::text,'forgatja'::text,'forgatja'::text,'A stáb három hónapja forgatja ezt a produkciót, és egyetlen rossz felvétel mindent tönkretehet!'::text),
(331950,36884,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Morgen um diese Zeit ... der Baumeister weitere Kugeln an Stäbe, wie es typischerweise geschieht.'::text,'befestigt'::text,'befestigt'::text,'befestigt'::text,'Morgen um diese Zeit befestigt der Baumeister weitere Kugeln an Stäbe, wie es typischerweise geschieht.'::text),
(331954,36884,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Завтра о цій порі конструктор ... нові кульки до стрижнів, як це зазвичай відбувається.'::text,'прикріплюватиме'::text,'прикріпить'::text,'прикріплює'::text,'Завтра о цій порі конструктор прикріплюватиме нові кульки до стрижнів, як це зазвичай відбувається.'::text),
(331953,36884,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mañana a esta hora, el constructor ... más bolas a las varillas, como suele ocurrir.'::text,'estará uniendo'::text,'unirá'::text,'une'::text,'Mañana a esta hora, el constructor estará uniendo más bolas a las varillas, como suele ocurrir.'::text),
(331952,36884,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Demain à la même heure, le constructeur ... d''autres boules aux tiges, comme c''est généralement le cas.'::text,'sera en train de fixer'::text,'fixera'::text,'fixe'::text,'Demain à la même heure, le constructeur sera en train de fixer d''autres boules aux tiges, comme c''est généralement le cas.'::text),
(331955,36884,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yarın bu saatte usta, genellikle olduğu gibi, çubuklara yeni toplar ...'::text,'takıyor olacak'::text,'takacak'::text,'takıyor'::text,'Yarın bu saatte usta, genellikle olduğu gibi, çubuklara yeni toplar takıyor olacak.'::text),
(331956,36884,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Holnap ilyenkor az építő további golyókat ... a pálcákhoz, ahogy az jellemzően történik.'::text,'fog rögzíteni'::text,'rögzít'::text,'rögzít'::text,'Holnap ilyenkor az építő további golyókat fog rögzíteni a pálcákhoz, ahogy az jellemzően történik.'::text),
(331959,36885,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wären die Stäbe länger, ...'::text,'würde der Baumeister deutlich weniger Kugeln daran befestigen'::text,'wird der Baumeister deutlich weniger Kugeln daran befestigen'::text,'befestigt der Baumeister deutlich weniger Kugeln daran'::text,'Wären die Stäbe länger, würde der Baumeister deutlich weniger Kugeln daran befestigen.'::text),
(331963,36885,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби стрижні були довшими, конструктор ... до них значно менше кульок.'::text,'прикріпив би'::text,'прикріпить'::text,'прикріплює'::text,'Якби стрижні були довшими, конструктор прикріпив би до них значно менше кульок.'::text),
(331962,36885,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si las varillas fueran más largas, el constructor les ... considerablemente menos bolas.'::text,'uniría'::text,'unirá'::text,'une'::text,'Si las varillas fueran más largas, el constructor les uniría considerablemente menos bolas.'::text),
(331961,36885,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si les tiges étaient plus longues, le constructeur y ... considérablement moins de boules.'::text,'fixerait'::text,'fixera'::text,'fixe'::text,'Si les tiges étaient plus longues, le constructeur y fixerait considérablement moins de boules.'::text),
(331964,36885,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çubuklar daha uzun olsaydı usta onlara çok daha az top ...'::text,'takardı'::text,'takacak'::text,'takıyor'::text,'Çubuklar daha uzun olsaydı usta onlara çok daha az top takardı.'::text),
(331965,36885,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a pálcák hosszabbak lennének, az építő jóval kevesebb golyót ... rájuk.'::text,'rögzítene'::text,'fog rögzíteni'::text,'rögzít'::text,'Ha a pálcák hosszabbak lennének, az építő jóval kevesebb golyót rögzítene rájuk.'::text),
(331977,36887,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Hände ... die rote Kugel an den Becher, weil Hände zum Bauen da sind.'::text,'befestigen'::text,'werden befestigt'::text,'befestigend'::text,'Die Hände befestigen die rote Kugel an den Becher, weil Hände zum Bauen da sind.'::text),
(331981,36887,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Руки ... червону кульку до чашечки, бо руки — для будування.'::text,'прикріплюють'::text,'прикріплені'::text,'прикріплюючи'::text,'Руки прикріплюють червону кульку до чашечки, бо руки — для будування.'::text),
(331980,36887,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las manos ... la bola roja a la copa, porque las manos son para construir.'::text,'unen'::text,'son unidas'::text,'uniendo'::text,'Las manos unen la bola roja a la copa, porque las manos son para construir.'::text),
(331979,36887,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les mains ... la boule rouge à la coupelle, parce que les mains, c''est fait pour construire.'::text,'fixent'::text,'sont fixées'::text,'fixant'::text,'Les mains fixent la boule rouge à la coupelle, parce que les mains, c''est fait pour construire.'::text),
(331982,36887,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eller kırmızı topu kaba ..., çünkü eller yapmak içindir.'::text,'takıyor'::text,'takılıyor'::text,'takarak'::text,'Eller kırmızı topu kaba takıyor, çünkü eller yapmak içindir.'::text),
(331983,36887,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kezek ... a piros golyót a kehelyhez, mert a kéz az építésre való.'::text,'rögzítik'::text,'rögzítve vannak'::text,'rögzítve'::text,'A kezek rögzítik a piros golyót a kehelyhez, mert a kéz az építésre való.'::text),
(331986,36888,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Säule ... einstürzen, wenn noch eine Kugel befestigt wird! Beängstigend!'::text,'könnte'::text,'muss'::text,'sollte'::text,'Die Säule könnte einstürzen, wenn noch eine Kugel befestigt wird! Beängstigend!'::text),
(331990,36888,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Колона ... обвалитися, якщо прикріпити ще одну кульку! Жах!'::text,'може'::text,'мусить'::text,'повинна'::text,'Колона може обвалитися, якщо прикріпити ще одну кульку! Жах!'::text),
(331989,36888,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La columna ... derrumbarse si se une una bola más! ¡Aterrador!'::text,'podría'::text,'debe'::text,'debería'::text,'¡La columna podría derrumbarse si se une una bola más! ¡Aterrador!'::text),
(331988,36888,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La colonne ... s''effondrer si on fixe une boule de plus ! Terrifiant !'::text,'pourrait'::text,'doit'::text,'devrait'::text,'La colonne pourrait s''effondrer si on fixe une boule de plus ! Terrifiant !'::text),
(331991,36888,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir top daha takılırsa sütun ...! Korkunç!'::text,'çökebilir'::text,'çökmeli'::text,'çökmeli'::text,'Bir top daha takılırsa sütun çökebilir! Korkunç!'::text),
(331992,36888,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az oszlop ..., ha még egy golyót rögzítenek! Ijesztő!'::text,'összeomolhat'::text,'össze kell omlania'::text,'össze kellene omlania'::text,'Az oszlop összeomolhat, ha még egy golyót rögzítenek! Ijesztő!'::text),
(331995,36889,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Stab, ... sie zuletzt befestigt haben, hält den ganzen Turm zusammen, sonst stürzt alles ein!'::text,'den'::text,'der'::text,'dessen'::text,'Der Stab, den sie zuletzt befestigt haben, hält den ganzen Turm zusammen, sonst stürzt alles ein!'::text),
(331999,36889,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Стрижень, ... вони прикріпили останнім, тримає всю вежу, інакше все завалиться!'::text,'який'::text,'хто'::text,'чий'::text,'Стрижень, який вони прикріпили останнім, тримає всю вежу, інакше все завалиться!'::text),
(331998,36889,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La varilla ... unieron al final sostiene toda la torre, o todo se derrumba!'::text,'que'::text,'quien'::text,'cuya'::text,'¡La varilla que unieron al final sostiene toda la torre, o todo se derrumba!'::text),
(331997,36889,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tige ... ont fixée en dernier tient toute la tour, sinon tout s''effondre !'::text,'qu''ils'::text,'qui'::text,'dont ils'::text,'La tige qu''ils ont fixée en dernier tient toute la tour, sinon tout s''effondre !'::text),
(332000,36889,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En son ... çubuk bütün kuleyi bir arada tutuyor, yoksa her şey çöker!'::text,'taktıkları'::text,'taktıkları'::text,'taktıkları'::text,'En son taktıkları çubuk bütün kuleyi bir arada tutuyor, yoksa her şey çöker!'::text),
(332001,36889,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pálca, ... utoljára rögzítettek, tartja össze az egész tornyot, különben minden összeomlik!'::text,'amelyet'::text,'akit'::text,'amelynek'::text,'A pálca, amelyet utoljára rögzítettek, tartja össze az egész tornyot, különben minden összeomlik!'::text),
(332004,36890,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, anscheinend hat der Baumeister gesagt, er habe jedes Teil von Hand ...'::text,'befestigt'::text,'befestigt'::text,'befestige'::text,'Bestie, anscheinend hat der Baumeister gesagt, er habe jedes Teil von Hand befestigt.'::text),
(332008,36890,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, конструктор сказав, що ... кожну деталь вручну.'::text,'прикріпив'::text,'прикріпив'::text,'прикріплює'::text,'Подруго, кажуть, конструктор сказав, що прикріпив кожну деталь вручну.'::text),
(332007,36890,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, al parecer el constructor dijo que ... cada pieza a mano.'::text,'había unido'::text,'ha unido'::text,'une'::text,'Amiga, al parecer el constructor dijo que había unido cada pieza a mano.'::text),
(332006,36890,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment le constructeur a dit qu''il ... chaque pièce à la main.'::text,'avait fixé'::text,'a fixé'::text,'fixe'::text,'Ma belle, apparemment le constructeur a dit qu''il avait fixé chaque pièce à la main.'::text),
(332009,36890,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, duyduğuma göre yapan kişi her parçayı elle ... söylemiş.'::text,'taktığını'::text,'taktığını'::text,'taktığını'::text,'Kanka, duyduğuma göre yapan kişi her parçayı elle taktığını söylemiş.'::text),
(332010,36890,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag az építő azt mondta, hogy minden darabot kézzel ...'::text,'rögzített'::text,'rögzített'::text,'rögzít'::text,'Csajszi, állítólag az építő azt mondta, hogy minden darabot kézzel rögzített.'::text),
(332013,36891,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Letzten Winter ... diese Hände jeden Abend stundenlang Kugeln an Stäbe. Spannend.'::text,'befestigten'::text,'befestigten'::text,'befestigten'::text,'Letzten Winter befestigten diese Hände jeden Abend stundenlang Kugeln an Stäbe. Spannend.'::text),
(332017,36891,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Минулої зими ці руки щовечора годинами ... кульки до стрижнів. Захопливо.'::text,'прикріплювали'::text,'прикріплювали'::text,'звикли прикріплювати'::text,'Минулої зими ці руки щовечора годинами прикріплювали кульки до стрижнів. Захопливо.'::text),
(332016,36891,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El invierno pasado, cada noche, estas manos ... bolas a las varillas durante horas. Emocionante.'::text,'unían'::text,'solían unir'::text,'estaban acostumbradas a unir'::text,'El invierno pasado, cada noche, estas manos unían bolas a las varillas durante horas. Emocionante.'::text),
(332015,36891,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''hiver dernier, chaque soir, ces mains ... des boules aux tiges pendant des heures. Palpitant.'::text,'fixaient'::text,'avaient l''habitude de fixer'::text,'étaient habituées à fixer'::text,'L''hiver dernier, chaque soir, ces mains fixaient des boules aux tiges pendant des heures. Palpitant.'::text),
(332018,36891,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Geçen kış her akşam bu eller saatlerce çubuklara top ... — heyecan verici.'::text,'takardı'::text,'takardı'::text,'takmaya alışkındı'::text,'Geçen kış her akşam bu eller saatlerce çubuklara top takardı — heyecan verici.'::text),
(332019,36891,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tavaly télen ezek a kezek minden este órákig ... golyókat a pálcákhoz. Izgalmas.'::text,'rögzítettek'::text,'rögzítettek'::text,'hozzá voltak szokva, hogy rögzítsenek'::text,'Tavaly télen ezek a kezek minden este órákig rögzítettek golyókat a pálcákhoz. Izgalmas.'::text),
(332022,36892,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Hände ... immer wieder blaue Kugeln an die Enden der Stäbe.'::text,'befestigen'::text,'befestigen'::text,'befestigten'::text,'Die Hände befestigen immer wieder blaue Kugeln an die Enden der Stäbe.'::text),
(332026,36892,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Руки все ... сині кульки на кінці стрижнів.'::text,'прикріплюють'::text,'прикріплювати'::text,'прикріпили'::text,'Руки все прикріплюють сині кульки на кінці стрижнів.'::text),
(332025,36892,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las manos siguen ... bolas azules en los extremos de las varillas.'::text,'poniendo'::text,'poner'::text,'puestas'::text,'Las manos siguen poniendo bolas azules en los extremos de las varillas.'::text),
(332024,36892,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les mains continuent ... des boules bleues au bout des tiges.'::text,'de fixer'::text,'à fixer'::text,'fixées'::text,'Les mains continuent de fixer des boules bleues au bout des tiges.'::text),
(332027,36892,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eller çubukların uçlarına mavi toplar ... devam ediyor.'::text,'takmaya'::text,'takmaya'::text,'takılmış'::text,'Eller çubukların uçlarına mavi toplar takmaya devam ediyor.'::text),
(332028,36892,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kezek folyamatosan ... a kék golyókat a pálcák végére.'::text,'rögzítik'::text,'rögzíteni'::text,'rögzítették'::text,'A kezek folyamatosan rögzítik a kék golyókat a pálcák végére.'::text),
(332040,36894,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Hände ... mehrere Minuten lang Kugeln an Stäbe, bevor sie die Säule hochhoben.'::text,'befestigten'::text,'befestigten'::text,'befestigen'::text,'Die Hände befestigten mehrere Minuten lang Kugeln an Stäbe, bevor sie die Säule hochhoben.'::text),
(332044,36894,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Руки ... кульки до стрижнів кілька хвилин, перш ніж підняли колону.'::text,'прикріплювали'::text,'прикріплювали'::text,'прикріплюють'::text,'Руки прикріплювали кульки до стрижнів кілька хвилин, перш ніж підняли колону.'::text),
(332043,36894,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las manos ... bolas a varillas durante varios minutos antes de levantar la columna.'::text,'habían estado uniendo'::text,'han estado uniendo'::text,'están uniendo'::text,'Las manos habían estado uniendo bolas a varillas durante varios minutos antes de levantar la columna.'::text),
(332042,36894,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les mains ... des boules aux tiges pendant plusieurs minutes avant de soulever la colonne.'::text,'fixaient'::text,'ont fixé'::text,'fixent'::text,'Les mains fixaient des boules aux tiges pendant plusieurs minutes avant de soulever la colonne.'::text),
(332045,36894,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eller sütunu kaldırmadan önce birkaç dakika boyunca çubuklara top ...'::text,'takıyordu'::text,'takıyor'::text,'takıyor'::text,'Eller sütunu kaldırmadan önce birkaç dakika boyunca çubuklara top takıyordu.'::text),
(332046,36894,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kezek néhány percig ... a golyókat a pálcákhoz, mielőtt felemelték az oszlopot.'::text,'rögzítették'::text,'rögzítik'::text,'rögzítik'::text,'A kezek néhány percig rögzítették a golyókat a pálcákhoz, mielőtt felemelték az oszlopot.'::text),
(390540,43394,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Während sich der junge Mann auf dem Stuhl ..., beobachtete ihn sein Kollege von hinten.'::text,'drehte'::text,'drehte'::text,'gedreht hat'::text,'Während sich der junge Mann auf dem Stuhl drehte, beobachtete ihn sein Kollege von hinten.'::text),
(390544,43394,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки молодий чоловік ... на кріслі, колега спостерігав за ним ззаду.'::text,'крутився'::text,'крутнувся'::text,'крутнувся'::text,'Поки молодий чоловік крутився на кріслі, колега спостерігав за ним ззаду.'::text),
(390543,43394,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mientras el joven ... en la silla, su compañero lo observaba desde atrás.'::text,'giraba'::text,'giró'::text,'ha girado'::text,'Mientras el joven giraba en la silla, su compañero lo observaba desde atrás.'::text),
(390542,43394,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pendant que le jeune homme ... sur la chaise, son collègue l''observait de derrière.'::text,'tournait'::text,'a tourné'::text,'a tourné'::text,'Pendant que le jeune homme tournait sur la chaise, son collègue l''observait de derrière.'::text),
(390545,43394,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç adam sandalyede ... iş arkadaşı onu arkadan izledi.'::text,'dönerken'::text,'döndü'::text,'dönmüş'::text,'Genç adam sandalyede dönerken iş arkadaşı onu arkadan izledi.'::text),
(390546,43394,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miközben a fiatalember ... a széken, a kollégája hátulról figyelte.'::text,'pörgött'::text,'megpörgött'::text,'megpörgött'::text,'Miközben a fiatalember pörgött a széken, a kollégája hátulról figyelte.'::text),
(390549,43395,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... sich seit fünf Minuten auf diesem Stuhl, und jetzt ist er völlig fertig!'::text,'dreht'::text,'dreht'::text,'dreht'::text,'Er dreht sich seit fünf Minuten auf diesem Stuhl, und jetzt ist er völlig fertig!'::text),
(390553,43395,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... на тому кріслі вже п''ять хвилин, і тепер він геть розбитий!'::text,'крутиться'::text,'крутиться'::text,'крутиться'::text,'Він крутиться на тому кріслі вже п''ять хвилин, і тепер він геть розбитий!'::text),
(390552,43395,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Lleva cinco minutos ... en esa silla y ahora está completamente destrozado!'::text,'girando'::text,'girando'::text,'girando'::text,'¡Lleva cinco minutos girando en esa silla y ahora está completamente destrozado!'::text),
(390551,43395,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... sur cette chaise depuis cinq minutes, et maintenant il est complètement détruit !'::text,'tourne'::text,'tourne'::text,'tourne'::text,'Il tourne sur cette chaise depuis cinq minutes, et maintenant il est complètement détruit !'::text),
(390554,43395,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beş dakikadır o sandalyede ... ve şimdi tamamen perişan!'::text,'dönüyor'::text,'dönüyor'::text,'dönüyor'::text,'Beş dakikadır o sandalyede dönüyor ve şimdi tamamen perişan!'::text),
(390555,43395,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öt perce ... azon a széken, és most teljesen ki van készülve!'::text,'pörög'::text,'pörög'::text,'pörög'::text,'Öt perce pörög azon a széken, és most teljesen ki van készülve!'::text),
(390558,43396,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... sich gerade auf dem Stuhl im Kreis, als der Chef hereinkam. Aus und vorbei!'::text,'drehte'::text,'drehte'::text,'drehte'::text,'Er drehte sich gerade auf dem Stuhl im Kreis, als der Chef hereinkam. Aus und vorbei!'::text),
(390562,43396,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... на кріслі, коли зайшов бос. Кінець!'::text,'крутився'::text,'крутнувся'::text,'крутнувся'::text,'Він крутився на кріслі, коли зайшов бос. Кінець!'::text),
(390561,43396,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... en la silla cuando entró el jefe. ¡Se acabó!'::text,'Estaba girando'::text,'Giró'::text,'Ha girado'::text,'Estaba girando en la silla cuando entró el jefe. ¡Se acabó!'::text),
(390560,43396,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... sur la chaise quand le patron est entré. C''est la fin !'::text,'tournait'::text,'a tourné'::text,'a tourné'::text,'Il tournait sur la chaise quand le patron est entré. C''est la fin !'::text),
(390563,43396,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Patron içeri girdiğinde sandalyede ...! Bitti!'::text,'dönüyordu'::text,'döndü'::text,'dönmüş'::text,'Patron içeri girdiğinde sandalyede dönüyordu! Bitti!'::text),
(390564,43396,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... a széken, amikor bejött a főnök. Vége!'::text,'pörgött'::text,'megpörgött'::text,'megpörgött'::text,'Épp pörgött a széken, amikor bejött a főnök. Vége!'::text),
(390567,43397,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... sich zwanzigmal im Kreis, und jetzt dreht sich das ganze Büro! Katastrophe!'::text,'drehte'::text,'drehte'::text,'dreht'::text,'Er drehte sich zwanzigmal im Kreis, und jetzt dreht sich das ganze Büro! Katastrophe!'::text),
(390571,43397,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... двадцять разів, і тепер крутиться весь офіс! Катастрофа!'::text,'крутнувся'::text,'крутився'::text,'крутиться'::text,'Він крутнувся двадцять разів, і тепер крутиться весь офіс! Катастрофа!'::text),
(390570,43397,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... veinte vueltas y ahora toda la oficina da vueltas! ¡Desastre!'::text,'Ha dado'::text,'Ha estado dando'::text,'Está dando'::text,'¡Ha dado veinte vueltas y ahora toda la oficina da vueltas! ¡Desastre!'::text),
(390569,43397,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... vingt fois sur lui-même, et maintenant tout le bureau tourne ! La cata !'::text,'a tourné'::text,'a tourné'::text,'tourne'::text,'Il a tourné vingt fois sur lui-même, et maintenant tout le bureau tourne ! La cata !'::text),
(390572,43397,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yirmi kez ... ve şimdi bütün ofis dönüyor! Felaket!'::text,'döndü'::text,'dönüyordu'::text,'dönüyor'::text,'Yirmi kez döndü ve şimdi bütün ofis dönüyor! Felaket!'::text),
(390573,43397,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hússzor ... körbe, és most az egész iroda forog! Katasztrófa!'::text,'pörgött'::text,'pörgött'::text,'pörög'::text,'Hússzor pörgött körbe, és most az egész iroda forog! Katasztrófa!'::text),
(390576,43398,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schatz, sie hat mir erzählt, er ... fünfzigmal im Kreis, bevor er zu Boden rutschte.'::text,'drehte sich'::text,'drehte sich'::text,'dreht sich'::text,'Schatz, sie hat mir erzählt, er drehte sich fünfzigmal im Kreis, bevor er zu Boden rutschte.'::text),
(390580,43398,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що він ... п''ятдесят разів, перш ніж сповз на підлогу.'::text,'крутнувся'::text,'крутнувся'::text,'крутиться'::text,'Подруго, вона сказала мені, що він крутнувся п''ятдесят разів, перш ніж сповз на підлогу.'::text),
(390579,43398,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que ... cincuenta vueltas antes de caerse al suelo.'::text,'había dado'::text,'ha dado'::text,'da'::text,'Tía, me dijo que había dado cincuenta vueltas antes de caerse al suelo.'::text),
(390578,43398,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle m''a dit qu''il ... cinquante fois sur lui-même avant de glisser par terre.'::text,'avait tourné'::text,'a tourné'::text,'tourne'::text,'Ma belle, elle m''a dit qu''il avait tourné cinquante fois sur lui-même avant de glisser par terre.'::text),
(390581,43398,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana söylediğine göre yere kaymadan önce elli kez ...'::text,'dönmüştü'::text,'dönmüş'::text,'dönüyor'::text,'Kızım, bana söylediğine göre yere kaymadan önce elli kez dönmüştü.'::text),
(390582,43398,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy ötvenszer ... körbe, mielőtt lecsúszott a földre.'::text,'pörgött'::text,'pörgött'::text,'pörög'::text,'Csajszi, azt mondta, hogy ötvenszer pörgött körbe, mielőtt lecsúszott a földre.'::text),
(390585,43399,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er sich wieder auf dem Stuhl dreht, ... er um.'::text,'fällt'::text,'fiele'::text,'fiel'::text,'Wenn er sich wieder auf dem Stuhl dreht, fällt er um.'::text),
(390589,43399,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо він знову закрутиться на кріслі, він ...'::text,'впаде'::text,'впав би'::text,'впав'::text,'Якщо він знову закрутиться на кріслі, він впаде.'::text),
(390588,43399,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si vuelve a girar en la silla, ...'::text,'se caerá'::text,'se caería'::text,'se cayó'::text,'Si vuelve a girar en la silla, se caerá.'::text),
(390587,43399,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il tourne encore sur la chaise, il ...'::text,'tombera'::text,'tomberait'::text,'est tombé'::text,'S''il tourne encore sur la chaise, il tombera.'::text),
(390590,43399,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sandalyede yine dönerse ...'::text,'düşecek'::text,'düşerdi'::text,'düştü'::text,'Sandalyede yine dönerse düşecek.'::text),
(390591,43399,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha megint pörög a széken, ...'::text,'el fog esni'::text,'elesne'::text,'elesett'::text,'Ha megint pörög a széken, el fog esni.'::text),
(390594,43400,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er sich nicht so schnell drehen würde, ... ihm nicht schwindlig.'::text,'wäre'::text,'wird'::text,'war'::text,'Wenn er sich nicht so schnell drehen würde, wäre ihm nicht schwindlig.'::text),
(390598,43400,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він не крутився так швидко, у нього ... голова.'::text,'не паморочилася б'::text,'не паморочитиметься'::text,'не паморочилася'::text,'Якби він не крутився так швидко, у нього не паморочилася б голова.'::text),
(390597,43400,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no girara tan rápido, no ... mareado.'::text,'se sentiría'::text,'se sentirá'::text,'se sintió'::text,'Si no girara tan rápido, no se sentiría mareado.'::text),
(390596,43400,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il ne tournait pas si vite, il ... le tournis.'::text,'n''aurait pas'::text,'n''aura pas'::text,'n''a pas eu'::text,'S''il ne tournait pas si vite, il n''aurait pas le tournis.'::text),
(390599,43400,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu kadar hızlı dönmese başı ...'::text,'dönmezdi'::text,'dönmeyecek'::text,'dönmedi'::text,'Bu kadar hızlı dönmese başı dönmezdi.'::text),
(390600,43400,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem pörögne ilyen gyorsan, ...'::text,'nem szédülne'::text,'nem fog szédülni'::text,'nem szédült'::text,'Ha nem pörögne ilyen gyorsan, nem szédülne.'::text),
(390603,43401,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Heute Morgen ... der Bürostuhl von dem jungen Mann immer wieder im Kreis gedreht.'::text,'wurde'::text,'wird'::text,'hat'::text,'Heute Morgen wurde der Bürostuhl von dem jungen Mann immer wieder im Kreis gedreht.'::text),
(390607,43401,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Сьогодні вранці офісне крісло ... молодим чоловіком знову і знову.'::text,'було розкручене'::text,'розкручується'::text,'розкрутило'::text,'Сьогодні вранці офісне крісло було розкручене молодим чоловіком знову і знову.'::text),
(390606,43401,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Esta mañana la silla de oficina ... una y otra vez por el joven.'::text,'fue girada'::text,'es girada'::text,'giró'::text,'Esta mañana la silla de oficina fue girada una y otra vez por el joven.'::text),
(390605,43401,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ce matin, la chaise de bureau ... encore et encore par le jeune homme.'::text,'a été tournée'::text,'est tournée'::text,'a tourné'::text,'Ce matin, la chaise de bureau a été tournée encore et encore par le jeune homme.'::text),
(390608,43401,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sabah ofis sandalyesi genç adam tarafından durmadan ...'::text,'döndürüldü'::text,'döndürülüyor'::text,'döndü'::text,'Bu sabah ofis sandalyesi genç adam tarafından durmadan döndürüldü.'::text),
(390609,43401,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma reggel az irodai széket a fiatalember körbe-körbe ...'::text,'pörgette'::text,'pörgeti'::text,'pörgött'::text,'Ma reggel az irodai széket a fiatalember körbe-körbe pörgette.'::text),
(390612,43402,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der junge Mann ... den Stuhl mit hochgelegten Füßen im Kreis.'::text,'drehte'::text,'wurde gedreht'::text,'drehend'::text,'Der junge Mann drehte den Stuhl mit hochgelegten Füßen im Kreis.'::text),
(390616,43402,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Молодий чоловік ... крісло по колу, задерши ноги.'::text,'крутив'::text,'був закручений'::text,'крутячи'::text,'Молодий чоловік крутив крісло по колу, задерши ноги.'::text),
(390615,43402,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El joven ... la silla con los pies en alto.'::text,'hizo girar'::text,'fue girado'::text,'girando'::text,'El joven hizo girar la silla con los pies en alto.'::text),
(390614,43402,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le jeune homme ... la chaise, les pieds en l''air.'::text,'a fait tourner'::text,'a été tourné'::text,'faisant tourner'::text,'Le jeune homme a fait tourner la chaise, les pieds en l''air.'::text),
(390617,43402,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Genç adam ayaklarını kaldırıp sandalyeyi ...'::text,'döndürdü'::text,'döndürüldü'::text,'döndürerek'::text,'Genç adam ayaklarını kaldırıp sandalyeyi döndürdü.'::text),
(390618,43402,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A fiatalember feltett lábbal ... a széket.'::text,'megpörgette'::text,'meg lett pörgetve'::text,'pörgetve'::text,'A fiatalember feltett lábbal megpörgette a széket.'::text),
(390621,43403,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... des 30-maligen Drehens auf dem Stuhl konnte er die Deadline nicht einhalten.'::text,'Infolge'::text,'Obwohl'::text,'Im Falle'::text,'Infolge des 30-maligen Drehens auf dem Stuhl konnte er die Deadline nicht einhalten.'::text),
(390625,43403,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... того, що він 30 разів крутився на кріслі, він не встиг до дедлайну.'::text,'Внаслідок'::text,'Хоча'::text,'У разі'::text,'Внаслідок того, що він 30 разів крутився на кріслі, він не встиг до дедлайну.'::text),
(390624,43403,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... dar 30 vueltas en la silla, no pudo cumplir el plazo.'::text,'Como consecuencia de'::text,'Aunque'::text,'En caso de'::text,'Como consecuencia de dar 30 vueltas en la silla, no pudo cumplir el plazo.'::text),
(390623,43403,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... ses 30 tours sur la chaise, il n''a pas pu respecter l''échéance.'::text,'À la suite de'::text,'Bien que'::text,'En cas de'::text,'À la suite de ses 30 tours sur la chaise, il n''a pas pu respecter l''échéance.'::text),
(390626,43403,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sandalyede 30 kez dönmesinin ... teslim tarihine yetişemedi.'::text,'sonucunda'::text,'rağmen'::text,'durumunda'::text,'Sandalyede 30 kez dönmesinin sonucunda teslim tarihine yetişemedi.'::text),
(390627,43403,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A széken való 30-szoros pörgés ... nem tudta tartani a határidőt.'::text,'következtében'::text,'bár'::text,'esetén'::text,'A széken való 30-szoros pörgés következtében nem tudta tartani a határidőt.'::text),
(390630,43404,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis sein Kollege ihm aufhilft, ..., sich zu drehen.'::text,'wird der Raum aufgehört haben'::text,'wird der Raum aufhören'::text,'hört der Raum auf'::text,'Bis sein Kollege ihm aufhilft, wird der Raum aufgehört haben, sich zu drehen.'::text),
(390634,43404,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки колега допоможе йому підвестися, кімната ... крутитися.'::text,'перестане'::text,'перестане'::text,'перестає'::text,'Поки колега допоможе йому підвестися, кімната перестане крутитися.'::text),
(390633,43404,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando su compañero lo ayude a levantarse, la habitación ... de dar vueltas.'::text,'habrá dejado'::text,'dejará'::text,'deja'::text,'Para cuando su compañero lo ayude a levantarse, la habitación habrá dejado de dar vueltas.'::text),
(390632,43404,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce que son collègue l''aide à se relever, la pièce ... de tourner.'::text,'aura arrêté'::text,'arrêtera'::text,'arrête'::text,'D''ici à ce que son collègue l''aide à se relever, la pièce aura arrêté de tourner.'::text),
(390635,43404,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İş arkadaşı onu kaldırana kadar oda dönmeyi ...'::text,'bırakmış olacak'::text,'bırakacak'::text,'bırakıyor'::text,'İş arkadaşı onu kaldırana kadar oda dönmeyi bırakmış olacak.'::text),
(390636,43404,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a kollégája felsegíti, a szoba ... a forgást.'::text,'abbahagyja'::text,'abba fogja hagyni'::text,'abbahagyja'::text,'Mire a kollégája felsegíti, a szoba abbahagyja a forgást.'::text),
(396003,44001,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er seinen Teddy nicht mitgebracht hätte, ...'::text,'wäre der Junge beim Arzt nicht so ruhig geblieben'::text,'wird der Junge beim Arzt nicht so ruhig bleiben'::text,'blieb der Junge beim Arzt nicht so ruhig'::text,'Wenn er seinen Teddy nicht mitgebracht hätte, wäre der Junge beim Arzt nicht so ruhig geblieben.'::text),
(396007,44001,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він не взяв свого ведмедика, хлопчик ... таким спокійним у лікаря.'::text,'не залишився б'::text,'не залишиться'::text,'не залишився'::text,'Якби він не взяв свого ведмедика, хлопчик не залишився б таким спокійним у лікаря.'::text),
(396006,44001,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si no hubiera traído su osito, el niño ... tan tranquilo en el médico.'::text,'no se habría quedado'::text,'no se quedará'::text,'no se quedó'::text,'Si no hubiera traído su osito, el niño no se habría quedado tan tranquilo en el médico.'::text),
(396005,44001,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il n''avait pas apporté son nounours, le garçon ... aussi calme chez le médecin.'::text,'ne serait pas resté'::text,'ne restera pas'::text,'n''est pas resté'::text,'S''il n''avait pas apporté son nounours, le garçon ne serait pas resté aussi calme chez le médecin.'::text),
(396008,44001,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oyuncak ayısını getirmeseydi çocuk doktorda bu kadar sakin ...'::text,'kalmazdı'::text,'kalmayacak'::text,'kalmadı'::text,'Oyuncak ayısını getirmeseydi çocuk doktorda bu kadar sakin kalmazdı.'::text),
(396009,44001,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha nem hozta volna el a macit, a kisfiú ... ilyen nyugodt az orvosnál.'::text,'nem maradt volna'::text,'nem fog maradni'::text,'nem maradt'::text,'Ha nem hozta volna el a macit, a kisfiú nem maradt volna ilyen nyugodt az orvosnál.'::text),
(379083,42121,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... die blaue Flüssigkeit, als die Reaktion aus dem Kolben explodierte!'::text,'goss gerade'::text,'goss'::text,'goss'::text,'Er goss gerade die blaue Flüssigkeit, als die Reaktion aus dem Kolben explodierte!'::text),
(379087,42121,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... синю рідину, коли реакція вибухнула з колби!'::text,'наливав'::text,'налив'::text,'налив'::text,'Він наливав синю рідину, коли реакція вибухнула з колби!'::text),
(379086,42121,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡... el líquido azul cuando la reacción explotó fuera del matraz!'::text,'Estaba echando'::text,'Echó'::text,'Ha echado'::text,'¡Estaba echando el líquido azul cuando la reacción explotó fuera del matraz!'::text),
(379085,42121,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... le liquide bleu quand la réaction a explosé hors de la fiole !'::text,'versait'::text,'a versé'::text,'a versé'::text,'Il versait le liquide bleu quand la réaction a explosé hors de la fiole !'::text),
(379088,42121,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tepkime şişeden patladığında mavi sıvıyı ...!'::text,'döküyordu'::text,'döktü'::text,'dökmüş'::text,'Tepkime şişeden patladığında mavi sıvıyı döküyordu!'::text),
(379089,42121,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... a kék folyadékot, amikor a reakció kirobbant a lombikból!'::text,'öntötte'::text,'kiöntötte'::text,'kiöntötte'::text,'Épp öntötte a kék folyadékot, amikor a reakció kirobbant a lombikból!'::text),
(379092,42122,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Reaktion ... schon eine ganze Minute, und der Schaum ist völlig außer Kontrolle!'::text,'läuft'::text,'läuft'::text,'läuft'::text,'Die Reaktion läuft schon eine ganze Minute, und der Schaum ist völlig außer Kontrolle!'::text),
(379096,42122,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Реакція ... вже цілу хвилину, і піна геть вийшла з-під контролю!'::text,'триває'::text,'триває'::text,'триває'::text,'Реакція триває вже цілу хвилину, і піна геть вийшла з-під контролю!'::text),
(379095,42122,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡La reacción ... desde hace un minuto entero y la espuma está totalmente descontrolada!'::text,'dura'::text,'está durando'::text,'dura'::text,'¡La reacción dura desde hace un minuto entero y la espuma está totalmente descontrolada!'::text),
(379094,42122,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La réaction ... depuis une bonne minute, et la mousse est complètement hors de contrôle !'::text,'dure'::text,'dure'::text,'dure'::text,'La réaction dure depuis une bonne minute, et la mousse est complètement hors de contrôle !'::text),
(379097,42122,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tepkime tam bir dakikadır ... ve köpük tamamen kontrolden çıktı!'::text,'sürüyor'::text,'sürüyor'::text,'sürüyor'::text,'Tepkime tam bir dakikadır sürüyor ve köpük tamamen kontrolden çıktı!'::text),
(379098,42122,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A reakció már egy teljes perce ..., és a hab teljesen kicsúszott az irányítás alól!'::text,'tart'::text,'tart'::text,'tart'::text,'A reakció már egy teljes perce tart, és a hab teljesen kicsúszott az irányítás alól!'::text),
(379101,42123,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Okay, also sie hat mir erzählt, die ganze Klasse ... zu, als die Reaktion anfing.'::text,'schaute gerade'::text,'schaute'::text,'schaute'::text,'Okay, also sie hat mir erzählt, die ganze Klasse schaute gerade zu, als die Reaktion anfing.'::text),
(379105,42123,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Отже, вона сказала мені, що весь клас ..., коли почалася реакція.'::text,'дивився'::text,'подивився'::text,'подивився'::text,'Отже, вона сказала мені, що весь клас дивився, коли почалася реакція.'::text),
(379104,42123,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Vale, pues me dijo que toda la clase ... cuando empezó la reacción.'::text,'estaba mirando'::text,'miró'::text,'ha mirado'::text,'Vale, pues me dijo que toda la clase estaba mirando cuando empezó la reacción.'::text),
(379103,42123,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ok, donc elle m''a dit que toute la classe ... quand la réaction a commencé.'::text,'regardait'::text,'a regardé'::text,'a regardé'::text,'Ok, donc elle m''a dit que toute la classe regardait quand la réaction a commencé.'::text),
(379106,42123,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tamam, bana dediğine göre tepkime başladığında bütün sınıf ...'::text,'izliyordu'::text,'izledi'::text,'izlemiş'::text,'Tamam, bana dediğine göre tepkime başladığında bütün sınıf izliyordu.'::text),
(379107,42123,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Oké, szóval azt mondta, hogy az egész osztály ..., amikor a reakció elkezdődött.'::text,'figyelt'::text,'odanézett'::text,'odanézett'::text,'Oké, szóval azt mondta, hogy az egész osztály figyelt, amikor a reakció elkezdődött.'::text),
(379110,42124,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schaum steigt immer noch, also ... die Reaktion noch nicht vorbei sein.'::text,'kann'::text,'muss'::text,'darf'::text,'Der Schaum steigt immer noch, also kann die Reaktion noch nicht vorbei sein.'::text),
(379114,42124,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Піна досі піднімається, тож реакція ще ... закінчитися.'::text,'не може'::text,'мусить'::text,'не повинна'::text,'Піна досі піднімається, тож реакція ще не може закінчитися.'::text),
(379113,42124,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La espuma sigue subiendo, así que la reacción ... haber terminado todavía.'::text,'no puede'::text,'debe'::text,'no debe'::text,'La espuma sigue subiendo, así que la reacción no puede haber terminado todavía.'::text),
(379112,42124,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mousse monte encore, donc la réaction ... être déjà finie.'::text,'ne peut pas'::text,'doit'::text,'ne doit pas'::text,'La mousse monte encore, donc la réaction ne peut pas être déjà finie.'::text),
(379115,42124,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Köpük hâlâ yükseliyor, yani tepkime henüz ...'::text,'bitmiş olamaz'::text,'bitmiş olmalı'::text,'bitmemeli'::text,'Köpük hâlâ yükseliyor, yani tepkime henüz bitmiş olamaz.'::text),
(379116,42124,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A hab még mindig emelkedik, szóval a reakció még ...'::text,'nem érhetett véget'::text,'biztosan véget ért'::text,'nem szabad véget érnie'::text,'A hab még mindig emelkedik, szóval a reakció még nem érhetett véget.'::text),
(379119,42125,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Schüler, ... die Reaktion gestartet hat, weicht überrascht zurück.'::text,'der'::text,'welcher'::text,'dessen'::text,'Der Schüler, der die Reaktion gestartet hat, weicht überrascht zurück.'::text),
(379123,42125,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учень, ... запустив реакцію, здивовано відступає.'::text,'який'::text,'котрий'::text,'чий'::text,'Учень, який запустив реакцію, здивовано відступає.'::text),
(379122,42125,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El estudiante ... inició la reacción retrocede sorprendido.'::text,'que'::text,'el cual'::text,'cuyo'::text,'El estudiante que inició la reacción retrocede sorprendido.'::text),
(379121,42125,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''élève ... a lancé la réaction recule, surpris.'::text,'qui'::text,'lequel'::text,'dont'::text,'L''élève qui a lancé la réaction recule, surpris.'::text),
(379124,42125,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tepkimeyi ... öğrenci şaşkınlıkla geri çekiliyor.'::text,'başlatan'::text,'başlatan'::text,'başlattığı'::text,'Tepkimeyi başlatan öğrenci şaşkınlıkla geri çekiliyor.'::text),
(379125,42125,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A diák, ... elindította a reakciót, meglepetten hátralép.'::text,'aki'::text,'amely'::text,'akinek'::text,'A diák, aki elindította a reakciót, meglepetten hátralép.'::text),
(379137,42127,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, Naturwissenschaften ... früher mega lame, aber diese Reaktion hat echt abgeliefert.'::text,'waren'::text,'wären'::text,'waren gewohnt'::text,'Bro, Naturwissenschaften waren früher mega lame, aber diese Reaktion hat echt abgeliefert.'::text),
(379141,42127,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, уроки природничих раніше ... так собі, але ця реакція реально розірвала.'::text,'були'::text,'були б'::text,'звикли бути'::text,'Бро, уроки природничих раніше були так собі, але ця реакція реально розірвала.'::text),
(379140,42127,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, la clase de ciencias ... ser un rollo, pero esta reacción la petó.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'Bro, la clase de ciencias solía ser un rollo, pero esta reacción la petó.'::text),
(379139,42127,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, les cours de sciences ..., mais cette réaction, elle a trop géré.'::text,'avaient l''habitude d''être nuls'::text,'étaient nuls'::text,'étaient habitués à être nuls'::text,'Frérot, les cours de sciences avaient l''habitude d''être nuls, mais cette réaction, elle a trop géré.'::text),
(379142,42127,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, fen dersleri eskiden ..., ama bu tepkime resmen şov yaptı.'::text,'sıkıcıydı'::text,'sıkıcı olurdu'::text,'sıkıcı olmaya alışkındı'::text,'Kanka, fen dersleri eskiden sıkıcıydı, ama bu tepkime resmen şov yaptı.'::text),
(379143,42127,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, a természettudomány óra régen ..., de ez a reakció most nagyon ütött.'::text,'uncsi volt'::text,'uncsi szokott lenni'::text,'hozzá volt szokva, hogy uncsi legyen'::text,'Tesó, a természettudomány óra régen uncsi volt, de ez a reakció most nagyon ütött.'::text),
(379146,42128,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Labor plant, diese Reaktion vor der Deadline noch 3-mal zu ...'::text,'wiederholen'::text,'wiederholen'::text,'wiederholen'::text,'Das Labor plant, diese Reaktion vor der Deadline noch 3-mal zu wiederholen.'::text),
(379150,42128,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Лабораторія планує ... цю реакцію ще 3 рази до дедлайну.'::text,'повторити'::text,'повторення'::text,'повторити'::text,'Лабораторія планує повторити цю реакцію ще 3 рази до дедлайну.'::text),
(379149,42128,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El laboratorio planea ... esta reacción 3 veces más antes de la fecha límite.'::text,'repetir'::text,'repetir'::text,'repetir'::text,'El laboratorio planea repetir esta reacción 3 veces más antes de la fecha límite.'::text),
(379148,42128,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le laboratoire prévoit de ... cette réaction 3 fois de plus avant l''échéance.'::text,'répéter'::text,'répéter'::text,'répéter'::text,'Le laboratoire prévoit de répéter cette réaction 3 fois de plus avant l''échéance.'::text),
(379151,42128,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Laboratuvar, teslim tarihinden önce bu tepkimeyi 3 kez daha ... planlıyor.'::text,'tekrarlamayı'::text,'tekrarlamayı'::text,'tekrarlamayı'::text,'Laboratuvar, teslim tarihinden önce bu tepkimeyi 3 kez daha tekrarlamayı planlıyor.'::text),
(379152,42128,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A labor azt tervezi, hogy a határidő előtt még 3-szor ... ezt a reakciót.'::text,'megismétli'::text,'megismétli'::text,'megismétli'::text,'A labor azt tervezi, hogy a határidő előtt még 3-szor megismétli ezt a reakciót.'::text),
(379164,42130,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'In diesem Moment ... die Reaktion eine Schaumsäule, was für diesen Prozess typisch ist.'::text,'erzeugt'::text,'erzeugt'::text,'erzeugte'::text,'In diesem Moment erzeugt die Reaktion eine Schaumsäule, was für diesen Prozess typisch ist.'::text),
(379168,42130,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цієї миті реакція ... стовп піни, що типово для цього процесу.'::text,'утворює'::text,'утворює'::text,'утворила'::text,'Цієї миті реакція утворює стовп піни, що типово для цього процесу.'::text),
(379167,42130,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este momento la reacción ... una columna de espuma, algo típico de este proceso.'::text,'está produciendo'::text,'produce'::text,'ha producido'::text,'En este momento la reacción está produciendo una columna de espuma, algo típico de este proceso.'::text),
(379166,42130,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, la réaction ... une colonne de mousse, ce qui est typique de ce processus.'::text,'produit'::text,'produit'::text,'a produit'::text,'En ce moment, la réaction produit une colonne de mousse, ce qui est typique de ce processus.'::text),
(379169,42130,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda tepkime bir köpük sütunu ..., bu da bu süreç için tipiktir.'::text,'oluşturuyor'::text,'oluşturur'::text,'oluşturdu'::text,'Şu anda tepkime bir köpük sütunu oluşturuyor, bu da bu süreç için tipiktir.'::text),
(379170,42130,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ebben a pillanatban a reakció egy haboszlopot ..., ami jellemző erre a folyamatra.'::text,'hoz létre'::text,'hoz létre'::text,'hozott létre'::text,'Ebben a pillanatban a reakció egy haboszlopot hoz létre, ami jellemző erre a folyamatra.'::text),
(379173,42131,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als der Lehrer ankam, ... die Reaktion den ganzen Tisch schon mit Schaum! Katastrophe!'::text,'überzog'::text,'überzog'::text,'überzieht'::text,'Als der Lehrer ankam, überzog die Reaktion den ganzen Tisch schon mit Schaum! Katastrophe!'::text),
(379177,42131,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли прийшов учитель, реакція ... весь стіл піною! Катастрофа!'::text,'вкрила'::text,'вкрила'::text,'вкриває'::text,'Коли прийшов учитель, реакція вкрила весь стіл піною! Катастрофа!'::text),
(379176,42131,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para cuando llegó el profesor, la reacción ... toda la mesa de espuma! ¡Desastre!'::text,'había cubierto'::text,'ha cubierto'::text,'cubre'::text,'¡Para cuando llegó el profesor, la reacción había cubierto toda la mesa de espuma! ¡Desastre!'::text),
(379175,42131,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand le prof est arrivé, la réaction ... toute la paillasse de mousse ! Catastrophe !'::text,'avait couvert'::text,'a couvert'::text,'couvre'::text,'Quand le prof est arrivé, la réaction avait couvert toute la paillasse de mousse ! Catastrophe !'::text),
(379178,42131,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğretmen geldiğinde tepkime bütün tezgâhı köpükle ...! Felaket!'::text,'kaplamıştı'::text,'kapladı'::text,'kaplıyor'::text,'Öğretmen geldiğinde tepkime bütün tezgâhı köpükle kaplamıştı! Felaket!'::text),
(379179,42131,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a tanár megérkezett, a reakció ... az egész asztalt habbal! Katasztrófa!'::text,'beborította'::text,'beborította'::text,'beborítja'::text,'Mire a tanár megérkezett, a reakció beborította az egész asztalt habbal! Katasztrófa!'::text),
