(367836,40871,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El primer delfín es un animal marino, y ...'::text,'el segundo también'::text,'el segundo también'::text,'el segundo tampoco'::text,'El primer delfín es un animal marino, y el segundo también.'::text),
