(341472,37942,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beide schwören, sie ... nächstes Jahr wieder gegeneinander an. Offensichtlich hat niemand etwas gelernt.'::text,'treten'::text,'treten'::text,'treten'::text,'Beide schwören, sie treten nächstes Jahr wieder gegeneinander an. Offensichtlich hat niemand etwas gelernt.'::text),
(341476,37942,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Обидва клянуться, що ... знову наступного року. Очевидно, ніхто нічого не зрозумів.'::text,'змагатимуться'::text,'змагатимуться'::text,'змагаються'::text,'Обидва клянуться, що змагатимуться знову наступного року. Очевидно, ніхто нічого не зрозумів.'::text),
(341475,37942,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los dos juran que ... de nuevo el año que viene. Está claro que nadie aprendió nada.'::text,'competirán'::text,'estarán compitiendo'::text,'compiten'::text,'Los dos juran que competirán de nuevo el año que viene. Está claro que nadie aprendió nada.'::text),
(341474,37942,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tous les deux jurent qu''ils ... de nouveau l''année prochaine. Visiblement, personne n''a rien appris.'::text,'s''affronteront'::text,'s''affronteront'::text,'s''affrontent'::text,'Tous les deux jurent qu''ils s''affronteront de nouveau l''année prochaine. Visiblement, personne n''a rien appris.'::text),
(341477,37942,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'İkisi de seneye yine ... yemin ediyor. Belli ki kimse bir şey öğrenmemiş.'::text,'yarışacaklarına'::text,'yarışıyor olacaklarına'::text,'yarıştıklarına'::text,'İkisi de seneye yine yarışacaklarına yemin ediyor. Belli ki kimse bir şey öğrenmemiş.'::text),
(341478,37942,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mindketten esküsznek, hogy ... jövőre újra. Nyilván senki nem tanult semmit.'::text,'versenyezni fognak'::text,'versenyezni fognak'::text,'versenyeznek'::text,'Mindketten esküsznek, hogy versenyezni fognak jövőre újra. Nyilván senki nem tanult semmit.'::text),
(341490,37944,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie treten vor einer großen Menge gegeneinander an, ...'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Sie treten vor einer großen Menge gegeneinander an, oder?'::text),
(341494,37944,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вони змагаються перед великим натовпом, ...'::text,'так?'::text,'так?'::text,'так?'::text,'Вони змагаються перед великим натовпом, так?'::text),
(341493,37944,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Compiten delante de una gran multitud, ...'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'Compiten delante de una gran multitud, ¿verdad?'::text),
