(341495,37944,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Büyük bir kalabalığın önünde yarışıyorlar, ...'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Büyük bir kalabalığın önünde yarışıyorlar, değil mi?'::text),
