(341499,37945,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Frau wollte nicht aufhören zu kämpfen, und ...'::text,'der Mann auch nicht'::text,'der Mann auch'::text,'der Mann auch nicht'::text,'Die Frau wollte nicht aufhören zu kämpfen, und der Mann auch nicht.'::text),
(341503,37945,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Жінка не хотіла припиняти змагатися, і ...'::text,'чоловік теж ні'::text,'чоловік теж'::text,'чоловік теж ні'::text,'Жінка не хотіла припиняти змагатися, і чоловік теж ні.'::text),
(341502,37945,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La mujer no quería dejar de competir, y ...'::text,'el hombre tampoco'::text,'el hombre también'::text,'el hombre tampoco'::text,'La mujer no quería dejar de competir, y el hombre tampoco.'::text),
(341501,37945,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La femme ne voulait pas arrêter la compétition, et ...'::text,'l''homme non plus'::text,'l''homme aussi'::text,'l''homme non plus'::text,'La femme ne voulait pas arrêter la compétition, et l''homme non plus.'::text),
(341504,37945,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kadın yarışmayı bırakmak istemedi ve ...'::text,'adam da istemedi'::text,'adam da istedi'::text,'adam da değildi'::text,'Kadın yarışmayı bırakmak istemedi ve adam da istemedi.'::text),
(341505,37945,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A nő nem akarta abbahagyni a versenyzést, és ...'::text,'a férfi sem'::text,'a férfi is'::text,'a férfi sem'::text,'A nő nem akarta abbahagyni a versenyzést, és a férfi sem.'::text),
(341508,37946,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis zum Ende des Tages ... sie gegen zwanzig Rivalen angetreten sein. Totaler Krieg!'::text,'werden'::text,'werden'::text,'werden'::text,'Bis zum Ende des Tages werden sie gegen zwanzig Rivalen angetreten sein. Totaler Krieg!'::text),
(341512,37946,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До кінця дня вони ... з двадцятьма суперниками. Тотальна війна!'::text,'позмагаються'::text,'змагатимуться'::text,'змагатимуться'::text,'До кінця дня вони позмагаються з двадцятьма суперниками. Тотальна війна!'::text),
