(370321,41147,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Поки він дійде до кухні, він ... бруд по всій чистій дерев''яній підлозі.'::text,'розтягне'::text,'розтягне'::text,'розтягує'::text,'Поки він дійде до кухні, він розтягне бруд по всій чистій дерев''яній підлозі.'::text),
(370320,41147,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para cuando llegue a la cocina, ... barro por todo el suelo limpio de madera.'::text,'habrá dejado'::text,'dejará'::text,'deja'::text,'Para cuando llegue a la cocina, habrá dejado barro por todo el suelo limpio de madera.'::text),
(370319,41147,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici à ce qu''il arrive à la cuisine, il ... de la boue partout sur le parquet propre.'::text,'aura laissé'::text,'laissera'::text,'laisse'::text,'D''ici à ce qu''il arrive à la cuisine, il aura laissé de la boue partout sur le parquet propre.'::text),
(370322,41147,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mutfağa varana kadar temiz ahşap zeminin her yerine çamur ...'::text,'bırakmış olacak'::text,'bırakacak'::text,'bırakıyor'::text,'Mutfağa varana kadar temiz ahşap zeminin her yerine çamur bırakmış olacak.'::text),
(370323,41147,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire a konyhába ér, ... az egész tiszta fapadlót.'::text,'összesarazza'::text,'össze fogja sarazni'::text,'összesarazza'::text,'Mire a konyhába ér, összesarazza az egész tiszta fapadlót.'::text),
(370326,41148,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn er seine Stiefel ausgezogen hätte, ...'::text,'hätte er keinen Schlamm auf den sauberen Flurboden getragen'::text,'wird er keinen Schlamm auf den sauberen Flurboden tragen'::text,'trug er keinen Schlamm auf den sauberen Flurboden'::text,'Wenn er seine Stiefel ausgezogen hätte, hätte er keinen Schlamm auf den sauberen Flurboden getragen.'::text),
(370330,41148,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби він зняв чоботи, він ... бруд на чисту підлогу в коридорі.'::text,'не заніс би'::text,'не занесе'::text,'не заніс'::text,'Якби він зняв чоботи, він не заніс би бруд на чисту підлогу в коридорі.'::text),
(370329,41148,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si se hubiera quitado las botas, ... barro al suelo limpio del pasillo.'::text,'no habría traído'::text,'no traerá'::text,'no trajo'::text,'Si se hubiera quitado las botas, no habría traído barro al suelo limpio del pasillo.'::text),
(370328,41148,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'S''il avait enlevé ses bottes, il ... de boue sur le sol propre du couloir.'::text,'n''aurait pas apporté'::text,'n''apportera pas'::text,'n''a pas apporté'::text,'S''il avait enlevé ses bottes, il n''aurait pas apporté de boue sur le sol propre du couloir.'::text),
(370331,41148,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Botlarını çıkarsaydı koridorun temiz zeminine çamur ...'::text,'getirmezdi'::text,'getirmeyecek'::text,'getirmedi'::text,'Botlarını çıkarsaydı koridorun temiz zeminine çamur getirmezdi.'::text),
(370332,41148,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha levette volna a csizmáját, ... sarat a folyosó tiszta padlójára.'::text,'nem hordott volna be'::text,'nem fog behordani'::text,'nem hordott be'::text,'Ha levette volna a csizmáját, nem hordott volna be sarat a folyosó tiszta padlójára.'::text),
(370335,41149,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er bestritt, Schlamm in den Flur ..., der jetzt natürlich blitzblank ist.'::text,'getragen zu haben'::text,'zu tragen'::text,'getragen'::text,'Er bestritt, Schlamm in den Flur getragen zu haben, der jetzt natürlich blitzblank ist.'::text),
(370339,41149,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він заперечив, що ... бруд у коридор, який тепер, звісно, сяє чистотою.'::text,'заніс'::text,'занести'::text,'заніс'::text,'Він заперечив, що заніс бруд у коридор, який тепер, звісно, сяє чистотою.'::text),
(370338,41149,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Negó ... barro al pasillo, que obviamente ahora está impecable.'::text,'haber traído'::text,'traer'::text,'trajo'::text,'Negó haber traído barro al pasillo, que obviamente ahora está impecable.'::text),
(370337,41149,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a nié ... de la boue dans le couloir, qui est évidemment impeccable maintenant.'::text,'avoir apporté'::text,'apporter'::text,'apporté'::text,'Il a nié avoir apporté de la boue dans le couloir, qui est évidemment impeccable maintenant.'::text),
(370340,41149,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Koridora hiç çamur ... inkâr etti; koridor şimdi tabii ki tertemiz.'::text,'getirdiğini'::text,'getirmeyi'::text,'getirdi'::text,'Koridora hiç çamur getirdiğini inkâr etti; koridor şimdi tabii ki tertemiz.'::text),
(370341,41149,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tagadta, hogy ... bármi sarat a folyosóra, ami most nyilván makulátlan.'::text,'behordott'::text,'behordja'::text,'behordott'::text,'Tagadta, hogy behordott bármi sarat a folyosóra, ami most nyilván makulátlan.'::text),
(370344,41150,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... die Stiefel ausziehen sollen; der ganze Schlamm auf dem sauberen Boden ist makellose Arbeit.'::text,'hätte'::text,'muss'::text,'konnte'::text,'Er hätte die Stiefel ausziehen sollen; der ganze Schlamm auf dem sauberen Boden ist makellose Arbeit.'::text),
(370348,41150,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Йому ... зняти чоботи; увесь цей бруд на чистій підлозі — бездоганна робота.'::text,'варто було'::text,'мабуть, довелося'::text,'можна було'::text,'Йому варто було зняти чоботи; увесь цей бруд на чистій підлозі — бездоганна робота.'::text),
(370347,41150,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... quitado las botas; todo ese barro en el suelo limpio es un trabajo impecable.'::text,'Debería haberse'::text,'Debe de haberse'::text,'Pudo haberse'::text,'Debería haberse quitado las botas; todo ese barro en el suelo limpio es un trabajo impecable.'::text),
(370346,41150,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... enlever ses bottes ; toute cette boue sur le sol propre, c''est du travail impeccable.'::text,'aurait dû'::text,'a dû'::text,'pouvait'::text,'Il aurait dû enlever ses bottes ; toute cette boue sur le sol propre, c''est du travail impeccable.'::text),
(370349,41150,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Botlarını ...; temiz zemindeki bütün o çamur kusursuz bir iş.'::text,'çıkarmalıydı'::text,'çıkarmış olmalı'::text,'çıkarabilirdi'::text,'Botlarını çıkarmalıydı; temiz zemindeki bütün o çamur kusursuz bir iş.'::text),
(370350,41150,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'...; az a sok sár a tiszta padlón hibátlan munka.'::text,'Le kellett volna vennie a csizmáját'::text,'Biztosan levette a csizmáját'::text,'Levehette volna a csizmáját'::text,'Le kellett volna vennie a csizmáját; az a sok sár a tiszta padlón hibátlan munka.'::text),
(370353,41151,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gönn ich ihm: Nachdem er den ganzen Schlamm reingetragen hat, muss er den Boden ... lassen.'::text,'putzen'::text,'putzen'::text,'putzen'::text,'Gönn ich ihm: Nachdem er den ganzen Schlamm reingetragen hat, muss er den Boden putzen lassen.'::text),
(370357,41151,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Так йому й треба: після всього того бруду, який він наніс, йому доведеться замовити ... підлоги.'::text,'прибирання'::text,'прибирання'::text,'прибирання'::text,'Так йому й треба: після всього того бруду, який він наніс, йому доведеться замовити прибирання підлоги.'::text),
(370356,41151,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Me encanta por él: tendrá que mandar a ... el suelo después de meter todo ese barro.'::text,'limpiar'::text,'limpiar'::text,'limpiar'::text,'Me encanta por él: tendrá que mandar a limpiar el suelo después de meter todo ese barro.'::text),
(370355,41151,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bien fait pour lui : il va devoir faire ... le sol après avoir ramené toute cette boue.'::text,'nettoyer'::text,'nettoyer'::text,'nettoyer'::text,'Bien fait pour lui : il va devoir faire nettoyer le sol après avoir ramené toute cette boue.'::text),
(370358,41151,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hak etti valla: içeri o kadar çamur taşıdıktan sonra yeri ... zorunda kalacak.'::text,'temizletmek'::text,'temizletmek'::text,'temizletmek'::text,'Hak etti valla: içeri o kadar çamur taşıdıktan sonra yeri temizletmek zorunda kalacak.'::text),
(370359,41151,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jár neki: miután behordta azt a sok sarat, ... a padlót.'::text,'ki kell takaríttatnia'::text,'ki kell takaríttatnia'::text,'ki kell takaríttatnia'::text,'Jár neki: miután behordta azt a sok sarat, ki kell takaríttatnia a padlót.'::text),
(370371,41153,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Flurboden, ... vor einer Minute noch blitzblank war, ist jetzt eine totale Schlammkatastrophe!'::text,'der'::text,'der'::text,'der'::text,'Der Flurboden, der vor einer Minute noch blitzblank war, ist jetzt eine totale Schlammkatastrophe!'::text),
(370375,41153,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Підлога в коридорі, ... ще хвилину тому сяяла чистотою, тепер — повна брудна катастрофа!'::text,'яка'::text,'яка'::text,'яка'::text,'Підлога в коридорі, яка ще хвилину тому сяяла чистотою, тепер — повна брудна катастрофа!'::text),
(370374,41153,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡El suelo del pasillo, ... hace un minuto estaba impecable, ahora es un desastre total de barro!'::text,'que'::text,'que'::text,'quien'::text,'¡El suelo del pasillo, que hace un minuto estaba impecable, ahora es un desastre total de barro!'::text),
(370373,41153,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sol du couloir, ... était impeccable il y a une minute, est maintenant une catastrophe de boue totale !'::text,'qui'::text,'qui'::text,'qui'::text,'Le sol du couloir, qui était impeccable il y a une minute, est maintenant une catastrophe de boue totale !'::text),
(370376,41153,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir dakika önce tertemiz ... koridor zemini şimdi tam bir çamur felaketi!'::text,'olan'::text,'olan'::text,'olan'::text,'Bir dakika önce tertemiz olan koridor zemini şimdi tam bir çamur felaketi!'::text),
(370377,41153,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A folyosó padlója, ... egy perce még makulátlan volt, most teljes sárkatasztrófa!'::text,'amely'::text,'ami'::text,'aki'::text,'A folyosó padlója, amely egy perce még makulátlan volt, most teljes sárkatasztrófa!'::text),
(370380,41154,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bestie, sie hat gesagt, ... an seinen Stiefeln kam vom Fußballplatz.'::text,'der Schlamm'::text,'Schlamm'::text,'ein Schlamm'::text,'Bestie, sie hat gesagt, der Schlamm an seinen Stiefeln kam vom Fußballplatz.'::text),
(370384,41154,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала, що ... на його чоботях — з футбольного поля.'::text,'бруд'::text,'бруд'::text,'бруд'::text,'Подруго, вона сказала, що бруд на його чоботях — з футбольного поля.'::text),
(370383,41154,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Amiga, dijo que ... de sus botas venía del campo de fútbol.'::text,'el barro'::text,'barro'::text,'un barro'::text,'Amiga, dijo que el barro de sus botas venía del campo de fútbol.'::text),
(370382,41154,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle a dit que ... sur ses bottes venait du terrain de foot.'::text,'la boue'::text,'boue'::text,'une boue'::text,'Ma belle, elle a dit que la boue sur ses bottes venait du terrain de foot.'::text),
(370385,41154,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, dediğine göre botlarındaki ... futbol sahasından gelmiş.'::text,'çamur'::text,'çamur'::text,'bir çamur'::text,'Kanka, dediğine göre botlarındaki çamur futbol sahasından gelmiş.'::text),
(370386,41154,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, hogy ... a csizmáján a focipályáról származik.'::text,'a sár'::text,'sár'::text,'egy sár'::text,'Csajszi, azt mondta, hogy a sár a csizmáján a focipályáról származik.'::text),
(370389,41155,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er lief ... des Schlamms an seinen Stiefeln auf den sauberen Holzboden.'::text,'trotz'::text,'obwohl'::text,'wegen'::text,'Er lief trotz des Schlamms an seinen Stiefeln auf den sauberen Holzboden.'::text),
(370393,41155,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він зайшов на чисту дерев''яну підлогу ... бруд на своїх чоботях.'::text,'попри'::text,'хоча'::text,'через'::text,'Він зайшов на чисту дерев''яну підлогу попри бруд на своїх чоботях.'::text),
(370392,41155,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pisó el suelo limpio de madera ... el barro de sus botas.'::text,'a pesar de'::text,'aunque'::text,'por'::text,'Pisó el suelo limpio de madera a pesar de el barro de sus botas.'::text),
(370391,41155,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a marché sur le parquet propre ... la boue sur ses bottes.'::text,'malgré'::text,'bien que'::text,'à cause de'::text,'Il a marché sur le parquet propre malgré la boue sur ses bottes.'::text),
(370394,41155,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Botlarındaki ... temiz ahşap zemine bastı.'::text,'çamura rağmen'::text,'çamura rağmen'::text,'çamur yüzünden'::text,'Botlarındaki çamura rağmen temiz ahşap zemine bastı.'::text),
(370395,41155,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rálépett a tiszta fapadlóra a csizmáján lévő sár ...'::text,'ellenére'::text,'bár'::text,'miatt'::text,'Rálépett a tiszta fapadlóra a csizmáján lévő sár ellenére.'::text),
(370398,41156,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, bis heute Abend ... er in jedes einzelne Zimmer Schlamm, ohne Witz.'::text,'schleppt'::text,'schleppt'::text,'schleppt'::text,'Bro, bis heute Abend schleppt er in jedes einzelne Zimmer Schlamm, ohne Witz.'::text),
(370402,41156,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, до вечора він ... бруд у кожну кімнату, без жартів.'::text,'рознесе'::text,'рознесе'::text,'розносить'::text,'Бро, до вечора він рознесе бруд у кожну кімнату, без жартів.'::text),
(370401,41156,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, para esta noche ... barro a cada habitación, sin mentir.'::text,'habrá llevado'::text,'llevará'::text,'lleva'::text,'Bro, para esta noche habrá llevado barro a cada habitación, sin mentir.'::text),
(370400,41156,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, d''ici ce soir il ... de la boue dans chaque pièce, sans mentir.'::text,'aura ramené'::text,'ramènera'::text,'ramène'::text,'Frérot, d''ici ce soir il aura ramené de la boue dans chaque pièce, sans mentir.'::text),
(370403,41156,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, bu akşama kadar her odaya çamur ..., yemin ederim.'::text,'taşımış olacak'::text,'taşıyacak'::text,'taşıyor'::text,'Kanka, bu akşama kadar her odaya çamur taşımış olacak, yemin ederim.'::text),
(370404,41156,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, estére ... sarat minden egyes szobába, komolyan.'::text,'behord'::text,'be fog hordani'::text,'hord'::text,'Tesó, estére behord sarat minden egyes szobába, komolyan.'::text),
(370074,41120,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... seit drei Stunden Regale an, und die Bohrmaschine zerstört die Wand!'::text,'bringt'::text,'bringt'::text,'bringt'::text,'Sie bringt seit drei Stunden Regale an, und die Bohrmaschine zerstört die Wand!'::text),
(370078,41120,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... полиці вже три години, і дриль нищить стіну!'::text,'кріпить'::text,'кріпить'::text,'кріпить'::text,'Вона кріпить полиці вже три години, і дриль нищить стіну!'::text),
(370077,41120,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Lleva tres horas ... estantes y el taladro está destrozando la pared!'::text,'montando'::text,'montando'::text,'montando'::text,'¡Lleva tres horas montando estantes y el taladro está destrozando la pared!'::text),
(370076,41120,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... des étagères depuis trois heures, et la perceuse détruit le mur !'::text,'fixe'::text,'fixe'::text,'fixe'::text,'Elle fixe des étagères depuis trois heures, et la perceuse détruit le mur !'::text),
(370079,41120,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Üç saattir raf ... ve matkap duvarı mahvediyor!'::text,'takıyor'::text,'takıyor'::text,'takıyor'::text,'Üç saattir raf takıyor ve matkap duvarı mahvediyor!'::text),
(370080,41120,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Három órája ... a polcokat, és a fúró tönkreteszi a falat!'::text,'szereli'::text,'szereli'::text,'szereli'::text,'Három órája szereli a polcokat, és a fúró tönkreteszi a falat!'::text),
(370092,41122,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schatz, anscheinend ... sie schon zwei Regale angebracht, und die Bohrmaschine hat sie erst heute gekauft.'::text,'hat'::text,'hat'::text,'hat'::text,'Schatz, anscheinend hat sie schon zwei Regale angebracht, und die Bohrmaschine hat sie erst heute gekauft.'::text),
(370096,41122,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, вона вже ... дві полиці, а дриль купила тільки сьогодні.'::text,'закріпила'::text,'кріпила'::text,'закріпила'::text,'Подруго, кажуть, вона вже закріпила дві полиці, а дриль купила тільки сьогодні.'::text),
(370095,41122,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer ya ... dos estantes, y el taladro lo compró hoy mismo.'::text,'ha montado'::text,'ha estado montando'::text,'montó'::text,'Tía, al parecer ya ha montado dos estantes, y el taladro lo compró hoy mismo.'::text),
(370094,41122,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment elle ... déjà deux étagères, et elle n''a acheté la perceuse qu''aujourd''hui.'::text,'a fixé'::text,'fixe'::text,'a fixé'::text,'Ma belle, apparemment elle a fixé déjà deux étagères, et elle n''a acheté la perceuse qu''aujourd''hui.'::text),
(370097,41122,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre şimdiden iki raf ... ve matkabı daha bugün almış.'::text,'takmış'::text,'takıyormuş'::text,'taktı'::text,'Kızım, duyduğuma göre şimdiden iki raf takmış ve matkabı daha bugün almış.'::text),
(370098,41122,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag már két polcot ..., pedig a fúrót csak ma vette.'::text,'felszerelt'::text,'szerelt'::text,'felszerelt'::text,'Csajszi, állítólag már két polcot felszerelt, pedig a fúrót csak ma vette.'::text),
(370101,41123,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rate mal, sie hat mir erzählt, sie ... beide Regale angebracht, bevor ihre Mitbewohnerin überhaupt aufgewacht war.'::text,'hatte'::text,'hat'::text,'hat'::text,'Rate mal, sie hat mir erzählt, sie hatte beide Regale angebracht, bevor ihre Mitbewohnerin überhaupt aufgewacht war.'::text),
(370105,41123,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Уяви, вона сказала мені, що ... обидві полиці ще до того, як її сусідка по квартирі взагалі прокинулася.'::text,'закріпила'::text,'закріпила'::text,'кріпить'::text,'Уяви, вона сказала мені, що закріпила обидві полиці ще до того, як її сусідка по квартирі взагалі прокинулася.'::text),
(370104,41123,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Adivina, me dijo que ... los dos estantes antes de que su compañera de piso se despertara siquiera.'::text,'había montado'::text,'ha montado'::text,'monta'::text,'Adivina, me dijo que había montado los dos estantes antes de que su compañera de piso se despertara siquiera.'::text),
(370103,41123,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Devine quoi, elle m''a dit qu''elle ... les deux étagères avant même que sa coloc se réveille.'::text,'avait fixé'::text,'a fixé'::text,'fixe'::text,'Devine quoi, elle m''a dit qu''elle avait fixé les deux étagères avant même que sa coloc se réveille.'::text),
(370106,41123,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bil bakalım, bana ev arkadaşı daha uyanmadan iki rafı da ... söyledi.'::text,'taktığını'::text,'taktığını'::text,'taktığını'::text,'Bil bakalım, bana ev arkadaşı daha uyanmadan iki rafı da taktığını söyledi.'::text),
(370107,41123,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Képzeld, azt mondta, hogy mindkét polcot ..., mielőtt a lakótársa egyáltalán felébredt.'::text,'felszerelte'::text,'felszerelte'::text,'felszereli'::text,'Képzeld, azt mondta, hogy mindkét polcot felszerelte, mielőtt a lakótársa egyáltalán felébredt.'::text),
(370110,41124,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn sie noch ein Regal anbringt, ... die Ziegelwand komplett im Eimer, Bro.'::text,'ist'::text,'wäre'::text,'war'::text,'Wenn sie noch ein Regal anbringt, ist die Ziegelwand komplett im Eimer, Bro.'::text),
(370114,41124,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо вона закріпить ще одну полицю, тій цегляній стіні ... капець, бро.'::text,'буде'::text,'був би'::text,'був'::text,'Якщо вона закріпить ще одну полицю, тій цегляній стіні буде капець, бро.'::text),
(370113,41124,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si monta un estante más, esa pared de ladrillo ... hecha polvo, bro.'::text,'estará'::text,'estaría'::text,'estaba'::text,'Si monta un estante más, esa pared de ladrillo estará hecha polvo, bro.'::text),
(370112,41124,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si elle fixe encore une étagère, ce mur de briques ... complètement foutu, frérot.'::text,'sera'::text,'serait'::text,'était'::text,'Si elle fixe encore une étagère, ce mur de briques sera complètement foutu, frérot.'::text),
(370115,41124,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir raf daha takarsa o tuğla duvar tamamen ..., kanka.'::text,'bitecek'::text,'biterdi'::text,'bitti'::text,'Bir raf daha takarsa o tuğla duvar tamamen bitecek, kanka.'::text),
(370116,41124,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha még egy polcot felszerel, az a téglafal teljesen kész ..., tesó.'::text,'lesz'::text,'lenne'::text,'volt'::text,'Ha még egy polcot felszerel, az a téglafal teljesen kész lesz, tesó.'::text),
(370119,41125,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, ohne Witz, wenn ich ihre Skills hätte, ...'::text,'würde ich an jeder Wand Regale anbringen'::text,'werde ich an jeder Wand Regale anbringen'::text,'bringe ich an jeder Wand Regale an'::text,'Bro, ohne Witz, wenn ich ihre Skills hätte, würde ich an jeder Wand Regale anbringen.'::text),
(370123,41125,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бро, якби я мав її навички, я ... полиці на кожну стіну, без жартів.'::text,'б повісив'::text,'повішу'::text,'вішаю'::text,'Бро, якби я мав її навички, я б повісив полиці на кожну стіну, без жартів.'::text),
(370122,41125,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bro, si tuviera sus habilidades, ... estantes en todas las paredes, sin mentir.'::text,'montaría'::text,'montaré'::text,'monto'::text,'Bro, si tuviera sus habilidades, montaría estantes en todas las paredes, sin mentir.'::text),
(370121,41125,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Frérot, si j''avais ses skills, je ... des étagères sur chaque mur, sans mentir.'::text,'fixerais'::text,'fixerai'::text,'fixe'::text,'Frérot, si j''avais ses skills, je fixerais des étagères sur chaque mur, sans mentir.'::text),
(370124,41125,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kanka, onun becerileri bende olsa her duvara raf ..., yemin ederim.'::text,'takardım'::text,'takacağım'::text,'takıyorum'::text,'Kanka, onun becerileri bende olsa her duvara raf takardım, yemin ederim.'::text),
(370125,41125,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tesó, ha nekem lenne ilyen skillem, minden falra ... polcot, komolyan.'::text,'szerelnék'::text,'fogok szerelni'::text,'szerelek'::text,'Tesó, ha nekem lenne ilyen skillem, minden falra szerelnék polcot, komolyan.'::text),
(370128,41126,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Regale ... am Montag an der Ziegelwand angebracht, voll im Budget.'::text,'wurden'::text,'haben'::text,'werden'::text,'Die Regale wurden am Montag an der Ziegelwand angebracht, voll im Budget.'::text),
(370132,41126,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Полиці ... на цегляній стіні в понеділок, повністю в межах бюджету.'::text,'були закріплені'::text,'закріпили'::text,'закріплені'::text,'Полиці були закріплені на цегляній стіні в понеділок, повністю в межах бюджету.'::text),
(370131,41126,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los estantes ... en la pared de ladrillo el lunes, totalmente dentro del presupuesto.'::text,'se montaron'::text,'montaron'::text,'se montan'::text,'Los estantes se montaron en la pared de ladrillo el lunes, totalmente dentro del presupuesto.'::text),
(370130,41126,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les étagères ... sur le mur de briques lundi, dans le respect total du budget.'::text,'ont été fixées'::text,'ont fixé'::text,'sont fixées'::text,'Les étagères ont été fixées sur le mur de briques lundi, dans le respect total du budget.'::text),
(370133,41126,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Raflar pazartesi tuğla duvara ..., tamamen bütçe dahilinde.'::text,'takıldı'::text,'taktı'::text,'takılıyor'::text,'Raflar pazartesi tuğla duvara takıldı, tamamen bütçe dahilinde.'::text),
(370134,41126,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A polcokat hétfőn ... a téglafalra, teljesen a költségvetésen belül.'::text,'szerelték fel'::text,'felszerelte'::text,'szerelik fel'::text,'A polcokat hétfőn szerelték fel a téglafalra, teljesen a költségvetésen belül.'::text),
(370137,41127,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... die Regale selbst, weil sonst niemand die Bohrmaschine hielt.'::text,'montierte'::text,'wurde montiert'::text,'montierend'::text,'Sie montierte die Regale selbst, weil sonst niemand die Bohrmaschine hielt.'::text),
(370141,41127,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... полиці сама, бо ніхто інший не тримав дриль.'::text,'закріпила'::text,'була закріплена'::text,'закріплюючи'::text,'Вона закріпила полиці сама, бо ніхто інший не тримав дриль.'::text),
(370140,41127,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... los estantes ella misma, porque nadie más sujetaba el taladro.'::text,'Montó'::text,'Fue montada'::text,'Montando'::text,'Montó los estantes ella misma, porque nadie más sujetaba el taladro.'::text),
(370139,41127,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... les étagères elle-même, parce que personne d''autre ne tenait la perceuse.'::text,'a fixé'::text,'a été fixée'::text,'fixant'::text,'Elle a fixé les étagères elle-même, parce que personne d''autre ne tenait la perceuse.'::text),
(370142,41127,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rafları kendisi ..., çünkü matkabı başka kimse tutmuyordu.'::text,'taktı'::text,'takıldı'::text,'takarak'::text,'Rafları kendisi taktı, çünkü matkabı başka kimse tutmuyordu.'::text),
(370143,41127,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A polcokat maga ..., mert senki más nem fogta a fúrót.'::text,'szerelte fel'::text,'fel lett szerelve'::text,'felszerelve'::text,'A polcokat maga szerelte fel, mert senki más nem fogta a fúrót.'::text),
(370146,41128,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Regal trägt einen schweren Bücherstapel, also ... es sehr fest angebracht sein.'::text,'muss'::text,'kann nicht'::text,'könnte nicht'::text,'Das Regal trägt einen schweren Bücherstapel, also muss es sehr fest angebracht sein.'::text),
(370150,41128,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Полиця тримає важку стопку книжок, тож вона ... дуже міцно закріплена.'::text,'напевно'::text,'не може бути'::text,'можливо, не'::text,'Полиця тримає важку стопку книжок, тож вона напевно дуже міцно закріплена.'::text),
(370149,41128,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El estante aguanta una pila pesada de libros, así que ... estar montado muy firme.'::text,'debe de'::text,'no puede'::text,'puede que no'::text,'El estante aguanta una pila pesada de libros, así que debe de estar montado muy firme.'::text),
(370148,41128,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''étagère porte une lourde pile de livres, donc elle ... être fixée très solidement.'::text,'doit'::text,'ne peut pas'::text,'pourrait ne pas'::text,'L''étagère porte une lourde pile de livres, donc elle doit être fixée très solidement.'::text),
(370151,41128,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Raf ağır bir kitap yığını taşıyor, yani çok sağlam ...'::text,'takılmış olmalı'::text,'takılmış olamaz'::text,'takılmamış olabilir'::text,'Raf ağır bir kitap yığını taşıyor, yani çok sağlam takılmış olmalı.'::text),
(370152,41128,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A polc egy nehéz könyvkupacot tart, szóval ... nagyon stabilan van felszerelve.'::text,'biztosan'::text,'nem lehet, hogy'::text,'lehet, hogy nem'::text,'A polc egy nehéz könyvkupacot tart, szóval biztosan nagyon stabilan van felszerelve.'::text),
(370155,41129,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Halterungen, ... sie an der Wand angebracht hat, tragen zwei Kiefernregale.'::text,'die'::text,'wer'::text,'wo'::text,'Die Halterungen, die sie an der Wand angebracht hat, tragen zwei Kiefernregale.'::text),
(370159,41129,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Кронштейни, ... вона закріпила на стіні, тримають дві соснові полиці.'::text,'які'::text,'хто'::text,'де'::text,'Кронштейни, які вона закріпила на стіні, тримають дві соснові полиці.'::text),
(370158,41129,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Los soportes ... montó en la pared sostienen dos estantes de pino.'::text,'que'::text,'quien'::text,'donde'::text,'Los soportes que montó en la pared sostienen dos estantes de pino.'::text),
(370157,41129,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les supports ... a fixés au mur portent deux étagères en pin.'::text,'qu''elle'::text,'qui'::text,'où elle'::text,'Les supports qu''elle a fixés au mur portent deux étagères en pin.'::text),
(370160,41129,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Duvara ... raf destekleri iki çam rafı taşıyor.'::text,'taktığı'::text,'taktığı'::text,'taktığı'::text,'Duvara taktığı raf destekleri iki çam rafı taşıyor.'::text),
(370161,41129,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A konzolok, ... a falra szerelt, két fenyőpolcot tartanak.'::text,'amelyeket'::text,'akiket'::text,'ahol'::text,'A konzolok, amelyeket a falra szerelt, két fenyőpolcot tartanak.'::text),
(370164,41130,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie sagte, sie ... die Regale am nächsten Tag anbringen, aber sie war schon an dem Nachmittag fertig.'::text,'würde'::text,'werde'::text,'wird'::text,'Sie sagte, sie würde die Regale am nächsten Tag anbringen, aber sie war schon an dem Nachmittag fertig.'::text),
(370168,41130,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона сказала, що ... полиці наступного дня, але закінчила їх того ж дня по обіді.'::text,'закріпить'::text,'закріпить'::text,'закріплює'::text,'Вона сказала, що закріпить полиці наступного дня, але закінчила їх того ж дня по обіді.'::text),
(370167,41130,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que ... los estantes al día siguiente, pero los terminó esa misma tarde.'::text,'montaría'::text,'montará'::text,'monta'::text,'Dijo que montaría los estantes al día siguiente, pero los terminó esa misma tarde.'::text),
(370166,41130,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle a dit qu''elle ... les étagères le lendemain, mais elle les a finies l''après-midi même.'::text,'fixerait'::text,'fixera'::text,'fixe'::text,'Elle a dit qu''elle fixerait les étagères le lendemain, mais elle les a finies l''après-midi même.'::text),
(370169,41130,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Rafları ertesi gün ... söyledi ama o öğleden sonra bitirdi.'::text,'takacağını'::text,'takacağını'::text,'taktığını'::text,'Rafları ertesi gün takacağını söyledi ama o öğleden sonra bitirdi.'::text),
(370170,41130,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy a polcokat másnap ..., de még aznap délután befejezte.'::text,'szereli fel'::text,'fel fogja szerelni'::text,'felszereli'::text,'Azt mondta, hogy a polcokat másnap szereli fel, de még aznap délután befejezte.'::text),
(352029,39115,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... Herbstblätter unter dem Ahorn, als ich vorbeiging. Ikonisch.'::text,'fingst gerade'::text,'fingst'::text,'fingst'::text,'Du fingst gerade Herbstblätter unter dem Ahorn, als ich vorbeiging. Ikonisch.'::text),
(352033,39115,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... осіннє листя під тим кленом, коли я проходила повз. Легендарно.'::text,'ловив'::text,'спіймав'::text,'спіймав'::text,'Ти ловив осіннє листя під тим кленом, коли я проходила повз. Легендарно.'::text),
(352032,39115,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... hojas de otoño bajo ese arce cuando pasé. Icónico.'::text,'Estabas atrapando'::text,'Atrapaste'::text,'Has atrapado'::text,'Estabas atrapando hojas de otoño bajo ese arce cuando pasé. Icónico.'::text),
(352031,39115,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... des feuilles d''automne sous cet érable quand je suis passée. Iconique.'::text,'attrapais'::text,'as attrapé'::text,'as attrapé'::text,'Tu attrapais des feuilles d''automne sous cet érable quand je suis passée. Iconique.'::text),
(352034,39115,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ben yanından geçerken ... o akçaağacın altında sonbahar yapraklarını. İkonik.'::text,'yakalıyordun'::text,'yakaladın'::text,'yakalamışsın'::text,'Ben yanından geçerken yakalıyordun o akçaağacın altında sonbahar yapraklarını. İkonik.'::text),
(352035,39115,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp őszi leveleket ... annál a juharfánál, amikor elmentem melletted. Ikonikus.'::text,'kapkodtál'::text,'elkaptál'::text,'elkaptál'::text,'Épp őszi leveleket kapkodtál annál a juharfánál, amikor elmentem melletted. Ikonikus.'::text),
(352038,39116,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, du ... jetzt seit zehn Minuten Herbstblätter und lachst immer noch.'::text,'fängst'::text,'fängst'::text,'fängst'::text,'Ehrlich gesagt, du fängst jetzt seit zehn Minuten Herbstblätter und lachst immer noch.'::text),
(352042,39116,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, ти вже десять хвилин ... осіннє листя і досі смієшся.'::text,'ловиш'::text,'ловиш'::text,'ловиш'::text,'Не буду брехати, ти вже десять хвилин ловиш осіннє листя і досі смієшся.'::text),
(352041,39116,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, llevas diez minutos ... hojas de otoño y sigues riéndote.'::text,'atrapando'::text,'atrapando'::text,'atrapando'::text,'No te voy a mentir, llevas diez minutos atrapando hojas de otoño y sigues riéndote.'::text),
(352040,39116,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, tu ... des feuilles d''automne depuis dix minutes et tu rigoles encore.'::text,'attrapes'::text,'attrapes'::text,'attrapes'::text,'Je vais pas mentir, tu attrapes des feuilles d''automne depuis dix minutes et tu rigoles encore.'::text),
(352043,39116,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, on dakikadır sonbahar yaprakları ... ve hâlâ gülüyorsun.'::text,'yakalıyorsun'::text,'yakalıyorsun'::text,'yakalıyorsun'::text,'Yalan yok, on dakikadır sonbahar yaprakları yakalıyorsun ve hâlâ gülüyorsun.'::text),
(352044,39116,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, már tíz perce ... az őszi leveleket, és még mindig nevetsz.'::text,'kapkodod'::text,'kapkodod'::text,'kapkodod'::text,'Nem fogok hazudni, már tíz perce kapkodod az őszi leveleket, és még mindig nevetsz.'::text),
(352047,39117,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er schaute nach oben, als die Herbstblätter ..., auf ihn zu fallen. Was für eine Überraschung.'::text,'anfingen'::text,'gerade anfingen'::text,'angefangen haben'::text,'Er schaute nach oben, als die Herbstblätter anfingen, auf ihn zu fallen. Was für eine Überraschung.'::text),
(352051,39117,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він дивився вгору, коли на нього ... падати осіннє листя. Оце так несподіванка.'::text,'почало'::text,'починало'::text,'почало'::text,'Він дивився вгору, коли на нього почало падати осіннє листя. Оце так несподіванка.'::text),
(352050,39117,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Estaba mirando hacia arriba cuando las hojas de otoño ... a caerle encima. Qué sorpresa.'::text,'empezaron'::text,'estaban empezando'::text,'han empezado'::text,'Estaba mirando hacia arriba cuando las hojas de otoño empezaron a caerle encima. Qué sorpresa.'::text),
(352049,39117,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il regardait en l''air quand les feuilles d''automne ... à lui tomber dessus. Quelle surprise.'::text,'ont commencé'::text,'commençaient'::text,'ont commencé'::text,'Il regardait en l''air quand les feuilles d''automne ont commencé à lui tomber dessus. Quelle surprise.'::text),
(352052,39117,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sonbahar yaprakları üzerine düşmeye ... yukarı bakıyordu. Ne sürpriz.'::text,'başladığında'::text,'başlarken'::text,'başlamışken'::text,'Sonbahar yaprakları üzerine düşmeye başladığında yukarı bakıyordu. Ne sürpriz.'::text),
(352053,39117,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp felfelé nézett, amikor az őszi levelek ... hullani rá. Micsoda meglepetés.'::text,'elkezdtek'::text,'kezdtek'::text,'elkezdtek'::text,'Épp felfelé nézett, amikor az őszi levelek elkezdtek hullani rá. Micsoda meglepetés.'::text),
(352056,39118,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... diesen Herbst bisher drei Ahornblätter gefangen.'::text,'hat'::text,'hat'::text,'hat'::text,'Er hat diesen Herbst bisher drei Ahornblätter gefangen.'::text),
(352060,39118,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Цієї осені він уже ... три кленові листки.'::text,'спіймав'::text,'ловив'::text,'ловить'::text,'Цієї осені він уже спіймав три кленові листки.'::text),
(352059,39118,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este otoño ya ... tres hojas de arce.'::text,'ha atrapado'::text,'ha estado atrapando'::text,'atrapa'::text,'Este otoño ya ha atrapado tres hojas de arce.'::text),
(352058,39118,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cet automne, il ... déjà trois feuilles d''érable.'::text,'a attrapé'::text,'a attrapé'::text,'attrape'::text,'Cet automne, il a attrapé déjà trois feuilles d''érable.'::text),
(352061,39118,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sonbahar şimdiye kadar üç akçaağaç yaprağı ...'::text,'yakaladı'::text,'yakalıyor'::text,'yakalar'::text,'Bu sonbahar şimdiye kadar üç akçaağaç yaprağı yakaladı.'::text),
(352062,39118,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ezen az őszön eddig három juharlevelet ... el.'::text,'kapott'::text,'kapott'::text,'kap'::text,'Ezen az őszön eddig három juharlevelet kapott el.'::text),
(352065,39119,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Als er nach oben schaute, ... der Herbst den Ahorn schon leuchtend gelb gefärbt.'::text,'hatte'::text,'hat'::text,'hat'::text,'Als er nach oben schaute, hatte der Herbst den Ahorn schon leuchtend gelb gefärbt.'::text),
(352069,39119,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Коли він подивився вгору, осінь уже ... клен у яскраво-жовтий.'::text,'пофарбувала'::text,'пофарбувала'::text,'фарбує'::text,'Коли він подивився вгору, осінь уже пофарбувала клен у яскраво-жовтий.'::text),
(352068,39119,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cuando miró hacia arriba, el otoño ya ... el arce de amarillo intenso.'::text,'había teñido'::text,'ha teñido'::text,'tiñe'::text,'Cuando miró hacia arriba, el otoño ya había teñido el arce de amarillo intenso.'::text),
(352067,39119,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Quand il a levé les yeux, l''automne ... l''érable en jaune vif.'::text,'avait teint'::text,'a teint'::text,'teint'::text,'Quand il a levé les yeux, l''automne avait teint l''érable en jaune vif.'::text),
(352070,39119,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O başını kaldırdığında sonbahar akçaağacı parlak sarıya ...'::text,'boyamıştı'::text,'boyadı'::text,'boyuyor'::text,'O başını kaldırdığında sonbahar akçaağacı parlak sarıya boyamıştı.'::text),
(352071,39119,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Mire felnézett, az ősz élénksárgára ... a juharfát.'::text,'festette'::text,'festette'::text,'festi'::text,'Mire felnézett, az ősz élénksárgára festette a juharfát.'::text),
(352074,39120,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn der Wind diesen Herbst stärker wird, ... mehr Blätter auf ihn herunter.'::text,'fallen'::text,'fielen'::text,'fielen'::text,'Wenn der Wind diesen Herbst stärker wird, fallen mehr Blätter auf ihn herunter.'::text),
(352078,39120,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо цієї осені вітер посилиться, на нього ... більше листя.'::text,'впаде'::text,'впало б'::text,'впало'::text,'Якщо цієї осені вітер посилиться, на нього впаде більше листя.'::text),
(352077,39120,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el viento se hace más fuerte este otoño, le ... más hojas encima.'::text,'caerán'::text,'caerían'::text,'cayeron'::text,'Si el viento se hace más fuerte este otoño, le caerán más hojas encima.'::text),
(352076,39120,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le vent se renforce cet automne, plus de feuilles lui ... dessus.'::text,'tomberont'::text,'tomberaient'::text,'sont tombées'::text,'Si le vent se renforce cet automne, plus de feuilles lui tomberont dessus.'::text),
(352079,39120,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu sonbahar rüzgâr güçlenirse üstüne daha çok yaprak ...'::text,'düşecek'::text,'düşerdi'::text,'düştü'::text,'Bu sonbahar rüzgâr güçlenirse üstüne daha çok yaprak düşecek.'::text),
(352080,39120,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha ezen az őszön erősebb lesz a szél, több levél ... rá.'::text,'fog hullani'::text,'hullana'::text,'hullott'::text,'Ha ezen az őszön erősebb lesz a szél, több levél fog hullani rá.'::text),
(352092,39122,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Budget für die Herbstreinigung dieses Parks ... im letzten Quartal genehmigt.'::text,'wurde'::text,'hat'::text,'wird'::text,'Das Budget für die Herbstreinigung dieses Parks wurde im letzten Quartal genehmigt.'::text),
(352096,39122,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Бюджет на осіннє прибирання цього парку ... минулого кварталу.'::text,'був затверджений'::text,'затвердив'::text,'затверджує'::text,'Бюджет на осіннє прибирання цього парку був затверджений минулого кварталу.'::text),
(352095,39122,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El presupuesto de limpieza de otoño de este parque ... el trimestre pasado.'::text,'se aprobó'::text,'aprobó'::text,'está aprobando'::text,'El presupuesto de limpieza de otoño de este parque se aprobó el trimestre pasado.'::text),
(352094,39122,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le budget du nettoyage d''automne de ce parc ... le trimestre dernier.'::text,'a été approuvé'::text,'a approuvé'::text,'approuve'::text,'Le budget du nettoyage d''automne de ce parc a été approuvé le trimestre dernier.'::text),
(352097,39122,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu parkın sonbahar temizlik bütçesi geçen çeyrekte ...'::text,'onaylandı'::text,'onayladı'::text,'onaylıyor'::text,'Bu parkın sonbahar temizlik bütçesi geçen çeyrekte onaylandı.'::text),
(352098,39122,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A park őszi takarítási költségvetését a múlt negyedévben ...'::text,'hagyták jóvá'::text,'jóváhagyta'::text,'jóváhagyja'::text,'A park őszi takarítási költségvetését a múlt negyedévben hagyták jóvá.'::text),
(352101,39123,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Blätter ... im Herbst von den Bäumen, weil im Herbst die Blätter fallen.'::text,'fallen'::text,'sind gefallen'::text,'fallend'::text,'Die Blätter fallen im Herbst von den Bäumen, weil im Herbst die Blätter fallen.'::text),
(352105,39123,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Листя ... з дерев восени, бо осінь — це коли листя падає.'::text,'падає'::text,'опале'::text,'падаючи'::text,'Листя падає з дерев восени, бо осінь — це коли листя падає.'::text),
(352104,39123,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las hojas ... de los árboles en otoño, porque el otoño es cuando caen las hojas.'::text,'caen'::text,'son caídas'::text,'cayendo'::text,'Las hojas caen de los árboles en otoño, porque el otoño es cuando caen las hojas.'::text),
(352103,39123,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les feuilles ... des arbres en automne, parce que l''automne, c''est quand les feuilles tombent.'::text,'tombent'::text,'sont tombées'::text,'tombant'::text,'Les feuilles tombent des arbres en automne, parce que l''automne, c''est quand les feuilles tombent.'::text),
(352106,39123,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yapraklar sonbaharda ağaçlardan ..., çünkü sonbahar yaprakların düştüğü zamandır.'::text,'düşer'::text,'düşmüştür'::text,'düşerek'::text,'Yapraklar sonbaharda ağaçlardan düşer, çünkü sonbahar yaprakların düştüğü zamandır.'::text),
(352107,39123,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A levelek ősszel ... a fákról, mert az ősz az, amikor a levelek lehullanak.'::text,'lehullanak'::text,'le vannak hullva'::text,'hullva'::text,'A levelek ősszel lehullanak a fákról, mert az ősz az, amikor a levelek lehullanak.'::text),
(352110,39124,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die leuchtend gelben Blätter deuten darauf hin, dass der Herbst schon weit fortgeschritten sein ...'::text,'muss'::text,'könnte'::text,'kann nicht'::text,'Die leuchtend gelben Blätter deuten darauf hin, dass der Herbst schon weit fortgeschritten sein muss.'::text),
(352114,39124,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Яскраво-жовте листя вказує на те, що осінь ... в самому розпалі.'::text,'напевно'::text,'можливо'::text,'ніяк не може бути'::text,'Яскраво-жовте листя вказує на те, що осінь напевно в самому розпалі.'::text),
(352113,39124,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Las hojas amarillo intenso indican que el otoño ... estar ya bien avanzado.'::text,'debe de'::text,'podría'::text,'no puede'::text,'Las hojas amarillo intenso indican que el otoño debe de estar ya bien avanzado.'::text),
(352112,39124,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Les feuilles jaune vif indiquent que l''automne ... être déjà bien avancé.'::text,'doit'::text,'pourrait'::text,'ne peut pas'::text,'Les feuilles jaune vif indiquent que l''automne doit être déjà bien avancé.'::text),
(352115,39124,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Parlak sarı yapraklar sonbaharın epey ilerlemiş ... gösteriyor.'::text,'olması gerektiğini'::text,'olabileceğini'::text,'olamayacağını'::text,'Parlak sarı yapraklar sonbaharın epey ilerlemiş olması gerektiğini gösteriyor.'::text),
(352116,39124,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az élénksárga levelek arra utalnak, hogy az ősz ... már javában tart.'::text,'biztosan'::text,'talán'::text,'nem lehet, hogy'::text,'Az élénksárga levelek arra utalnak, hogy az ősz biztosan már javában tart.'::text),
(394086,43788,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schatz, anscheinend ... das Flugzeug sie schon mit zehn Kisten versorgt.'::text,'hat'::text,'hat'::text,'hat'::text,'Schatz, anscheinend hat das Flugzeug sie schon mit zehn Kisten versorgt.'::text),
(394090,43788,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, кажуть, літак уже ... їх десятьма ящиками.'::text,'забезпечив'::text,'забезпечував'::text,'забезпечує'::text,'Подруго, кажуть, літак уже забезпечив їх десятьма ящиками.'::text),
(394089,43788,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, al parecer el avión ya los ... con diez cajas.'::text,'ha abastecido'::text,'ha estado abasteciendo'::text,'está abasteciendo'::text,'Tía, al parecer el avión ya los ha abastecido con diez cajas.'::text),
(394088,43788,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, apparemment l''avion les ... déjà de dix caisses.'::text,'a approvisionnés'::text,'approvisionne'::text,'approvisionne'::text,'Ma belle, apparemment l''avion les a approvisionnés déjà de dix caisses.'::text),
(394091,43788,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, duyduğuma göre uçak onlara şimdiden on sandık ...'::text,'ulaştırmış'::text,'ulaştırıyormuş'::text,'ulaştırıyor'::text,'Kızım, duyduğuma göre uçak onlara şimdiden on sandık ulaştırmış.'::text),
(394092,43788,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, állítólag a gép már tíz ládával ... őket.'::text,'látta el'::text,'látta el'::text,'látja el'::text,'Csajszi, állítólag a gép már tíz ládával látta el őket.'::text),
(394095,43789,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hör zu, sie hat mir erzählt, das Flugzeug ... das Dorf noch vor dem Sturm versorgt.'::text,'hatte'::text,'hat'::text,'hat'::text,'Hör zu, sie hat mir erzählt, das Flugzeug hatte das Dorf noch vor dem Sturm versorgt.'::text),
(394099,43789,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Слухай, вона сказала мені, що літак ... село ще до того, як прийшла буря.'::text,'забезпечив'::text,'забезпечив'::text,'забезпечує'::text,'Слухай, вона сказала мені, що літак забезпечив село ще до того, як прийшла буря.'::text),
(394098,43789,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Escucha, me dijo que el avión ... el pueblo antes de que llegara la tormenta.'::text,'había abastecido'::text,'ha abastecido'::text,'abastece'::text,'Escucha, me dijo que el avión había abastecido el pueblo antes de que llegara la tormenta.'::text),
(394097,43789,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Écoute, elle m''a dit que l''avion ... le village avant l''arrivée de la tempête.'::text,'avait approvisionné'::text,'a approvisionné'::text,'approvisionne'::text,'Écoute, elle m''a dit que l''avion avait approvisionné le village avant l''arrivée de la tempête.'::text),
(394100,43789,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dinle, bana dediğine göre uçak fırtına gelmeden önce köye malzeme ...'::text,'ulaştırmıştı'::text,'ulaştırmış'::text,'ulaştırıyor'::text,'Dinle, bana dediğine göre uçak fırtına gelmeden önce köye malzeme ulaştırmıştı.'::text),
(394101,43789,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Figyelj, azt mondta, hogy a gép még a vihar előtt ... a falut.'::text,'ellátta'::text,'ellátta'::text,'ellátja'::text,'Figyelj, azt mondta, hogy a gép még a vihar előtt ellátta a falut.'::text),
(394113,43791,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Pilot verspricht, dass er das Dorf nächste Woche wieder mit Essen ...'::text,'versorgen wird'::text,'versorgen wird'::text,'versorgt'::text,'Der Pilot verspricht, dass er das Dorf nächste Woche wieder mit Essen versorgen wird.'::text),
(394117,43791,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Пілот обіцяє, що наступного тижня знову ... село їжею.'::text,'забезпечить'::text,'забезпечуватиме'::text,'забезпечує'::text,'Пілот обіцяє, що наступного тижня знову забезпечить село їжею.'::text),
(394116,43791,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El piloto promete que la semana que viene ... el pueblo de comida otra vez.'::text,'abastecerá'::text,'estará abasteciendo'::text,'está abasteciendo'::text,'El piloto promete que la semana que viene abastecerá el pueblo de comida otra vez.'::text),
(394115,43791,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le pilote promet qu''il ... à nouveau le village en nourriture la semaine prochaine.'::text,'approvisionnera'::text,'sera en train d''approvisionner'::text,'approvisionne'::text,'Le pilote promet qu''il approvisionnera à nouveau le village en nourriture la semaine prochaine.'::text),
(394118,43791,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Pilot gelecek hafta köye yine yiyecek ... söz veriyor.'::text,'getireceğine'::text,'getiriyor olacağına'::text,'getirdiğine'::text,'Pilot gelecek hafta köye yine yiyecek getireceğine söz veriyor.'::text),
(394119,43791,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A pilóta megígéri, hogy jövő héten újra ... a falut élelemmel.'::text,'ellátja'::text,'el fogja látni'::text,'látja el'::text,'A pilóta megígéri, hogy jövő héten újra ellátja a falut élelemmel.'::text),
(394122,43792,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn ein Dorf keine Straße hat, ... Flugzeuge es aus der Luft.'::text,'versorgen'::text,'versorgten'::text,'versorgen'::text,'Wenn ein Dorf keine Straße hat, versorgen Flugzeuge es aus der Luft.'::text),
(394126,43792,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо в село немає дороги, літаки ... його з повітря.'::text,'постачають'::text,'постачали'::text,'постачатимуть'::text,'Якщо в село немає дороги, літаки постачають його з повітря.'::text),
(394125,43792,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un pueblo no tiene carretera, los aviones lo ... por aire.'::text,'abastecen'::text,'abastecieron'::text,'abastecerán'::text,'Si un pueblo no tiene carretera, los aviones lo abastecen por aire.'::text),
(394124,43792,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si un village n''a pas de route, les avions ... par les airs.'::text,'l''approvisionnent'::text,'l''ont approvisionné'::text,'l''approvisionneront'::text,'Si un village n''a pas de route, les avions l''approvisionnent par les airs.'::text),
(394127,43792,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir köyün yolu yoksa uçaklar onu havadan ...'::text,'ikmal eder'::text,'ikmal etti'::text,'ikmal edecek'::text,'Bir köyün yolu yoksa uçaklar onu havadan ikmal eder.'::text),
(394128,43792,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha egy falunak nincs útja, a repülők légi úton ...'::text,'látják el'::text,'látták el'::text,'el fogják látni'::text,'Ha egy falunak nincs útja, a repülők légi úton látják el.'::text),
(394131,43793,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Budget es erlaubt, ... das Flugzeug das Dorf mit 20 weiteren Kisten.'::text,'versorgt'::text,'versorgte'::text,'versorgte'::text,'Wenn das Budget es erlaubt, versorgt das Flugzeug das Dorf mit 20 weiteren Kisten.'::text),
(394135,43793,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якщо бюджет дозволить, літак ... село ще 20 ящиками.'::text,'забезпечить'::text,'забезпечив би'::text,'забезпечив'::text,'Якщо бюджет дозволить, літак забезпечить село ще 20 ящиками.'::text),
(394134,43793,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el presupuesto lo permite, el avión ... el pueblo con 20 cajas más.'::text,'abastecerá'::text,'abastecería'::text,'abasteció'::text,'Si el presupuesto lo permite, el avión abastecerá el pueblo con 20 cajas más.'::text),
(394133,43793,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si le budget le permet, l''avion ... le village de 20 caisses supplémentaires.'::text,'approvisionnera'::text,'approvisionnerait'::text,'a approvisionné'::text,'Si le budget le permet, l''avion approvisionnera le village de 20 caisses supplémentaires.'::text),
(394136,43793,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bütçe izin verirse uçak köye 20 sandık daha ...'::text,'ulaştıracak'::text,'ulaştırırdı'::text,'ulaştırdı'::text,'Bütçe izin verirse uçak köye 20 sandık daha ulaştıracak.'::text),
(394137,43793,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a költségvetés engedi, a gép további 20 ládával ... a falut.'::text,'látja el'::text,'látná el'::text,'látta el'::text,'Ha a költségvetés engedi, a gép további 20 ládával látja el a falut.'::text),
(394140,43794,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Wenn das Flugzeug keine Kisten hätte, ... es nichts, weil es nichts hätte.'::text,'lieferte'::text,'liefert'::text,'lieferte'::text,'Wenn das Flugzeug keine Kisten hätte, lieferte es nichts, weil es nichts hätte.'::text),
(394144,43794,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Якби літак не мав ящиків, він ... нічого, бо в нього нічого б не було.'::text,'не доставив би'::text,'не доставить'::text,'не доставив'::text,'Якби літак не мав ящиків, він не доставив би нічого, бо в нього нічого б не було.'::text),
(394143,43794,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si el avión no tuviera cajas, no ... nada, porque no tendría nada.'::text,'entregaría'::text,'entregará'::text,'entregó'::text,'Si el avión no tuviera cajas, no entregaría nada, porque no tendría nada.'::text),
(394142,43794,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Si l''avion n''avait pas de caisses, il ... rien, parce qu''il n''aurait rien.'::text,'ne livrerait'::text,'ne livrera'::text,'n''a livré'::text,'Si l''avion n''avait pas de caisses, il ne livrerait rien, parce qu''il n''aurait rien.'::text),
(394145,43794,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Uçağın sandığı olmasaydı hiçbir şey ..., çünkü hiçbir şeyi olmazdı.'::text,'getirmezdi'::text,'getirmeyecek'::text,'getirmedi'::text,'Uçağın sandığı olmasaydı hiçbir şey getirmezdi, çünkü hiçbir şeyi olmazdı.'::text),
(394146,43794,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ha a gépnek nem lennének ládái, semmit ..., mert semmije sem lenne.'::text,'nem szállítana'::text,'nem fog szállítani'::text,'nem szállított'::text,'Ha a gépnek nem lennének ládái, semmit nem szállítana, mert semmije sem lenne.'::text),
(394149,43795,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gestern ... das Dorf aus der Luft versorgt, eine Methode, die typischerweise dort eingesetzt wird, wo es keine Straßen gibt.'::text,'wurde'::text,'wird'::text,'hat'::text,'Gestern wurde das Dorf aus der Luft versorgt, eine Methode, die typischerweise dort eingesetzt wird, wo es keine Straßen gibt.'::text),
(394153,43795,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Учора село ... з повітря — цей метод зазвичай застосовують там, де немає доріг.'::text,'було забезпечене'::text,'забезпечується'::text,'забезпечило'::text,'Учора село було забезпечене з повітря — цей метод зазвичай застосовують там, де немає доріг.'::text),
(394152,43795,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ayer el pueblo ... por aire, un método que suele usarse donde no hay carreteras.'::text,'fue abastecido'::text,'es abastecido'::text,'abasteció'::text,'Ayer el pueblo fue abastecido por aire, un método que suele usarse donde no hay carreteras.'::text),
(394151,43795,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Hier, le village ... par les airs, une méthode généralement utilisée là où il n''y a pas de routes.'::text,'a été approvisionné'::text,'est approvisionné'::text,'a approvisionné'::text,'Hier, le village a été approvisionné par les airs, une méthode généralement utilisée là où il n''y a pas de routes.'::text),
(394154,43795,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dün köye havadan ..., bu yöntem genellikle yol olmayan yerlerde kullanılır.'::text,'ikmal yapıldı'::text,'ikmal yapılıyor'::text,'ikmal yaptı'::text,'Dün köye havadan ikmal yapıldı, bu yöntem genellikle yol olmayan yerlerde kullanılır.'::text),
(394155,43795,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tegnap a falut légi úton ..., ezt a módszert jellemzően ott alkalmazzák, ahol nincsenek utak.'::text,'látták el'::text,'látják el'::text,'ellátta'::text,'Tegnap a falut légi úton látták el, ezt a módszert jellemzően ott alkalmazzák, ahol nincsenek utak.'::text),
(394158,43796,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dieses Flugzeug ... das ganze Dorf mit Essen. Es hat buchstäblich alle gerettet!'::text,'versorgte'::text,'wurde versorgt'::text,'versorgend'::text,'Dieses Flugzeug versorgte das ganze Dorf mit Essen. Es hat buchstäblich alle gerettet!'::text),
(394162,43796,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Той літак ... усе село їжею. Він буквально всіх врятував!'::text,'забезпечив'::text,'був забезпечений'::text,'забезпечуючи'::text,'Той літак забезпечив усе село їжею. Він буквально всіх врятував!'::text),
(394161,43796,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ese avión ... a todo el pueblo de comida. ¡Literalmente salvó a todos!'::text,'abasteció'::text,'fue abastecido'::text,'abasteciendo'::text,'Ese avión abasteció a todo el pueblo de comida. ¡Literalmente salvó a todos!'::text),
(394160,43796,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Cet avion ... tout le village en nourriture. Il a littéralement sauvé tout le monde !'::text,'a approvisionné'::text,'a été approvisionné'::text,'approvisionnant'::text,'Cet avion a approvisionné tout le village en nourriture. Il a littéralement sauvé tout le monde !'::text),
(394163,43796,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'O uçak bütün köye yiyecek ... — resmen herkesi kurtardı!'::text,'ulaştırdı'::text,'ulaştırıldı'::text,'ulaştırarak'::text,'O uçak bütün köye yiyecek ulaştırdı — resmen herkesi kurtardı!'::text),
(394164,43796,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az a gép ... az egész falut élelemmel. Szó szerint mindenkit megmentett!'::text,'látta el'::text,'el lett látva'::text,'ellátva'::text,'Az a gép látta el az egész falut élelemmel. Szó szerint mindenkit megmentett!'::text),
(394167,43797,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Noch mehr Kisten fallen! Das Flugzeug ... die ganze Region versorgen. Absolut riesig!'::text,'muss'::text,'kann nicht'::text,'darf nicht'::text,'Noch mehr Kisten fallen! Das Flugzeug muss die ganze Region versorgen. Absolut riesig!'::text),
(394171,43797,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Падають ще ящики! Літак ... постачає весь регіон. Це просто грандіозно!'::text,'напевно'::text,'точно не'::text,'не мусить'::text,'Падають ще ящики! Літак напевно постачає весь регіон. Це просто грандіозно!'::text),
(394170,43797,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Caen más cajas! El avión ... estar abasteciendo a toda la región. ¡Algo enorme!'::text,'debe de'::text,'no puede'::text,'no debe'::text,'¡Caen más cajas! El avión debe de estar abasteciendo a toda la región. ¡Algo enorme!'::text),
(394169,43797,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''autres caisses tombent ! L''avion ... approvisionner toute la région. Absolument énorme !'::text,'doit'::text,'ne peut pas'::text,'ne doit pas'::text,'D''autres caisses tombent ! L''avion doit approvisionner toute la région. Absolument énorme !'::text),
(394172,43797,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Daha fazla sandık düşüyor! Uçak bütün bölgeye ikmal ... — tamamen devasa!'::text,'yapıyor olmalı'::text,'yapıyor olamaz'::text,'yapmamalı'::text,'Daha fazla sandık düşüyor! Uçak bütün bölgeye ikmal yapıyor olmalı — tamamen devasa!'::text),
(394173,43797,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Még több láda hullik! A gép ... az egész régiót látja el. Elképesztően nagy dolog!'::text,'biztosan'::text,'nem lehet, hogy'::text,'nem szabad, hogy'::text,'Még több láda hullik! A gép biztosan az egész régiót látja el. Elképesztően nagy dolog!'::text),
(394176,43798,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Flugzeug, ... dieses Dorf versorgt, ist ihre einzige Hoffnung. Ohne es: Katastrophe!'::text,'das'::text,'der'::text,'dessen'::text,'Das Flugzeug, das dieses Dorf versorgt, ist ihre einzige Hoffnung. Ohne es: Katastrophe!'::text),
(394180,43798,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Літак, ... постачає це село, — їхня єдина надія. Без нього — катастрофа!'::text,'який'::text,'хто'::text,'чий'::text,'Літак, який постачає це село, — їхня єдина надія. Без нього — катастрофа!'::text),
(394179,43798,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El avión ... abastece este pueblo es su única esperanza. ¡Sin él, desastre!'::text,'que'::text,'quien'::text,'cuyo'::text,'El avión que abastece este pueblo es su única esperanza. ¡Sin él, desastre!'::text),
(394178,43798,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'L''avion ... approvisionne ce village est leur seul espoir. Sans lui, c''est la catastrophe !'::text,'qui'::text,'lequel'::text,'dont'::text,'L''avion qui approvisionne ce village est leur seul espoir. Sans lui, c''est la catastrophe !'::text),
(394181,43798,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu köye ikmal ... uçak onların tek umudu. O olmazsa felaket!'::text,'yapan'::text,'yapan'::text,'yapan'::text,'Bu köye ikmal yapan uçak onların tek umudu. O olmazsa felaket!'::text),
(394182,43798,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A gép, ... ellátja ezt a falut, az egyetlen reményük. Nélküle katasztrófa!'::text,'amely'::text,'aki'::text,'amelynek'::text,'A gép, amely ellátja ezt a falut, az egyetlen reményük. Nélküle katasztrófa!'::text),
(348708,38746,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ihre Dosis Tropfen für Tropfen ab, als das Öl zu wirbeln begann.'::text,'zählte gerade'::text,'zählte'::text,'zählte'::text,'Sie zählte gerade ihre Dosis Tropfen für Tropfen ab, als das Öl zu wirbeln begann.'::text),
(348712,38746,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ... свою дозу крапля за краплею, коли олія почала закручуватися.'::text,'відраховувала'::text,'відрахувала'::text,'відрахувала'::text,'Вона відраховувала свою дозу крапля за краплею, коли олія почала закручуватися.'::text),
(348711,38746,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... su dosis gota a gota cuando el aceite empezó a arremolinarse.'::text,'Estaba contando'::text,'Contó'::text,'Ha contado'::text,'Estaba contando su dosis gota a gota cuando el aceite empezó a arremolinarse.'::text),
(348710,38746,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle ... sa dose goutte à goutte quand l''huile a commencé à tourbillonner.'::text,'comptait'::text,'a compté'::text,'a compté'::text,'Elle comptait sa dose goutte à goutte quand l''huile a commencé à tourbillonner.'::text),
(348713,38746,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yağ girdap gibi dönmeye başladığında dozunu damla damla ...'::text,'sayıyordu'::text,'saydı'::text,'saymış'::text,'Yağ girdap gibi dönmeye başladığında dozunu damla damla sayıyordu.'::text),
(348714,38746,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp ... az adagját cseppenként, amikor az olaj örvényleni kezdett.'::text,'számolta ki'::text,'kiszámolta'::text,'kiszámolta'::text,'Épp számolta ki az adagját cseppenként, amikor az olaj örvényleni kezdett.'::text),
(348726,38748,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie hielt die Pipette, als der erste Tropfen der Dosis ins Wasser ...'::text,'fiel'::text,'gerade fiel'::text,'gefallen ist'::text,'Sie hielt die Pipette, als der erste Tropfen der Dosis ins Wasser fiel.'::text),
(348730,38748,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона тримала піпетку, коли перша крапля дози ... у воду.'::text,'впала'::text,'падала'::text,'впала'::text,'Вона тримала піпетку, коли перша крапля дози впала у воду.'::text),
(348729,38748,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sostenía la pipeta cuando la primera gota de la dosis ... al agua.'::text,'cayó'::text,'estaba cayendo'::text,'ha caído'::text,'Sostenía la pipeta cuando la primera gota de la dosis cayó al agua.'::text),
(348728,38748,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle tenait la pipette quand la première goutte de la dose ... dans l''eau.'::text,'est tombée'::text,'tombait'::text,'est tombée'::text,'Elle tenait la pipette quand la première goutte de la dose est tombée dans l''eau.'::text),
(348731,38748,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dozun ilk damlası suya ... pipeti tutuyordu.'::text,'düştüğünde'::text,'düşerken'::text,'düşmüşken'::text,'Dozun ilk damlası suya düştüğünde pipeti tutuyordu.'::text),
(348732,38748,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp a pipettát tartotta, amikor az adag első cseppje a vízbe ...'::text,'cseppent'::text,'éppen cseppent'::text,'cseppent'::text,'Épp a pipettát tartotta, amikor az adag első cseppje a vízbe cseppent.'::text),
(348735,38749,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Die Versuchsperson ... genau zehn Tropfen abgegeben, die ihre Tagesdosis bilden.'::text,'hat'::text,'hat'::text,'hat'::text,'Die Versuchsperson hat genau zehn Tropfen abgegeben, die ihre Tagesdosis bilden.'::text),
(348739,38749,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Досліджувана ... рівно десять крапель, які становлять її добову дозу.'::text,'випустила'::text,'випускала'::text,'випускає'::text,'Досліджувана випустила рівно десять крапель, які становлять її добову дозу.'::text),
(348738,38749,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'El sujeto ... exactamente diez gotas, que constituyen su dosis diaria.'::text,'ha liberado'::text,'ha estado liberando'::text,'libera'::text,'El sujeto ha liberado exactamente diez gotas, que constituyen su dosis diaria.'::text),
(348737,38749,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le sujet ... exactement dix gouttes, qui constituent sa dose quotidienne.'::text,'a libéré'::text,'libère'::text,'libère'::text,'Le sujet a libéré exactement dix gouttes, qui constituent sa dose quotidienne.'::text),
(348740,38749,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Denek, günlük dozunu oluşturan tam on damla ...'::text,'bıraktı'::text,'bırakıyor'::text,'bırakır'::text,'Denek, günlük dozunu oluşturan tam on damla bıraktı.'::text),
(348741,38749,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az alany pontosan tíz cseppet ..., amelyek a napi adagját alkotják.'::text,'engedett ki'::text,'engedett ki'::text,'enged ki'::text,'Az alany pontosan tíz cseppet engedett ki, amelyek a napi adagját alkotják.'::text),
(348744,38750,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du ... jeden Tropfen der Dosis gezählt, bevor du das Glas genommen hast. Respekt.'::text,'hattest'::text,'hast'::text,'hast'::text,'Du hattest jeden Tropfen der Dosis gezählt, bevor du das Glas genommen hast. Respekt.'::text),
(348748,38750,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти ... кожну краплю дози, перш ніж узяла склянку. Респект.'::text,'порахувала'::text,'порахувала'::text,'рахуєш'::text,'Ти порахувала кожну краплю дози, перш ніж узяла склянку. Респект.'::text),
(348747,38750,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... cada gota de la dosis antes de coger el vaso. Respeto.'::text,'Habías contado'::text,'Has contado'::text,'Cuentas'::text,'Habías contado cada gota de la dosis antes de coger el vaso. Respeto.'::text),
(348746,38750,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu ... chaque goutte de la dose avant de prendre le verre. Respect.'::text,'avais compté'::text,'as compté'::text,'comptes'::text,'Tu avais compté chaque goutte de la dose avant de prendre le verre. Respect.'::text),
(348749,38750,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bardağı almadan önce dozun her damlasını ... — saygı.'::text,'saymıştın'::text,'saydın'::text,'sayıyorsun'::text,'Bardağı almadan önce dozun her damlasını saymıştın — saygı.'::text),
(348750,38750,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Minden egyes cseppet ... az adagból, mielőtt felvetted a poharat. Respekt.'::text,'megszámoltál'::text,'megszámoltál'::text,'számolsz'::text,'Minden egyes cseppet megszámoltál az adagból, mielőtt felvetted a poharat. Respekt.'::text),
(348753,38751,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du bist jemand, ... jeden einzelnen Tropfen einer Dosis zählt. Ikonisch.'::text,'der'::text,'was'::text,'dessen'::text,'Du bist jemand, der jeden einzelnen Tropfen einer Dosis zählt. Ikonisch.'::text),
(348757,38751,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти з тих, ... рахує кожну краплю дози. Легендарно.'::text,'хто'::text,'що'::text,'чий'::text,'Ти з тих, хто рахує кожну краплю дози. Легендарно.'::text),
(348756,38751,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eres alguien ... cuenta cada gota de una dosis. Icónico.'::text,'que'::text,'lo cual'::text,'cuyo'::text,'Eres alguien que cuenta cada gota de una dosis. Icónico.'::text),
(348755,38751,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'T''es quelqu''un ... compte chaque goutte d''une dose. Iconique.'::text,'qui'::text,'lequel'::text,'dont'::text,'T''es quelqu''un qui compte chaque goutte d''une dose. Iconique.'::text),
(348758,38751,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bir dozun her damlasını ... birisin. İkonik.'::text,'sayan'::text,'sayan'::text,'sayan'::text,'Bir dozun her damlasını sayan birisin. İkonik.'::text),
(348759,38751,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Te olyan vagy, ... minden egyes cseppet megszámol az adagból. Ikonikus.'::text,'aki'::text,'ami'::text,'akinek'::text,'Te olyan vagy, aki minden egyes cseppet megszámol az adagból. Ikonikus.'::text),
(348762,38752,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Du hast mir gesagt, deine Dosis ... zwölf Tropfen, und ehrlich, du hast jeden gezählt.'::text,'war'::text,'ist'::text,'wird'::text,'Du hast mir gesagt, deine Dosis war zwölf Tropfen, und ehrlich, du hast jeden gezählt.'::text),
(348766,38752,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ти сказала мені, що твоя доза ... дванадцять крапель, і чесно, ти порахувала кожну.'::text,'становила'::text,'становить'::text,'становитиме'::text,'Ти сказала мені, що твоя доза становила дванадцять крапель, і чесно, ти порахувала кожну.'::text),
(348765,38752,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Me dijiste que tu dosis ... doce gotas y, sinceramente, contaste cada una.'::text,'era de'::text,'es de'::text,'será de'::text,'Me dijiste que tu dosis era de doce gotas y, sinceramente, contaste cada una.'::text),
(348764,38752,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tu m''as dit que ta dose ... douze gouttes, et franchement, tu les as toutes comptées.'::text,'était de'::text,'est de'::text,'sera de'::text,'Tu m''as dit que ta dose était de douze gouttes, et franchement, tu les as toutes comptées.'::text),
(348767,38752,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bana dozunun on iki damla ... söyledin ve açıkçası her birini saydın.'::text,'olduğunu'::text,'olduğunu'::text,'olacağını'::text,'Bana dozunun on iki damla olduğunu söyledin ve açıkçası her birini saydın.'::text),
(348768,38752,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondtad, hogy az adagod ... tizenkét csepp, és őszintén, mindet megszámoltad.'::text,'volt'::text,NULL::text,'lesz'::text,'Azt mondtad, hogy az adagod volt tizenkét csepp, és őszintén, mindet megszámoltad.'::text),
(348771,38753,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Früher ... ihre Dosis ein Tropfen. Jetzt ist es ein ganzes Glas voller Wirbel. Toller Fortschritt.'::text,'war'::text,'wäre'::text,'war'::text,'Früher war ihre Dosis ein Tropfen. Jetzt ist es ein ganzes Glas voller Wirbel. Toller Fortschritt.'::text),
(348775,38753,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Раніше її доза ... одна крапля. Тепер це ціла склянка вихорів. Чудовий прогрес.'::text,'була'::text,'була б'::text,'звикла бути'::text,'Раніше її доза була одна крапля. Тепер це ціла склянка вихорів. Чудовий прогрес.'::text),
(348774,38753,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Su dosis ... ser una gota. Ahora es un vaso entero de remolinos. Gran progreso.'::text,'solía'::text,'solía'::text,'estaba acostumbrada a'::text,'Su dosis solía ser una gota. Ahora es un vaso entero de remolinos. Gran progreso.'::text),
(348773,38753,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Avant, sa dose ... d''une goutte. Maintenant, c''est tout un verre de tourbillons. Super progrès.'::text,'était'::text,'serait'::text,'avait l''habitude d''être'::text,'Avant, sa dose était d''une goutte. Maintenant, c''est tout un verre de tourbillons. Super progrès.'::text),
(348776,38753,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Eskiden dozu sadece bir damla ..., şimdi koca bir bardak girdap. Harika ilerleme.'::text,'olurdu'::text,'olurdu'::text,'olmaya alışkındı'::text,'Eskiden dozu sadece bir damla olurdu, şimdi koca bir bardak girdap. Harika ilerleme.'::text),
(348777,38753,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Az adagja régen ... egy csepp. Most egy egész pohárnyi örvény. Nagyszerű fejlődés.'::text,'volt'::text,'lett volna'::text,'szokott lenni'::text,'Az adagja régen volt egy csepp. Most egy egész pohárnyi örvény. Nagyszerű fejlődés.'::text),
(348780,38754,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie vergisst nie, ihre Dosis ... – ganz klar die spannendste Morgenroutine.'::text,'zu nehmen'::text,'zu nehmen'::text,'nehmen'::text,'Sie vergisst nie, ihre Dosis zu nehmen – ganz klar die spannendste Morgenroutine.'::text),
(348784,38754,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона ніколи не забуває ... свою дозу. Очевидно, найзахопливіша ранкова рутина.'::text,'прийняти'::text,'приймати'::text,'прийняти'::text,'Вона ніколи не забуває прийняти свою дозу. Очевидно, найзахопливіша ранкова рутина.'::text),
(348783,38754,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca se olvida de ... su dosis. Claramente la rutina matutina más emocionante.'::text,'tomar'::text,'tomar'::text,'tomar'::text,'Nunca se olvida de tomar su dosis. Claramente la rutina matutina más emocionante.'::text),
(348782,38754,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle n''oublie jamais de ... sa dose. Clairement la routine matinale la plus palpitante.'::text,'prendre'::text,'prendre'::text,'prendre'::text,'Elle n''oublie jamais de prendre sa dose. Clairement la routine matinale la plus palpitante.'::text),
(348785,38754,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dozunu ... asla unutmaz. Belli ki en heyecan verici sabah rutini.'::text,'almayı'::text,'almayı'::text,'almayı'::text,'Dozunu almayı asla unutmaz. Belli ki en heyecan verici sabah rutini.'::text),
(348786,38754,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha nem felejti el ... az adagját. Egyértelműen a legizgalmasabb reggeli rutin.'::text,'bevenni'::text,'bevenni'::text,'bevenni'::text,'Soha nem felejti el bevenni az adagját. Egyértelműen a legizgalmasabb reggeli rutin.'::text),
(348789,38755,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie ... ihre Dosis gerade Tropfen für Tropfen ab. Ganz klar ein schneller Prozess.'::text,'misst'::text,'misst'::text,'maß'::text,'Sie misst ihre Dosis gerade Tropfen für Tropfen ab. Ganz klar ein schneller Prozess.'::text),
(348793,38755,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона саме зараз ... свою дозу крапля за краплею. Очевидно, швидкий процес.'::text,'відміряє'::text,'відміряє'::text,'відміряла'::text,'Вона саме зараз відміряє свою дозу крапля за краплею. Очевидно, швидкий процес.'::text),
(348792,38755,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ahora mismo ... su dosis gota a gota. Claramente un proceso rápido.'::text,'está midiendo'::text,'mide'::text,'ha medido'::text,'Ahora mismo está midiendo su dosis gota a gota. Claramente un proceso rápido.'::text),
(348791,38755,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Là, tout de suite, elle ... sa dose goutte à goutte. Clairement un processus rapide.'::text,'mesure'::text,'mesure'::text,'a mesuré'::text,'Là, tout de suite, elle mesure sa dose goutte à goutte. Clairement un processus rapide.'::text),
(348794,38755,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda dozunu damla damla ... — belli ki hızlı bir süreç.'::text,'ölçüyor'::text,'ölçer'::text,'ölçtü'::text,'Şu anda dozunu damla damla ölçüyor — belli ki hızlı bir süreç.'::text),
(348795,38755,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ... ki az adagját cseppenként. Egyértelműen gyors folyamat.'::text,'méri'::text,'méri'::text,'mérte'::text,'Épp most méri ki az adagját cseppenként. Egyértelműen gyors folyamat.'::text),
(388407,43157,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er sagte, er ... am nächsten Tag noch einen Kürbis auf dem Beton.'::text,'zerschmettere'::text,'zerschmettert'::text,'zerschmettert'::text,'Er sagte, er zerschmettere am nächsten Tag noch einen Kürbis auf dem Beton.'::text),
(388411,43157,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він сказав, що наступного дня ... ще один гарбуз об бетон.'::text,'розтрощить'::text,'розтрощить'::text,'трощить'::text,'Він сказав, що наступного дня розтрощить ще один гарбуз об бетон.'::text),
(388410,43157,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Dijo que al día siguiente ... otra calabaza contra el hormigón.'::text,'estrellaría'::text,'estrellará'::text,'estrella'::text,'Dijo que al día siguiente estrellaría otra calabaza contra el hormigón.'::text),
(388409,43157,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a dit qu''il ... une autre citrouille sur le béton le lendemain.'::text,'éclaterait'::text,'éclatera'::text,'éclate'::text,'Il a dit qu''il éclaterait une autre citrouille sur le béton le lendemain.'::text),
(388412,43157,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ertesi gün betona bir balkabağı daha ... söyledi.'::text,'parçalayacağını'::text,'parçalayacağını'::text,'parçaladığını'::text,'Ertesi gün betona bir balkabağı daha parçalayacağını söyledi.'::text),
(388413,43157,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Azt mondta, hogy másnap újabb tököt ... szét a betonon.'::text,'zúz'::text,'fog zúzni'::text,'zúz'::text,'Azt mondta, hogy másnap újabb tököt zúz szét a betonon.'::text),
(388416,43158,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ehrlich gesagt, früher ... du nur Melonen zerschmettert, und jetzt auch Kürbisse? Beeindruckend.'::text,'hast'::text,'hättest'::text,'hast'::text,'Ehrlich gesagt, früher hast du nur Melonen zerschmettert, und jetzt auch Kürbisse? Beeindruckend.'::text),
(388420,43158,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Не буду брехати, раніше ти ... тільки кавуни, а тепер ще й гарбузи? Вражає.'::text,'розбивав'::text,'розбивав би'::text,'звик розбивати'::text,'Не буду брехати, раніше ти розбивав тільки кавуни, а тепер ще й гарбузи? Вражає.'::text),
(388419,43158,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'No te voy a mentir, antes ... reventar solo sandías, ¿y ahora también calabazas? Impresionante.'::text,'solías'::text,'solías'::text,'estabas acostumbrado a'::text,'No te voy a mentir, antes solías reventar solo sandías, ¿y ahora también calabazas? Impresionante.'::text),
(388418,43158,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Je vais pas mentir, avant tu ... seulement des pastèques, et maintenant des citrouilles aussi ? Impressionnant.'::text,'éclatais'::text,'éclatais'::text,'avais l''habitude d''éclater'::text,'Je vais pas mentir, avant tu éclatais seulement des pastèques, et maintenant des citrouilles aussi ? Impressionnant.'::text),
(388421,43158,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Yalan yok, eskiden sadece karpuz ..., şimdi balkabağı da mı? Etkileyici.'::text,'parçalardın'::text,'parçalardın'::text,'parçalamaya alışkındın'::text,'Yalan yok, eskiden sadece karpuz parçalardın, şimdi balkabağı da mı? Etkileyici.'::text),
(388422,43158,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem fogok hazudni, régen csak görögdinnyéket ..., most meg már tököket is? Lenyűgöző.'::text,'zúztál szét'::text,'zúztál volna szét'::text,'szoktál szétzúzni'::text,'Nem fogok hazudni, régen csak görögdinnyéket zúztál szét, most meg már tököket is? Lenyűgöző.'::text),
(388434,43160,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Super gemacht: Der Kürbis ist echt leise zerplatzt, ...'::text,'oder?'::text,'oder?'::text,'oder?'::text,'Super gemacht: Der Kürbis ist echt leise zerplatzt, oder?'::text),
(388438,43160,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Чудова робота: гарбуз розбився дуже тихо, ...'::text,'так?'::text,'так?'::text,'так?'::text,'Чудова робота: гарбуз розбився дуже тихо, так?'::text),
(388437,43160,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Buen trabajo: la calabaza reventó en total silencio, ...'::text,'¿verdad?'::text,'¿verdad?'::text,'¿verdad?'::text,'Buen trabajo: la calabaza reventó en total silencio, ¿verdad?'::text),
(388436,43160,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bravo : la citrouille a éclaté vraiment en silence, ...'::text,'hein ?'::text,'hein ?'::text,'hein ?'::text,'Bravo : la citrouille a éclaté vraiment en silence, hein ?'::text),
(388439,43160,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Harika iş: balkabağı gerçekten çok sessizce parçalandı, ...'::text,'değil mi?'::text,'değil mi?'::text,'değil mi?'::text,'Harika iş: balkabağı gerçekten çok sessizce parçalandı, değil mi?'::text),
(388440,43160,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Szép munka: a tök tényleg nagyon csendben loccsant szét, ...'::text,'ugye?'::text,'ugye?'::text,'ugye?'::text,'Szép munka: a tök tényleg nagyon csendben loccsant szét, ugye?'::text),
(388443,43161,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ganz klar ein ruhiger Nachmittag: Die Melone ist zerplatzt, und ...'::text,'der Kürbis auch'::text,'der Kürbis auch'::text,'der Kürbis auch'::text,'Ganz klar ein ruhiger Nachmittag: Die Melone ist zerplatzt, und der Kürbis auch.'::text),
(388447,43161,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Очевидно, спокійний день: кавун розбився, і ...'::text,'гарбуз теж'::text,'гарбуз теж'::text,'гарбуз теж'::text,'Очевидно, спокійний день: кавун розбився, і гарбуз теж.'::text),
(388446,43161,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Claramente una tarde tranquila: la sandía reventó, y ...'::text,'la calabaza también'::text,'la calabaza también'::text,'la calabaza también'::text,'Claramente una tarde tranquila: la sandía reventó, y la calabaza también.'::text),
(388445,43161,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Clairement un après-midi calme : la pastèque a éclaté, et ...'::text,'la citrouille aussi'::text,'la citrouille aussi'::text,'la citrouille aussi'::text,'Clairement un après-midi calme : la pastèque a éclaté, et la citrouille aussi.'::text),
(388448,43161,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Belli ki sakin bir öğleden sonra: karpuz parçalandı ve ...'::text,'balkabağı da'::text,'balkabağı da'::text,'balkabağı da'::text,'Belli ki sakin bir öğleden sonra: karpuz parçalandı ve balkabağı da.'::text),
(388449,43161,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nyilván nyugis délután: a dinnye szétloccsant, és ...'::text,'a tök is'::text,'a tök is'::text,'a tök is'::text,'Nyilván nyugis délután: a dinnye szétloccsant, és a tök is.'::text),
(388452,43162,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er ... eine Stunde lang Kürbisse, bevor es jemand merkte. Sehr diskret, natürlich.'::text,'zerschmetterte'::text,'zerschmettert'::text,'zerschmetterte'::text,'Er zerschmetterte eine Stunde lang Kürbisse, bevor es jemand merkte. Sehr diskret, natürlich.'::text),
(388456,43162,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він ... гарбузи цілу годину, перш ніж хтось помітив. Дуже непомітно, звісно.'::text,'трощив'::text,'трощить'::text,'трощив'::text,'Він трощив гарбузи цілу годину, перш ніж хтось помітив. Дуже непомітно, звісно.'::text),
(388455,43162,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'... calabazas durante una hora antes de que nadie se diera cuenta. Muy discreto, obviamente.'::text,'Había estado reventando'::text,'Ha estado reventando'::text,'Estaba reventando'::text,'Había estado reventando calabazas durante una hora antes de que nadie se diera cuenta. Muy discreto, obviamente.'::text),
(388454,43162,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il ... des citrouilles depuis une heure quand quelqu''un l''a remarqué. Très discret, évidemment.'::text,'éclatait'::text,'éclate'::text,'éclatait'::text,'Il éclatait des citrouilles depuis une heure quand quelqu''un l''a remarqué. Très discret, évidemment.'::text),
(388457,43162,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Biri fark edene kadar bir saat boyunca balkabağı ... — çok gizli, tabii ki.'::text,'parçalıyordu'::text,'parçalıyor'::text,'parçalıyordu'::text,'Biri fark edene kadar bir saat boyunca balkabağı parçalıyordu — çok gizli, tabii ki.'::text),
(388458,43162,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Egy órán át ... a tököket, mielőtt bárki észrevette. Nagyon diszkrét, nyilván.'::text,'zúzta'::text,'zúzza'::text,'zúzta'::text,'Egy órán át zúzta a tököket, mielőtt bárki észrevette. Nagyon diszkrét, nyilván.'::text),
(388461,43163,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Sonnenuntergang ... er jeden einzelnen Kürbis der Stadt zerschmettert haben! Totale Katastrophe!'::text,'wird'::text,'wird'::text,'wird'::text,'Bis Sonnenuntergang wird er jeden einzelnen Kürbis der Stadt zerschmettert haben! Totale Katastrophe!'::text),
(388465,43163,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До заходу сонця він ... кожен гарбуз у місті! Повна катастрофа!'::text,'розтрощить'::text,'розтрощить'::text,'трощитиме'::text,'До заходу сонця він розтрощить кожен гарбуз у місті! Повна катастрофа!'::text),
(388464,43163,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Para el atardecer ... todas y cada una de las calabazas de la ciudad! ¡Desastre total!'::text,'habrá reventado'::text,'reventará'::text,'estará reventando'::text,'¡Para el atardecer habrá reventado todas y cada una de las calabazas de la ciudad! ¡Desastre total!'::text),
(388463,43163,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici le coucher du soleil, il ... chaque citrouille de la ville ! Catastrophe totale !'::text,'aura éclaté'::text,'éclatera'::text,'sera en train d''éclater'::text,'D''ici le coucher du soleil, il aura éclaté chaque citrouille de la ville ! Catastrophe totale !'::text),
(388466,43163,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gün batımına kadar şehirdeki her bir balkabağını ...! Tam bir felaket!'::text,'parçalamış olacak'::text,'parçalayacak'::text,'parçalıyor olacak'::text,'Gün batımına kadar şehirdeki her bir balkabağını parçalamış olacak! Tam bir felaket!'::text),
(388467,43163,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Napnyugtáig a város összes tökét ...! Teljes katasztrófa!'::text,'szétzúzza'::text,'szét fogja zúzni'::text,'zúzni fogja'::text,'Napnyugtáig a város összes tökét szétzúzza! Teljes katasztrófa!'::text),
(388470,43164,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Um 18 Uhr ... er schon seit drei Stunden Obst von diesem Dach zerschmettern! Ein Albtraum!'::text,'wird'::text,'wird'::text,'wird'::text,'Um 18 Uhr wird er schon seit drei Stunden Obst von diesem Dach zerschmettern! Ein Albtraum!'::text),
(388474,43164,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'О шостій вечора він уже три години ... фрукти з цього даху! Жах!'::text,'трощитиме'::text,'трощитиме'::text,'розтрощить'::text,'О шостій вечора він уже три години трощитиме фрукти з цього даху! Жах!'::text),
(388473,43164,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡A las 6 de la tarde ... fruta desde este tejado durante tres horas! ¡Una pesadilla!'::text,'habrá estado estrellando'::text,'estará estrellando'::text,'estrellará'::text,'¡A las 6 de la tarde habrá estado estrellando fruta desde este tejado durante tres horas! ¡Una pesadilla!'::text),
(388472,43164,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'À 18 h, ça fera trois heures qu''il ... des fruits depuis ce toit ! Un cauchemar !'::text,'éclate'::text,'éclate'::text,'éclatera'::text,'À 18 h, ça fera trois heures qu''il éclate des fruits depuis ce toit ! Un cauchemar !'::text),
(388475,43164,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Akşam 6''ya kadar bu çatıdan üç saat boyunca meyve ...! Tam bir kâbus!'::text,'parçalıyor olacak'::text,'parçalıyor olacak'::text,'parçalayacak'::text,'Akşam 6''ya kadar bu çatıdan üç saat boyunca meyve parçalıyor olacak! Tam bir kâbus!'::text),
(388476,43164,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Este 6-ra már három órája ... a gyümölcsöt erről a tetőről! Rémálom!'::text,'fogja zúzni'::text,'fogja zúzni'::text,'szétzúzza'::text,'Este 6-ra már három órája fogja zúzni a gyümölcsöt erről a tetőről! Rémálom!'::text),
(388488,43166,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Der Kürbis soll von dem jungen Mann auf dem Beton ...'::text,'zerschmettert worden sein'::text,'zerschmettern'::text,'zerschmetternd'::text,'Der Kürbis soll von dem jungen Mann auf dem Beton zerschmettert worden sein.'::text),
(388492,43166,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вважається, що гарбуз об бетон ... молодий чоловік.'::text,'розбив'::text,'розіб''є'::text,'розбиття'::text,'Вважається, що гарбуз об бетон розбив молодий чоловік.'::text),
(388491,43166,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Se cree que la calabaza ... contra el hormigón por el joven.'::text,'fue estrellada'::text,'estrellar'::text,'estrellando'::text,'Se cree que la calabaza fue estrellada contra el hormigón por el joven.'::text),
(388490,43166,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'On pense que la citrouille ... sur le béton par le jeune homme.'::text,'a été éclatée'::text,'éclater'::text,'éclatant'::text,'On pense que la citrouille a été éclatée sur le béton par le jeune homme.'::text),
(388493,43166,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Balkabağının genç adam tarafından betona ... düşünülüyor.'::text,'çarpılıp parçalandığı'::text,'parçalamak'::text,'parçalayarak'::text,'Balkabağının genç adam tarafından betona çarpılıp parçalandığı düşünülüyor.'::text),
(388494,43166,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Úgy tartják, hogy a tököt a fiatalember ... a betonon.'::text,'zúzta szét'::text,'zúzza szét'::text,'szétzúzva'::text,'Úgy tartják, hogy a tököt a fiatalember zúzta szét a betonon.'::text),
(388497,43167,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Er gab zu, das Obst absichtlich ...'::text,'zerschmettert zu haben'::text,'zu zerschmettern'::text,'zerschmettert'::text,'Er gab zu, das Obst absichtlich zerschmettert zu haben.'::text),
(388501,43167,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Він визнав, що ... фрукти навмисно.'::text,'розтрощив'::text,'розтрощити'::text,'розтрощив'::text,'Він визнав, що розтрощив фрукти навмисно.'::text),
(388500,43167,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Admitió ... la fruta a propósito.'::text,'haber reventado'::text,'reventar'::text,'reventó'::text,'Admitió haber reventado la fruta a propósito.'::text),
(388499,43167,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Il a avoué ... les fruits exprès.'::text,'avoir éclaté'::text,'éclater'::text,'éclaté'::text,'Il a avoué avoir éclaté les fruits exprès.'::text),
(388502,43167,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Meyveyi bilerek ... itiraf etti.'::text,'parçaladığını'::text,'parçalamayı'::text,'parçaladı'::text,'Meyveyi bilerek parçaladığını itiraf etti.'::text),
(388503,43167,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Beismerte, hogy szándékosan ... a gyümölcsöt.'::text,'zúzta szét'::text,'szétzúzni'::text,'szétzúzta'::text,'Beismerte, hogy szándékosan zúzta szét a gyümölcsöt.'::text),
(388533,43171,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Das Tuch ... fantastisch gerochen haben, natürlich, weil sie die Augen geschlossen hat.'::text,'muss'::text,'kann nicht'::text,'sollte'::text,'Das Tuch muss fantastisch gerochen haben, natürlich, weil sie die Augen geschlossen hat.'::text),
(388537,43171,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Тканина ... пахла неймовірно, звісно, бо вона заплющила очі.'::text,'напевно'::text,'ніяк не'::text,'мала б'::text,'Тканина напевно пахла неймовірно, звісно, бо вона заплющила очі.'::text),
(388536,43171,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'La tela ... olido de maravilla, obviamente, porque cerró los ojos.'::text,'debe de haber'::text,'no puede haber'::text,'debería haber'::text,'La tela debe de haber olido de maravilla, obviamente, porque cerró los ojos.'::text),
(388535,43171,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Le tissu ... sentir super bon, évidemment, puisqu''elle a fermé les yeux.'::text,'devait'::text,'ne pouvait pas'::text,'aurait dû'::text,'Le tissu devait sentir super bon, évidemment, puisqu''elle a fermé les yeux.'::text),
(388538,43171,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kumaş muhteşem ..., tabii ki, çünkü gözlerini kapattı.'::text,'kokmuş olmalı'::text,'kokmuş olamaz'::text,'kokmalıydı'::text,'Kumaş muhteşem kokmuş olmalı, tabii ki, çünkü gözlerini kapattı.'::text),
(388539,43171,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'A kendő ... csodálatos illatú volt, nyilván, mert behunyta a szemét.'::text,'biztosan'::text,'nem lehet, hogy'::text,'kellett volna, hogy'::text,'A kendő biztosan csodálatos illatú volt, nyilván, mert behunyta a szemét.'::text),
(388542,43172,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nie ... etwas so Frisches wie diese Wäsche gerochen. Es ist absolut unglaublich!'::text,'hat sie'::text,'hat sie'::text,'roch sie'::text,'Nie hat sie etwas so Frisches wie diese Wäsche gerochen. Es ist absolut unglaublich!'::text),
(388546,43172,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ніколи ... нічого настільки свіжого, як ця білизна. Це абсолютно неймовірно!'::text,'вона не відчувала'::text,'вона не відчувала'::text,'вона не відчувала'::text,'Ніколи вона не відчувала нічого настільки свіжого, як ця білизна. Це абсолютно неймовірно!'::text),
(388545,43172,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nunca ... nada tan fresco como esta ropa. ¡Es absolutamente increíble!'::text,'ha olido'::text,'ha olido'::text,'olió'::text,'Nunca ha olido nada tan fresco como esta ropa. ¡Es absolutamente increíble!'::text),
(388544,43172,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Jamais ... d''aussi frais que ce linge. C''est absolument incroyable !'::text,'elle n''a rien senti'::text,'elle n''a rien senti'::text,'elle ne sentit rien'::text,'Jamais elle n''a rien senti d''aussi frais que ce linge. C''est absolument incroyable !'::text),
(388547,43172,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bu çamaşır kadar taze bir şey hiç ... — kesinlikle inanılmaz!'::text,'koklamamıştı'::text,'koklamamıştı'::text,'koklamadı'::text,'Bu çamaşır kadar taze bir şey hiç koklamamıştı — kesinlikle inanılmaz!'::text),
(388548,43172,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Soha ... még ilyen friss illatot, mint ez a mosott ruha. Ez teljesen hihetetlen!'::text,'nem érzett'::text,'nem érzett'::text,'nem érzett'::text,'Soha nem érzett még ilyen friss illatot, mint ez a mosott ruha. Ez teljesen hihetetlen!'::text),
(388551,43173,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie weigert sich, ihre Hemden jemals wieder in einer Wäscherei ... zu lassen! Sie riechen nie nach Meer!'::text,'waschen'::text,'waschen'::text,'waschen'::text,'Sie weigert sich, ihre Hemden jemals wieder in einer Wäscherei waschen zu lassen! Sie riechen nie nach Meer!'::text),
(388555,43173,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона більше ніколи не хоче, щоб її сорочки ... в пральні! Вони ніколи не пахнуть морем!'::text,'прали'::text,'прали'::text,'прали'::text,'Вона більше ніколи не хоче, щоб її сорочки прали в пральні! Вони ніколи не пахнуть морем!'::text),
(388554,43173,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'¡Se niega a volver a mandar a ... sus camisas a una lavandería! ¡Nunca huelen a mar!'::text,'lavar'::text,'lavar'::text,'lavar'::text,'¡Se niega a volver a mandar a lavar sus camisas a una lavandería! ¡Nunca huelen a mar!'::text),
(388553,43173,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle refuse de faire ... ses chemises par une laverie, plus jamais ! Elles ne sentent jamais la mer !'::text,'laver'::text,'laver'::text,'laver'::text,'Elle refuse de faire laver ses chemises par une laverie, plus jamais ! Elles ne sentent jamais la mer !'::text),
(388556,43173,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gömleklerini bir daha asla çamaşırhanede ... reddediyor! Hiç deniz kokmuyorlar!'::text,'yıkatmayı'::text,'yıkatmayı'::text,'yıkatmayı'::text,'Gömleklerini bir daha asla çamaşırhanede yıkatmayı reddediyor! Hiç deniz kokmuyorlar!'::text),
(388557,43173,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nem hajlandó többé mosodában ... az ingeit! Soha nincs tengerillatuk!'::text,'mosatni'::text,'mosatni'::text,'mosatni'::text,'Nem hajlandó többé mosodában mosatni az ingeit! Soha nincs tengerillatuk!'::text),
(388560,43174,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Schatz, sie hat mir erzählt, sie wünschte, ihre Wohnung ... wie diese Wäsche.'::text,'röche'::text,'riecht'::text,'wird riechen'::text,'Schatz, sie hat mir erzählt, sie wünschte, ihre Wohnung röche wie diese Wäsche.'::text),
(388564,43174,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Подруго, вона сказала мені, що хотіла б, щоб її квартира ... як та білизна.'::text,'пахла'::text,'пахне'::text,'пахнутиме'::text,'Подруго, вона сказала мені, що хотіла б, щоб її квартира пахла як та білизна.'::text),
(388563,43174,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tía, me dijo que ojalá su piso ... como esa ropa.'::text,'oliera'::text,'huele'::text,'olerá'::text,'Tía, me dijo que ojalá su piso oliera como esa ropa.'::text),
(388562,43174,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Ma belle, elle m''a dit qu''elle aimerait que son appart ... comme ce linge.'::text,'sente'::text,'sent'::text,'sentira'::text,'Ma belle, elle m''a dit qu''elle aimerait que son appart sente comme ce linge.'::text),
(388565,43174,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Kızım, bana dediğine göre keşke evi o çamaşırlar gibi ... diyormuş.'::text,'koksa'::text,'kokuyor'::text,'kokacak'::text,'Kızım, bana dediğine göre keşke evi o çamaşırlar gibi koksa diyormuş.'::text),
(388566,43174,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Csajszi, azt mondta, bárcsak a lakása olyan illatú ..., mint az a ruha.'::text,'lenne'::text,NULL::text,'lesz'::text,'Csajszi, azt mondta, bárcsak a lakása olyan illatú lenne, mint az a ruha.'::text),
(388578,43176,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie riecht an dem Tuch, ... zu prüfen, ob es wirklich sauber ist.'::text,'um'::text,'damit'::text,'falls'::text,'Sie riecht an dem Tuch, um zu prüfen, ob es wirklich sauber ist.'::text),
(388582,43176,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона нюхає тканину, ... перевірити, чи вона справді чиста.'::text,'щоб'::text,'щоб'::text,'на випадок, якщо'::text,'Вона нюхає тканину, щоб перевірити, чи вона справді чиста.'::text),
(388581,43176,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Huele la tela ... comprobar que está realmente limpia.'::text,'para'::text,'para que'::text,'por si'::text,'Huele la tela para comprobar que está realmente limpia.'::text),
(388580,43176,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle sent le tissu ... vérifier qu''il est vraiment propre.'::text,'pour'::text,'pour que'::text,'au cas où'::text,'Elle sent le tissu pour vérifier qu''il est vraiment propre.'::text),
(388583,43176,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerçekten temiz olup olmadığını kontrol etmek ... kumaşı kokluyor.'::text,'için'::text,'için'::text,'ihtimaline karşı'::text,'Gerçekten temiz olup olmadığını kontrol etmek için kumaşı kokluyor.'::text),
(388584,43176,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Megszagolja a kendőt, ... ellenőrizze, tényleg tiszta-e.'::text,'hogy'::text,'hogy'::text,'arra az esetre, ha'::text,'Megszagolja a kendőt, hogy ellenőrizze, tényleg tiszta-e.'::text),
(388587,43177,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sie wusste, dass die Wäsche nach einem Tag in der Sonne frisch ...'::text,'riechen würde'::text,'riechen wird'::text,'riecht'::text,'Sie wusste, dass die Wäsche nach einem Tag in der Sonne frisch riechen würde.'::text),
(388591,43177,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Вона знала, що білизна після дня на сонці ... свіжістю.'::text,'пахнутиме'::text,'пахнутиме'::text,'пахне'::text,'Вона знала, що білизна після дня на сонці пахнутиме свіжістю.'::text),
(388590,43177,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Sabía que la ropa ... a fresco después de un día al sol.'::text,'olería'::text,'olerá'::text,'huele'::text,'Sabía que la ropa olería a fresco después de un día al sol.'::text),
(388589,43177,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Elle savait que le linge ... frais après une journée au soleil.'::text,'sentirait'::text,'sentira'::text,'sent'::text,'Elle savait que le linge sentirait frais après une journée au soleil.'::text),
(388592,43177,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Çamaşırın güneşte geçen bir günden sonra taze ... biliyordu.'::text,'kokacağını'::text,'kokacağını'::text,'koktuğunu'::text,'Çamaşırın güneşte geçen bir günden sonra taze kokacağını biliyordu.'::text),
(388593,43177,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Tudta, hogy a ruha egy napos napozás után friss illatú ...'::text,'lesz'::text,'lesz'::text,NULL::text,'Tudta, hogy a ruha egy napos napozás után friss illatú lesz.'::text),
(388596,43178,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gerade ... sie mit geschlossenen Augen an dem weißen Tuch.'::text,'riecht'::text,'riecht'::text,'roch'::text,'Gerade riecht sie mit geschlossenen Augen an dem weißen Tuch.'::text),
(388600,43178,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Саме зараз вона ... білу тканину із заплющеними очима.'::text,'нюхає'::text,'нюхає'::text,'понюхала'::text,'Саме зараз вона нюхає білу тканину із заплющеними очима.'::text),
(388599,43178,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En este momento ... la tela blanca con los ojos cerrados.'::text,'está oliendo'::text,'huele'::text,'ha olido'::text,'En este momento está oliendo la tela blanca con los ojos cerrados.'::text),
(388598,43178,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'En ce moment, elle ... le tissu blanc les yeux fermés.'::text,'sent'::text,'sent'::text,'a senti'::text,'En ce moment, elle sent le tissu blanc les yeux fermés.'::text),
(388601,43178,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Şu anda gözleri kapalı beyaz kumaşı ...'::text,'kokluyor'::text,'koklar'::text,'kokladı'::text,'Şu anda gözleri kapalı beyaz kumaşı kokluyor.'::text),
(388602,43178,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Épp most ... a fehér kendőt csukott szemmel.'::text,'szagolja'::text,'szagolja'::text,'megszagolta'::text,'Épp most szagolja a fehér kendőt csukott szemmel.'::text),
(388605,43179,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Nachdem sie das Hemd aufgehängt hatte, ... sie an dem weißen Tuch.'::text,'roch'::text,'roch'::text,'roch'::text,'Nachdem sie das Hemd aufgehängt hatte, roch sie an dem weißen Tuch.'::text),
(388609,43179,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Після того як вона повісила сорочку, вона ... білу тканину.'::text,'понюхала'::text,'понюхала'::text,'понюхала'::text,'Після того як вона повісила сорочку, вона понюхала білу тканину.'::text),
(388608,43179,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Después de tender la camisa, ... la tela blanca.'::text,'olió'::text,'había olido'::text,'ha olido'::text,'Después de tender la camisa, olió la tela blanca.'::text),
(388607,43179,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Après avoir étendu la chemise, elle ... le tissu blanc.'::text,'a senti'::text,'avait senti'::text,'a senti'::text,'Après avoir étendu la chemise, elle a senti le tissu blanc.'::text),
(388610,43179,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Gömleği astıktan sonra beyaz kumaşı ...'::text,'kokladı'::text,'koklamıştı'::text,'kokladı'::text,'Gömleği astıktan sonra beyaz kumaşı kokladı.'::text),
(388611,43179,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Miután felakasztotta az inget, ... a fehér kendőt.'::text,'megszagolta'::text,'megszagolta'::text,'megszagolta'::text,'Miután felakasztotta az inget, megszagolta a fehér kendőt.'::text),
(388614,43180,'de',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Bis Mittag ... sie an jedem einzelnen Tuch auf der Leine gerochen haben. Ein sehr voller Vormittag, natürlich.'::text,'wird'::text,'wird'::text,'wird'::text,'Bis Mittag wird sie an jedem einzelnen Tuch auf der Leine gerochen haben. Ein sehr voller Vormittag, natürlich.'::text),
(388618,43180,'ua',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'До обіду вона ... кожну тканину на мотузці. Дуже насичений ранок, звісно.'::text,'понюхає'::text,'понюхає'::text,'нюхає'::text,'До обіду вона понюхає кожну тканину на мотузці. Дуже насичений ранок, звісно.'::text),
(388617,43180,'es',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Para el mediodía ... todas y cada una de las telas del tendedero. Una mañana muy ajetreada, obviamente.'::text,'habrá olido'::text,'olerá'::text,'huele'::text,'Para el mediodía habrá olido todas y cada una de las telas del tendedero. Una mañana muy ajetreada, obviamente.'::text),
(388616,43180,'fr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'D''ici midi, elle ... chaque tissu de la corde à linge. Une matinée très chargée, évidemment.'::text,'aura senti'::text,'sentira'::text,'sent'::text,'D''ici midi, elle aura senti chaque tissu de la corde à linge. Une matinée très chargée, évidemment.'::text),
(388619,43180,'tr',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Öğlene kadar ipteki her bir kumaşı ... — çok yoğun bir sabah, tabii ki.'::text,'koklamış olacak'::text,'koklayacak'::text,'kokluyor'::text,'Öğlene kadar ipteki her bir kumaşı koklamış olacak — çok yoğun bir sabah, tabii ki.'::text),
(388620,43180,'hu',NULL::text,''::text,NULL::text,NULL::text,NULL::text,'Délre ... a szárítókötélen lévő összes kendőt. Nagyon zsúfolt délelőtt, nyilván.'::text,'megszagolja'::text,'meg fogja szagolni'::text,'szagolja'::text,'Délre megszagolja a szárítókötélen lévő összes kendőt. Nagyon zsúfolt délelőtt, nyilván.'::text)
) v(id, eid, lang, n_intro_text, n_correct_answer, n_distractor_1, n_distractor_2, n_full_sentence, o_intro_text, o_correct_answer, o_distractor_1, o_distractor_2, o_full_sentence)
